private val LocalAgentStudioEmbedded = staticCompositionLocalOf { false }

object AgentStudio {
    const val VERSION_NAME = "0.2.0"
    const val WORK_TAG = "agentstudio"
    private val started = java.util.concurrent.atomic.AtomicBoolean(false)
    fun initialize(context: android.content.Context) {
        val app = AgentStudioProfiles.root(context)
        AgentStudioResources.attach(app)
        if (started.compareAndSet(false, true)) {
            try {
                androidx.work.WorkManager.getInstance(app)
                AS_LocalNotifications.LocalNotifications.createChannel(app)
                AgentStudioProfiles.list(app).forEach { agent ->
                    val scoped=AgentStudioProfiles.context(app,agent.id)
                    AS_AndroidAudioRecording.AndroidAudioRecording.cleanPreviousProcess(scoped)
                    AS_RoutineWorker.RoutineWorker.register(scoped)
                    AS_ContinuationWorker.RecoveryWorker.enqueue(scoped)
                }
            } catch (failure: Throwable) { started.set(false); throw failure }
        }
    }
}

/** Add this destination to your existing Compose app. */
@Composable fun AgentStudioScreen(
    modifier: androidx.compose.ui.Modifier = androidx.compose.ui.Modifier,
    onBack: (() -> Unit)? = null,
    notificationUri: String? = null,
    onNotificationConsumed: () -> Unit = {},
    initialAgentId: String? = null,
    displayName: String = "",
) {
    val application = androidx.compose.ui.platform.LocalContext.current.applicationContext as android.app.Application
    remember(application) { AgentStudio.initialize(AgentStudioProfiles.root(application)) }
    AgentStudioExperience(modifier,onBack,notificationUri,onNotificationConsumed,initialAgentId,displayName)
}

/** The host registers this provider once; no XML path resource is required. */
class AgentStudioFileProvider: android.content.ContentProvider() {
    override fun onCreate() = true
    private fun file(uri: android.net.Uri): java.io.File {
        require(uri.authority == requireNotNull(context).packageName + ".agentstudio.files") { "Invalid attachment authority." }
        val segments = uri.pathSegments
        require(segments.size == 2 && segments[1].matches(Regex("[A-Za-z0-9._-]+"))) { "Invalid attachment path." }
        require(AgentStudioProfiles.get(requireNotNull(context),segments[0])!=null) { "This agent was removed." }
        val scoped=AgentStudioProfiles.context(requireNotNull(context),segments[0])
        val root = java.io.File(scoped.filesDir,"agentstudio/attachments").canonicalFile
        val file = java.io.File(root, segments[1]).canonicalFile
        require(file.parentFile == root && file.isFile) { "Attachment is outside the feature's private directory or no longer exists." }
        return file
    }
    override fun openFile(uri: android.net.Uri, mode: String): android.os.ParcelFileDescriptor {
        require(mode == "r") { "Attachments are read-only." }
        return android.os.ParcelFileDescriptor.open(file(uri), android.os.ParcelFileDescriptor.MODE_READ_ONLY)
    }
    override fun query(uri: android.net.Uri, projection: Array<out String>?, selection: String?, selectionArgs: Array<out String>?, sortOrder: String?): android.database.Cursor {
        val file = file(uri)
        val columns = projection ?: arrayOf(android.provider.OpenableColumns.DISPLAY_NAME, android.provider.OpenableColumns.SIZE)
        return android.database.MatrixCursor(columns).apply { addRow(columns.map { column -> when(column) { android.provider.OpenableColumns.DISPLAY_NAME -> uri.getQueryParameter("displayName") ?: file.name; android.provider.OpenableColumns.SIZE -> file.length(); else -> null } }) }
    }
    override fun getType(uri: android.net.Uri): String { file(uri); return android.webkit.MimeTypeMap.getSingleton().getMimeTypeFromExtension((uri.getQueryParameter("displayName") ?: "").substringAfterLast('.', "").lowercase()) ?: "application/octet-stream" }
    override fun insert(uri: android.net.Uri, values: android.content.ContentValues?): android.net.Uri? = throw UnsupportedOperationException("Read-only attachments")
    override fun update(uri: android.net.Uri, values: android.content.ContentValues?, selection: String?, selectionArgs: Array<out String>?): Int = throw UnsupportedOperationException("Read-only attachments")
    override fun delete(uri: android.net.Uri, selection: String?, selectionArgs: Array<out String>?): Int = throw UnsupportedOperationException("Read-only attachments")
    companion object {
        fun getUriForFile(context: android.content.Context, authority: String, file: java.io.File, displayName: String): android.net.Uri {
            require(authority == context.packageName + ".agentstudio.files")
            val root = java.io.File(context.filesDir, "agentstudio/attachments").canonicalFile
            require(file.canonicalFile.parentFile == root && file.isFile) { "Only feature attachments can be shared." }
            return android.net.Uri.Builder().scheme("content").authority(authority).appendPath(requireNotNull(AgentStudioProfiles.id(context))).appendPath(file.name).appendQueryParameter("displayName",displayName).build()
        }
    }
}

/** Optional explicit recovery of original sources; never writes files automatically. */
object AgentStudioOriginalSources {
    const val ARCHIVE_SHA256 = "a27b6aef5786e451caa98942ce2ce3e0ebd493bdc52cc7690581627c088a9f26"
    fun writeTo(directory: java.io.File) {
        val data = AgentStudioResources.originalBytes()
        val hash = java.security.MessageDigest.getInstance("SHA-256").digest(data).joinToString("") { "%02x".format(it.toInt() and 255) }
        check(hash == ARCHIVE_SHA256) { "Original-source archive checksum mismatch." }
        val root = directory.canonicalFile
        java.util.zip.ZipInputStream(data.inputStream()).use { zip ->
            while(true) {
                val entry = zip.nextEntry ?: break
                val file = java.io.File(root,entry.name).canonicalFile
                require(file.toPath().startsWith(root.toPath()))
                if(entry.isDirectory) file.mkdirs() else { file.parentFile?.mkdirs(); file.outputStream().use { zip.copyTo(it) } }
            }
        }
    }
}


