    @Synchronized private fun fontFile(): java.io.File {
        val context = checkNotNull(app) { "Call AgentStudio.initialize(context) before showing its UI." }
        val file = java.io.File(context.cacheDir, "agentstudio-resources/inter.ttf")
        val data = bytes(asset_22)
        if (!file.isFile || file.length() != data.size.toLong()) {
            file.parentFile?.mkdirs()
            val temporary = java.io.File(file.parentFile, "inter.pending")
            temporary.writeBytes(data)
            check(temporary.renameTo(file)) { "Could not prepare the embedded font." }
        }
        return file
    }
