    fun notificationIcon(id: Int): android.graphics.drawable.Icon {
        val value = vector(id)
        val bitmap = android.graphics.Bitmap.createBitmap(72,72,android.graphics.Bitmap.Config.ARGB_8888)
        val canvas = android.graphics.Canvas(bitmap)
        canvas.scale(72/value.width,72/value.height)
        value.paths.forEach { path ->
            val shape = checkNotNull(androidx.core.graphics.PathParser.createPathFromPathData(path.data))
            shape.fillType = if(path.evenOdd) android.graphics.Path.FillType.EVEN_ODD else android.graphics.Path.FillType.WINDING
            val paint = android.graphics.Paint(android.graphics.Paint.ANTI_ALIAS_FLAG)
            if(path.fill != 0L) { paint.style=android.graphics.Paint.Style.FILL;paint.color=path.fill.toInt();canvas.drawPath(shape,paint) }
            if(path.stroke != 0L) { paint.style=android.graphics.Paint.Style.STROKE;paint.color=path.stroke.toInt();paint.strokeWidth=path.strokeWidth;paint.strokeCap=when(path.cap){"round"->android.graphics.Paint.Cap.ROUND;"square"->android.graphics.Paint.Cap.SQUARE;else->android.graphics.Paint.Cap.BUTT};paint.strokeJoin=when(path.join){"round"->android.graphics.Paint.Join.ROUND;"bevel"->android.graphics.Paint.Join.BEVEL;else->android.graphics.Paint.Join.MITER};canvas.drawPath(shape,paint) }
        }
        return android.graphics.drawable.Icon.createWithBitmap(bitmap)
    }
