            withContext(Dispatchers.Main) { onSaved() }
        }

    fun clearLocalData(onCleared: () -> Unit) =
        action {
            val context = getApplication<Application>()
            androidx.work.WorkManager
                .getInstance(AgentStudioProfiles.root(context))
                .cancelAllWorkByTag(AgentStudioProfiles.workTag(context))
                .result
                .get()
            AgentStudioProfiles.gate(getApplication())
                .lock()
            try {
                ai.openbot.agentstudio.AS_LocalDataResetRepository.LocalDataResetRepository(context, store)
                    .clear()
                state.value = AppState(busy = true)
                refresh()
            } finally {
                AgentStudioProfiles.gate(getApplication())
                    .unlock()
            }
            ai.openbot.agentstudio.AS_RoutineWorker.RoutineWorker
                .register(context)
            withContext(Dispatchers.Main) { onCleared() }
        }

