            refresh()
        }

    fun connectMcp(
        id: String?,
        name: String,
        url: String,
        newToken: String?,
        clearToken: Boolean,
        onSaved: () -> Unit,
    ) = action {
        require(name.trim().isNotEmpty() && name.trim().length <= 100) { "Connection name must be 1–100 characters." }
        val endpoint = mcpEndpoint(url).toASCIIString()
        val old = store.connections().find { it.id == id }
        val connectionId = old?.id ?: UUID.randomUUID().toString()
        val token = newToken?.takeIf { it.isNotBlank() }?.trim() ?: if (!clearToken && old?.url == endpoint)old.credentialRef?.let(connectionSecrets::token) else null
        val proposed = LocalConnection(connectionId, name.trim(), endpoint, updatedAt = now())
        val client = McpClient(proposed, token)
        try {
            val serverName = client.initialize()
            val tools = client.listTools()
            val names = tools.map { it.name }.toSet()
            val grants = if (old?.url == endpoint)old.grants.mapValues { (_, held) -> held.filter { it in names } } else emptyMap()
            // Write a new immutable credential slot, then switch SQLite's reference. A failed
            // metadata write must never attach a new endpoint's token to the old endpoint.
            val retained = old?.url == endpoint && !clearToken && newToken.isNullOrBlank() && token != null
            val credentialRef = if (retained)old?.credentialRef else token?.takeIf { it.isNotBlank() }?.let { UUID.randomUUID().toString() }
            try {
                if (!retained)credentialRef?.let { connectionSecrets.save(it, token) }
                store.saveConnection(proposed.copy(serverName = serverName, tools = tools, grants = grants, credentialRef = credentialRef))
            } catch (failure: Exception) {
                if (!retained)credentialRef?.let { runCatching { connectionSecrets.remove(it) } }
                throw failure
            }
            old?.credentialRef?.takeIf { it != credentialRef }?.let { runCatching { connectionSecrets.remove(it) } }
            refresh()
            withContext(Dispatchers.Main) { onSaved() }
        } finally {
            withContext(NonCancellable) { runCatching { client.close() } }
        }
    }

    fun grantConnectionTool(
        connection: LocalConnection,
        botId: String,
        toolName: String,
        enabled: Boolean,
    ) = action {
        val current = store.connections().firstOrNull { it.id == connection.id } ?: error("This connection no longer exists.")
        val granted = current.grants[botId].orEmpty().toMutableSet()
        if (enabled)granted.add(toolName) else granted.remove(toolName)
        store.saveConnection(current.copy(grants = current.grants + (botId to granted.toList())))
        refresh()
    }

    fun disconnectMcp(
        connection: LocalConnection,
        onDeleted: () -> Unit,
    ) = action {
        store.deleteConnection(connection.id)
        connection.credentialRef?.let { connectionSecrets.remove(it) }
        refresh()
        withContext(Dispatchers.Main) { onDeleted() }
    }

    fun stopGeneration() {
        if (state.value.generatingChannelId != null && !state.value.stopping) {
            state.update { it.copy(stopping = true) }
            activeJob?.cancel(CancellationException("Stopped by you."))
        }
    }

    fun loadGoalHistory(id: String?) {
        state.update { it.copy(goalHistoryFor = id, goalRuns = emptyList()) }
        viewModelScope.launch { withContext(Dispatchers.IO) { refresh() } }
    }

    fun saveGoal(
        id: String?,
        botId: String,
        channelId: String,
        title: String,
        instruction: String,
        criteria: String,
        onSaved: () -> Unit,
    ) = action {
        val now = now()
        val existing = id?.let(goalStore::get)
        val goal =
            existing?.copy(title = title, instruction = instruction, successCriteria = criteria, updatedAt = now)
                ?: LocalGoal(UUID.randomUUID().toString(), botId, channelId, title, instruction, criteria, createdAt = now, updatedAt = now)
        goalStore.save(goal)
        refresh()
        withContext(Dispatchers.Main) { onSaved() }
    }

    fun setGoalStatus(
        goal: LocalGoal,
        status: GoalStatus,
    ) = action {
        goalStore.transition(goal.id, status)
        if (status != GoalStatus.ACTIVE) {
            goalStore.runs(goal.id).filter { it.status in listOf(GoalRunStatus.QUEUED, GoalRunStatus.RUNNING) }.forEach { run ->
                if (run.status == GoalRunStatus.QUEUED)goalStore.finish(run.id, GoalRunStatus.SKIPPED, error = "The goal was paused or completed before it ran.")
                androidx.work.WorkManager
                    .getInstance(AgentStudioProfiles.root(getApplication()))
                    .cancelUniqueWork(AgentStudioProfiles.workName(getApplication(), "agentstudio-goal-run:${run.id}"))
            }
            if (status == GoalStatus.COMPLETED) {
                store.checkpoints().filter { checkpoint -> checkpoint.goalRunId?.let(goalStore::run)?.goalId == goal.id }.forEach { checkpoint ->
                    store.interruptContinuation(checkpoint, "The goal was completed. The pending action was not done.", true)
                    checkpoint.goalRunId?.let { goalStore.finish(it, GoalRunStatus.SKIPPED, error = "The goal was completed.") }
                    androidx.work.WorkManager
                        .getInstance(AgentStudioProfiles.root(getApplication()))
                        .cancelUniqueWork(AgentStudioProfiles.workName(getApplication(), "agentstudio-continuation:${checkpoint.turnId}"))
                }
            }
        }
        refresh()
    }

    fun runGoal(goal: LocalGoal) =
        action {
            runtime.checkConfigured()
            goalStore.enqueue(goal.id)
            state.update { it.copy(goalHistoryFor = goal.id) }
            GoalWorker.enqueueQueued(getApplication(), store)
            refresh()
        }

    fun setRoutineEnabled(
        routine: LocalRoutine,
        enabled: Boolean,
    ) = action {
        store.saveRoutine(routine.copy(enabled = enabled))
        refresh()
    }

    fun deleteRoutine(
        routine: LocalRoutine,
        onDeleted: () -> Unit,
    ) = action {
        store.deleteRoutine(routine.id)
        refresh()
        withContext(Dispatchers.Main) { onDeleted() }
    }

    fun runRoutineNow(routine: LocalRoutine) =
        action {
            runtime.checkConfigured()
            val run = requireNotNull(store.startRoutineRun(routine.id, manual = true))
            ai.openbot.agentstudio.AS_RoutineWorker.RoutineWorker
                .enqueueManual(getApplication(), run)
            refresh()
        }

    /** Main-thread gate prevents double taps from scheduling two writes or model generations. */
    private fun action(work: suspend () -> Unit) {
        // The initial state is busy until the initialization coroutine is launched below.
        if (state.value.busy && initialized) return
        initialized = true
        state.value = state.value.copy(busy = true, error = null)
        activeJob =
            viewModelScope.launch {
                try {
                    withContext(Dispatchers.IO) { work() }
                } catch (failure: CancellationException) {
                    throw failure
                } catch (failure: Exception) {
                    state.value = state.value.copy(error = failure.message ?: "Could not complete this action.")
                } finally {
                    state.value = state.value.copy(busy = false)
                }
            }
    }

    override fun onCleared() {
        // Wait for any native inference to finish before releasing native resources and SQLite.
        val finishing = activeJob
        CoroutineScope(SupervisorJob() + Dispatchers.IO).launch {
            try { finishing?.join(); model.close(); store.close() } finally { featureClosed.complete(Unit) }
        }
    }

    private fun now() = Instant.now().toString()
}
}

// ===== ORIGINAL RUNTIME FILE: android/app/src/main/kotlin/ai/openbot/android/background/ContinuationWorker.kt =====
object AS_ContinuationWorker {
@androidx.annotation.Keep
class ContinuationWorker(
    context: Context,
    parameters: WorkerParameters,
) : CoroutineWorker(context, parameters) {
    private val featureContext: Context get() = AgentStudioProfiles.fromWork(applicationContext,inputData)
    override suspend fun doWork(): Result {
        val turnId = inputData.getString("turnId") ?: return Result.failure()
        LocalStore(featureContext).use { store ->
            val checkpoint = store.checkpoints().firstOrNull { it.turnId == turnId && it.phase == ContinuationPhase.QUEUED } ?: return Result.success()
            val model = LocalModel(featureContext)
            try {
                val goals = GoalStore(store)
                checkpoint.goalRunId?.let(goals::resumeWaiting)
                checkpoint.routineRunId?.let(store::resumeRoutineRun)
                val result = AgentRuntime(featureContext, store, model).resume(turnId)
                checkpoint.routineRunId?.let(store::routineRun)?.let { run -> store.finishRoutineRun(run, if (result == TurnOutcome.WAITING)RoutineStatus.WAITING else RoutineStatus.SUCCEEDED) }
                checkpoint.goalRunId?.let { id ->
                    val reply = store.messages(checkpoint.channelId).find { it.id == turnId }?.text
                    goals.finish(id, if (result == TurnOutcome.WAITING)GoalRunStatus.WAITING else GoalRunStatus.SUCCEEDED, reply.takeIf { result == TurnOutcome.COMPLETED })
                }
                return Result.success()
            } catch (failure: CancellationException) {
                store.checkpoints().find { it.turnId == turnId }?.let { store.interruptContinuation(it, "The continuation was interrupted.", true) }
                checkpoint.goalRunId?.let { GoalStore(store).finish(it, GoalRunStatus.SKIPPED, error = "The continuation was interrupted.") }
                checkpoint.routineRunId?.let(store::routineRun)?.let { store.finishRoutineRun(it, RoutineStatus.SKIPPED, "The continuation was interrupted.") }
                throw failure
            } catch (failure: Exception) {
                store.checkpoints().find { it.turnId == turnId }?.let { store.interruptContinuation(it, "Could not continue this turn. ${failure.message.orEmpty()}", false) }
                checkpoint.goalRunId?.let { GoalStore(store).finish(it, GoalRunStatus.FAILED, error = failure.message) }
                checkpoint.routineRunId?.let(store::routineRun)?.let { store.finishRoutineRun(it, RoutineStatus.FAILED, failure.message) }
                return Result.success() // Failure is final and visible; external effects are never retried blindly.
            } finally {
                withContext(NonCancellable) { model.close() }
            }
        }
    }

    companion object {
        fun enqueue(
            context: Context,
            turnId: String,
        ) {
            val request =
                OneTimeWorkRequestBuilder<ContinuationWorker>().addTag(AgentStudio.WORK_TAG).addTag(AgentStudioProfiles.workTag(context)).setInputData(AgentStudioProfiles.workData(context))
                    .setInputData(AgentStudioProfiles.workData(context,workDataOf("turnId" to turnId)))
                    .setConstraints(androidx.work.Constraints.Builder().setRequiredNetworkType(NetworkType.CONNECTED).build())
                    .build()
            WorkManager.getInstance(AgentStudioProfiles.root(context)).enqueueUniqueWork(AgentStudioProfiles.workName(context, "agentstudio-continuation:$turnId"), ExistingWorkPolicy.APPEND_OR_REPLACE, request)
        }
    }
}

/** Recover process death under the same execution gate used by live turns. Pending decisions survive. */
@androidx.annotation.Keep
class RecoveryWorker(
    context: Context,
    parameters: WorkerParameters,
) : CoroutineWorker(context, parameters) {
    private val featureContext: Context get() = AgentStudioProfiles.fromWork(applicationContext,inputData)
    override suspend fun doWork(): Result {
        AgentStudioProfiles.gate(featureContext).lock()
        try {
            LocalStore(featureContext).use { store ->
                store.recoverInterruptedMessages()
                store.recoverContinuations()
                store.reapRoutineRuns()
                ai.openbot.agentstudio.AS_AttachmentStore.AttachmentStore(featureContext, store)
                    .reap()
                store.checkpoints().filter { it.phase == ContinuationPhase.QUEUED }.forEach { ContinuationWorker.enqueue(featureContext, it.turnId) }
                GoalWorker.enqueueQueued(featureContext, store)
                ai.openbot.agentstudio.AS_LocalNotifications.LocalNotifications
                    .sync(featureContext, store)
            }
        } finally {
            AgentStudioProfiles.gate(featureContext).unlock()
        }
        return Result.success()
    }

    companion object {
        fun enqueue(context: Context) {
            WorkManager.getInstance(AgentStudioProfiles.root(context)).enqueueUniqueWork(AgentStudioProfiles.workName(context, "agentstudio-recover"), ExistingWorkPolicy.KEEP, OneTimeWorkRequestBuilder<RecoveryWorker>().addTag(AgentStudio.WORK_TAG).addTag(AgentStudioProfiles.workTag(context)).setInputData(AgentStudioProfiles.workData(context)).build())
        }
    }
}
}

// ===== ORIGINAL RUNTIME FILE: android/app/src/main/kotlin/ai/openbot/android/background/GoalWorker.kt =====
object AS_GoalWorker {
@androidx.annotation.Keep
class GoalWorker(
    context: Context,
    parameters: WorkerParameters,
) : CoroutineWorker(context, parameters) {
    private val featureContext: Context get() = AgentStudioProfiles.fromWork(applicationContext,inputData)
    override suspend fun doWork(): Result {
        val runId = inputData.getString("runId") ?: return Result.failure()
        LocalStore(featureContext).use { store ->
            val goals = GoalStore(store)
            val existing = goals.run(runId) ?: return Result.success()
            // WorkManager can restart its own interrupted job. Never repeat a turn already written.
            if (existing.status == GoalRunStatus.RUNNING) {
                val message = existing.turnId?.let { id -> store.messages(goals.get(existing.goalId).channelId).find { it.id == id } }
                when (message?.state) {
                    MessageState.COMPLETE -> goals.finish(runId, GoalRunStatus.SUCCEEDED, message.text)
                    MessageState.WAITING -> goals.finish(runId, GoalRunStatus.WAITING)
                    null -> goals.requeue(runId)
                    else -> {
                        store.saveMessage(message.copy(state = MessageState.INTERRUPTED, text = "This goal run was interrupted. Check its saved actions before starting another run."))
                        goals.finish(runId, GoalRunStatus.SKIPPED, error = "The previous process ended before the turn finished.")
                    }
                }
                if (message != null)return Result.success()
            }
            if (goals.run(runId)?.status != GoalRunStatus.QUEUED)return Result.success()
            val goal = goals.get(existing.goalId)
            if (store.checkpoints().any { it.channelId == goal.channelId && it.phase in listOf(ContinuationPhase.WAITING, ContinuationPhase.QUEUED, ContinuationPhase.RUNNING) })return Result.retry()
            val run = goals.claim(runId) ?: return Result.success()
            val model = LocalModel(featureContext)
            try {
                val outcome = AgentRuntime(featureContext, store, model).turn(goal.channelId, frameGoal(goal, run.id), goalRunId = run.id)
                val reply = goals.run(runId)?.turnId?.let { id -> store.messages(goal.channelId).find { it.id == id }?.text }
                goals.finish(runId, if (outcome == TurnOutcome.WAITING)GoalRunStatus.WAITING else GoalRunStatus.SUCCEEDED, reply.takeIf { outcome == TurnOutcome.COMPLETED })
                return Result.success()
            } catch (waiting: ConversationWaitingException) {
                goals.requeue(runId)
                return Result.retry()
            } catch (failure: CancellationException) {
                if (goals.run(runId)?.turnId == null) {
                    goals.requeue(runId)
                } else {
                    goals.finish(runId, GoalRunStatus.SKIPPED, error = "The goal run was interrupted.")
                }
                throw failure
            } catch (failure: Exception) {
                goals.finish(runId, if (goals.get(goal.id).status == GoalStatus.ACTIVE)GoalRunStatus.FAILED else GoalRunStatus.SKIPPED, error = failure.message)
                return Result.success()
            } finally {
                withContext(NonCancellable) {
                    model.close()
                    enqueueQueued(featureContext, store)
                }
            }
        }
    }

    companion object {
        fun enqueueQueued(
            context: Context,
            store: LocalStore,
        ) {
            val provider = ModelSettingsStore(context).settings().mode == ModelMode.PROVIDER_API
            GoalStore(store).queuedRuns().forEach { run ->
                val request =
                    OneTimeWorkRequestBuilder<GoalWorker>().addTag(AgentStudio.WORK_TAG).addTag(AgentStudioProfiles.workTag(context)).setInputData(AgentStudioProfiles.workData(context))
                        .setInputData(AgentStudioProfiles.workData(context,workDataOf("runId" to run.id)))
                        .setConstraints(androidx.work.Constraints.Builder().apply { if (provider)setRequiredNetworkType(NetworkType.CONNECTED) }.build())
                        .build()
                WorkManager.getInstance(AgentStudioProfiles.root(context)).enqueueUniqueWork(AgentStudioProfiles.workName(context, "agentstudio-goal-run:${run.id}"), ExistingWorkPolicy.KEEP, request)
            }
        }
    }
}
}

// ===== ORIGINAL RUNTIME FILE: android/app/src/main/kotlin/ai/openbot/android/background/RoutineWorker.kt =====
object AS_RoutineWorker {
/** WorkManager survives process recreation and reboot; Android may defer work while idle. */
@androidx.annotation.Keep
class RoutineWorker(
    context: Context,
    parameters: WorkerParameters,
) : CoroutineWorker(context, parameters) {
    private val featureContext: Context get() = AgentStudioProfiles.fromWork(applicationContext,inputData)
    override suspend fun doWork(): Result {
        LocalStore(featureContext).use { store ->
            val model = LocalModel(featureContext)
            try {
                store.reapRoutineRuns()
                GoalWorker.enqueueQueued(featureContext, store)
                val manualId = inputData.getString("routineId")
                val manualRun = manualId?.let { id -> store.routineRuns(id).find { it.id == inputData.getString("runId") } }
                if (manualId != null && manualRun?.status != RoutineStatus.RUNNING)return Result.success()
                val runtime = AgentRuntime(featureContext, store, model)
                // Missing provider configuration is a deployment condition, not a scheduled failure.
                try {
                    runtime.checkConfigured()
                } catch (failure: Exception) {
                    if (manualRun != null)store.finishRoutineRun(manualRun, RoutineStatus.SKIPPED, failure.message)
                    return Result.success()
                }
                if (ai.openbot.agentstudio.AS_ModelSettingsStore.ModelSettingsStore(featureContext)
                        .settings()
                        .mode == ModelMode.PROVIDER_API
                ) {
                    val connectivity = featureContext.getSystemService(Context.CONNECTIVITY_SERVICE) as android.net.ConnectivityManager
                    val capabilities = connectivity.activeNetwork?.let(connectivity::getNetworkCapabilities)
                    if (capabilities?.hasCapability(android.net.NetworkCapabilities.NET_CAPABILITY_INTERNET) != true)return Result.retry()
                }
                val now = Instant.now()
                val due = store.routines().filter { if (manualId != null)it.id == manualId else it.enabled && Instant.parse(it.nextRunAt) <= now }
                for (routine in due) {
                    if (store.checkpoints().any { it.channelId == routine.channelId && it.phase in listOf(ContinuationPhase.WAITING, ContinuationPhase.QUEUED, ContinuationPhase.RUNNING) }) {
                        if (manualRun != null)store.finishRoutineRun(manualRun, RoutineStatus.SKIPPED, "A turn is already waiting for approval in this conversation.")
                        continue
                    }
                    if (!routine.enabled || store.bots().none { it.id == routine.botId && !it.paused }) {
                        if (manualRun != null)store.finishRoutineRun(manualRun, RoutineStatus.SKIPPED, "The routine or its Bot was paused before the run started.")
                        continue
                    }
                    val run =
                        manualRun ?: try {
                            store.startRoutineRun(routine.id, manual = false)
                        } catch (failure: ScheduleRefusedException) {
                            store.disableUnschedulable(routine, failure.message.orEmpty())
                            null
                        } catch (_: IllegalArgumentException) {
                            null
                        } ?: continue
                    try {
                        val outcome = runtime.turn(routine.channelId, frameFiring(routine.instruction), routineRunId = run.id)
                        store.finishRoutineRun(run, if (outcome == ai.openbot.agentstudio.AS_ProviderTurnEngine.TurnOutcome.WAITING)RoutineStatus.WAITING else RoutineStatus.SUCCEEDED)
                    } catch (failure: CancellationException) {
                        withContext(NonCancellable) { store.finishRoutineRun(run, RoutineStatus.SKIPPED, "The background run was interrupted.") }
                        throw failure
                    } catch (failure: Exception) {
                        store.finishRoutineRun(run, RoutineStatus.FAILED, failure.message)
                    }
                }
                return Result.success()
            } finally {
                withContext(NonCancellable) { model.close() }
            }
        }
    }

    companion object {
        fun register(context: Context) {
            val request = PeriodicWorkRequestBuilder<RoutineWorker>(15, TimeUnit.MINUTES).addTag(AgentStudio.WORK_TAG).addTag(AgentStudioProfiles.workTag(context)).setInputData(AgentStudioProfiles.workData(context)).build()
            WorkManager.getInstance(AgentStudioProfiles.root(context)).enqueueUniquePeriodicWork(AgentStudioProfiles.workName(context, "agentstudio-routines"), ExistingPeriodicWorkPolicy.KEEP, request)
        }

        fun enqueueManual(
            context: Context,
            run: LocalRoutineRun,
        ) {
            val request = OneTimeWorkRequestBuilder<RoutineWorker>().addTag(AgentStudio.WORK_TAG).addTag(AgentStudioProfiles.workTag(context)).setInputData(AgentStudioProfiles.workData(context)).setInputData(AgentStudioProfiles.workData(context,workDataOf("routineId" to run.routineId, "runId" to run.id))).build()
            WorkManager.getInstance(AgentStudioProfiles.root(context)).enqueueUniqueWork(AgentStudioProfiles.workName(context, "agentstudio-routine-run:${run.id}"), ExistingWorkPolicy.KEEP, request)
        }
    }
}
}

// ===== ORIGINAL RUNTIME FILE: android/app/src/main/kotlin/ai/openbot/android/data/ApprovalRuleStore.kt =====
object AS_ApprovalRuleStore {
class ApprovalRuleStore(
    private val store: LocalStore,
) {
    private val json = Json { ignoreUnknownKeys = true }
    private val db get() = store.writableDatabase

    companion object {
        fun createTables(
            db: SQLiteDatabase,
            keepLegacyAsk: Boolean = false,
        ) {
            db.execSQL("CREATE TABLE approval_preferences(id INTEGER PRIMARY KEY CHECK(id=1),payload TEXT NOT NULL)")
            db.execSQL("CREATE TABLE approval_rules(id TEXT PRIMARY KEY,payload TEXT NOT NULL)")
            if (keepLegacyAsk) {
                db.insertOrThrow(
                    "approval_preferences",
                    null,
                    ContentValues().apply {
                        put("id", 1)
                        put("payload", Json.encodeToString(ApprovalPreferences(true, false)))
                    },
                )
            }
        }
    }

    private inline fun <reified T> query(sql: String): List<T> = db.rawQuery(sql, null).use { cursor -> buildList { while (cursor.moveToNext())add(json.decodeFromString<T>(cursor.getString(0))) } }

    private fun changed() {
        if (!db.inTransaction())LocalDatabaseChanges.changed()
    }

    fun preferences(): ApprovalPreferences = query<ApprovalPreferences>("SELECT payload FROM approval_preferences WHERE id=1").firstOrNull() ?: ApprovalPreferences(false, false)

    fun savePreferences(value: ApprovalPreferences) {
        db.insertWithOnConflict(
            "approval_preferences",
            null,
            ContentValues().apply {
                put("id", 1)
                put("payload", json.encodeToString(value))
            },
            SQLiteDatabase.CONFLICT_REPLACE,
        )
        changed()
    }

    fun rules(): List<ApprovalRule> = query("SELECT payload FROM approval_rules ORDER BY rowid DESC")

    fun save(rule: ApprovalRule) {
        for (value in listOf(rule.botId, rule.toolRef, rule.effect, rule.scope))require(value.trim().length in 1..300) { "Each rule pattern must contain 1–300 characters." }
        val cleaned = rule.copy(botId = rule.botId.trim(), toolRef = rule.toolRef.trim(), effect = rule.effect.trim(), scope = rule.scope.trim())
        val values = ContentValues().apply { put("payload", json.encodeToString(cleaned)) }
        if (db.update("approval_rules", values, "id=?", arrayOf(rule.id)) == 0) {
            values.put("id", rule.id)
            db.insertOrThrow("approval_rules", null, values)
        }
        changed()
    }

    fun delete(id: String) {
        db.delete("approval_rules", "id=?", arrayOf(id))
        changed()
    }

    fun standingRuleExists(candidate: PolicyCandidate) = rules().any { it.botId == candidate.botId && it.toolRef == candidate.toolRef && it.effect == candidate.effect && it.scope == candidate.scope }

    /** Changing a preference/rule resumes an old request with a withdrawal result, never an effect. */
    fun withdraw(
        reason: String,
        match: (PendingLocalAction) -> Boolean,
    ): List<String> {
        val turns = mutableListOf<String>()
        for (snapshot in store.pendingActions().filter { it.status == LocalActionStatus.PENDING && match(it) }) {
            db.beginTransaction()
            try {
                val action = store.pendingActions().firstOrNull { it.id == snapshot.id && it.status == LocalActionStatus.PENDING } ?: continue
                val checkpoint = store.checkpoints().firstOrNull { it.turnId == action.turnId && it.approvalId == action.id && it.phase == ContinuationPhase.WAITING } ?: continue
                store.savePendingAction(action.copy(status = LocalActionStatus.CANCELLED))
                store.saveToolEvent(
                    LocalToolEvent(
                        java.util.UUID
                            .randomUUID()
                            .toString(),
                        action.turnId,
                        action.channelId,
                        action.call.id,
                        action.call.name,
                        action.call.arguments,
                        reason,
                        true,
                        java.time.Instant
                            .now()
                            .toString(),
                        action.connectionName?.let { "$it · ${action.tool.name.replace('_',' ')}" },
                    ),
                )
                store.saveCheckpoint(checkpoint.copy(phase = ContinuationPhase.QUEUED))
                turns.add(checkpoint.turnId)
                db.setTransactionSuccessful()
            } finally {
                db.endTransaction()
                changed()
            }
        }
        return turns
    }
}
}

// ===== ORIGINAL RUNTIME FILE: android/app/src/main/kotlin/ai/openbot/android/data/AttachmentStore.kt =====
object AS_AttachmentStore {
/** Files stay private to this app; filenames from document providers are display metadata only. */
class AttachmentStore(
    context: Context,
    private val store: LocalStore,
) {
    private val directory = File(context.applicationContext.filesDir, "agentstudio/attachments")
    private val json = Json { ignoreUnknownKeys = true }

    private fun rows(
        selection: String = "",
        args: Array<String> = emptyArray(),
    ): List<LocalAttachment> =
        store.readableDatabase.rawQuery("SELECT payload FROM local_attachments $selection ORDER BY created_at,id", args).use { cursor ->
            buildList { while (cursor.moveToNext())add(json.decodeFromString<LocalAttachment>(cursor.getString(0))) }
        }

    fun staged(key: String) = rows("WHERE stage_key=?", arrayOf(key))

    fun conversation(id: String) = rows("WHERE channel_id=?", arrayOf(id))

    fun get(id: String) = rows("WHERE id=?", arrayOf(id)).singleOrNull()

    private fun file(id: String): File {
        require(runCatching { UUID.fromString(id).toString() == id }.getOrDefault(false)) { "Invalid attachment identity." }
        return File(directory, id)
    }

    fun open(
        id: String,
        channelId: String,
    ): InputStream {
        val attachment = get(id) ?: error("This attachment is no longer available.")
        require(attachment.channelId == channelId && attachment.messageId != null) { "This attachment does not belong to the conversation." }
        return file(id).inputStream()
    }

    fun preview(
        id: String,
        stageKey: String?,
        channelId: String?,
    ): File? {
        val attachment = get(id) ?: return null
        if (!(attachment.stageKey != null && attachment.stageKey == stageKey || attachment.channelId != null && attachment.channelId == channelId))return null
        return file(id).takeIf { it.isFile }
    }

    private fun save(attachment: LocalAttachment) {
        val values =
            ContentValues().apply {
                put("payload", json.encodeToString(attachment))
                put("stage_key", attachment.stageKey)
                put("channel_id", attachment.channelId)
                put("message_id", attachment.messageId)
                put("created_at", attachment.createdAt)
            }
        if (store.writableDatabase.update("local_attachments", values, "id=?", arrayOf(attachment.id)) == 0) {
            values.put("id", attachment.id)
            store.writableDatabase.insertOrThrow("local_attachments", null, values)
        }
    }

    fun stage(
        key: String,
        name: String,
        claimed: String,
        input: InputStream,
        now: Instant = Instant.now(),
    ): LocalAttachment =
        input.use {
            synchronized(lock) {
                require(key.isNotBlank() && key.length <= 250)
                require(staged(key).size < MAX_ATTACHMENTS_PER_MESSAGE) { "You can attach $MAX_ATTACHMENTS_PER_MESSAGE files to a message." }
                require(rows("WHERE stage_key IS NOT NULL").size < 32) { "Finish or remove some waiting attachments before adding more." }
                directory.mkdirs()
                val id = UUID.randomUUID().toString()
                val target = file(id)
                val temporary = File(directory, ".$id.part")
                try {
                    var count = 0L
                    input.use { source ->
                        temporary.outputStream().use { output ->
                            val buffer = ByteArray(8192)
                            while (true) {
                                val size = source.read(buffer)
                                if (size < 0)break
                                count += size
                                require(count <= MAX_IMAGE_BYTES) { "'${attachmentFilename(name)}' is larger than the 8MB limit for images." }
                                output.write(buffer, 0, size)
                            }
                        }
                    }
                    val bytes = temporary.readBytes()
                    val mime = sniffAttachmentMime(bytes, claimed)
                    val keptName = attachmentFilename(name)
                    validateAttachment(keptName, mime, count)
                    val channelId = key.takeIf { it.startsWith("conversation:") }?.removePrefix("conversation:")
                    require(channelId == null || store.conversations().any { it.id == channelId }) { "This conversation no longer exists." }
                    val attachment = LocalAttachment(id, keptName, mime, count, now.toString(), stageKey = key, channelId = channelId)
                    check(temporary.renameTo(target)) { "Could not save this attachment." }
                    val db = store.writableDatabase
                    db.beginTransaction()
                    try {
                        require(staged(key).size < MAX_ATTACHMENTS_PER_MESSAGE) { "You can attach $MAX_ATTACHMENTS_PER_MESSAGE files to a message." }
                        save(attachment)
                        db.setTransactionSuccessful()
                    } finally {
                        db.endTransaction()
                    }
                    LocalDatabaseChanges.changed()
                    attachment
                } catch (failure: Throwable) {
                    target.delete()
                    throw failure
                } finally {
                    temporary.delete()
                }
            }
        }

    fun validateSend(
        ids: List<String>,
        stageKey: String,
    ): List<LocalAttachment> {
        require(ids.distinct().size == ids.size && ids.size <= MAX_ATTACHMENTS_PER_MESSAGE) { "You can attach $MAX_ATTACHMENTS_PER_MESSAGE files to a message." }
        val selected = ids.map { id -> get(id)?.takeIf { it.stageKey == stageKey && it.messageId == null } ?: error("A selected attachment is no longer waiting to send.") }
        require(selected.sumOf { it.size } <= MAX_INLINED_BYTES_PER_RUN) { "This message's attachments exceed the 32MB limit. Send fewer files in each message." }
        selected.forEach { require(file(it.id).isFile) { "'${it.name}' is no longer available. Attach it again." } }
        return selected
    }

    /** Called inside the same transaction that saves the person's message. */
    fun bind(
        ids: List<String>,
        stageKey: String,
        channelId: String,
        messageId: String,
    ) {
        require(store.writableDatabase.inTransaction()) { "Attachments must commit with their message." }
        val message = store.messages(channelId).firstOrNull { it.id == messageId && it.role == "user" } ?: error("The attachment message does not exist.")
        require(message.conversationId == channelId)
        validateSend(ids, stageKey).forEach { save(it.copy(stageKey = null, channelId = channelId, messageId = messageId)) }
    }

    fun remove(
        id: String,
        stageKey: String,
    ) = synchronized(lock) {
        val attachment = get(id) ?: return@synchronized
        require(attachment.stageKey == stageKey && attachment.messageId == null) { "An attachment already sent cannot be removed from its message." }
        require(store.writableDatabase.delete("local_attachments", "id=? AND stage_key=?", arrayOf(id, stageKey)) == 1) { "This attachment is no longer waiting to send." }
        file(id).delete()
        LocalDatabaseChanges.changed()
    }

    fun deleteUnreferenced(ids: List<String>) =
        synchronized(lock) {
            ids.filter { get(it) == null }.forEach { file(it).delete() }
        }

    fun reap(now: Instant = Instant.now()) =
        synchronized(lock) {
            val cutoff = now.minusSeconds(24 * 60 * 60)
            rows("WHERE stage_key IS NOT NULL").filter { Instant.parse(it.createdAt) < cutoff }.forEach { remove(it.id, requireNotNull(it.stageKey)) }
            val live = rows().map { it.id }.toSet()
            directory
                .listFiles()
                .orEmpty()
                .filter { it.name !in live && it.lastModified() < cutoff.toEpochMilli() }
                .forEach { it.delete() }
        }

    companion object {
        private val lock = Any()

        fun createTables(db: SQLiteDatabase) {
            db.execSQL("CREATE TABLE local_attachments(id TEXT PRIMARY KEY,stage_key TEXT,channel_id TEXT REFERENCES conversations(id) ON DELETE CASCADE,message_id TEXT REFERENCES messages(id) ON DELETE CASCADE,created_at TEXT NOT NULL,payload TEXT NOT NULL)")
            db.execSQL("CREATE INDEX local_attachments_stage ON local_attachments(stage_key)")
            db.execSQL("CREATE INDEX local_attachments_channel ON local_attachments(channel_id)")
        }
    }
}
}

// ===== ORIGINAL RUNTIME FILE: android/app/src/main/kotlin/ai/openbot/android/data/ConnectionSecrets.kt =====
object AS_ConnectionSecrets {
/** Connection bearer tokens stay in encrypted app-private preferences, outside SQLite and AppState. */
class ConnectionSecrets(
    context: Context,
) {
    private val preferences = context.applicationContext.getSharedPreferences("agentstudio-connection-secrets", Context.MODE_PRIVATE)

    fun clear() {
        check(preferences.edit().clear().commit()) { "The connection credentials could not be removed." }
    }

    fun hasToken(id: String) = preferences.contains(id)

    fun token(id: String): String? {
        val encoded = preferences.getString(id, null) ?: return null
        val bytes = Base64.decode(encoded, Base64.NO_WRAP)
        check(bytes.size > 28) { "The connection credential could not be opened. Save it again." }
        val cipher = Cipher.getInstance("AES/GCM/NoPadding")
        cipher.init(Cipher.DECRYPT_MODE, key(), GCMParameterSpec(128, bytes.copyOfRange(0, 12)))
        cipher.updateAAD(id.toByteArray())
        return cipher.doFinal(bytes.copyOfRange(12, bytes.size)).toString(Charsets.UTF_8)
    }

    fun save(
        id: String,
        token: String?,
    ) {
        if (token.isNullOrBlank()) {
            check(preferences.edit().remove(id).commit())
            return
        }
        require(token.none { it == '\r' || it == '\n' }) { "The connection credential must be a single line." }
        val cipher = Cipher.getInstance("AES/GCM/NoPadding")
        cipher.init(Cipher.ENCRYPT_MODE, key())
        cipher.updateAAD(id.toByteArray())
        val bytes = cipher.iv + cipher.doFinal(token.trim().toByteArray(Charsets.UTF_8))
        check(preferences.edit().putString(id, Base64.encodeToString(bytes, Base64.NO_WRAP)).commit()) { "The connection credential could not be saved." }
    }

    fun remove(id: String) {
        check(preferences.edit().remove(id).commit()) { "The connection credential could not be removed." }
    }

    private fun key(): SecretKey {
        val store = KeyStore.getInstance("AndroidKeyStore").apply { load(null) }
        (store.getKey("agentstudio-connection-keys", null) as? SecretKey)?.let { return it }
        return KeyGenerator
            .getInstance(KeyProperties.KEY_ALGORITHM_AES, "AndroidKeyStore")
            .apply {
                init(
                    KeyGenParameterSpec
                        .Builder("agentstudio-connection-keys", KeyProperties.PURPOSE_ENCRYPT or KeyProperties.PURPOSE_DECRYPT)
                        .setKeySize(256)
                        .setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE)
                        .setBlockModes(KeyProperties.BLOCK_MODE_GCM)
                        .build(),
                )
            }.generateKey()
    }
}
}

// ===== ORIGINAL RUNTIME FILE: android/app/src/main/kotlin/ai/openbot/android/data/GoalStore.kt =====
object AS_GoalStore {
/** Goal identity, lifecycle and run outbox live in the phone's transactional SQLite database. */
class GoalStore(
    private val store: LocalStore,
) {
    private val json = Json { ignoreUnknownKeys = true }
    private val db get() = store.writableDatabase

    companion object {
        fun createTables(db: SQLiteDatabase) {
            db.execSQL("CREATE TABLE goals(id TEXT PRIMARY KEY,bot_id TEXT NOT NULL REFERENCES bots(id) ON DELETE CASCADE,channel_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,updated_at TEXT NOT NULL,payload TEXT NOT NULL)")
            db.execSQL("CREATE INDEX goals_updated ON goals(updated_at)")
            db.execSQL("CREATE TABLE goal_runs(id TEXT PRIMARY KEY,goal_id TEXT NOT NULL REFERENCES goals(id) ON DELETE CASCADE,status TEXT NOT NULL,created_at TEXT NOT NULL,payload TEXT NOT NULL)")
            db.execSQL("CREATE INDEX goal_runs_goal ON goal_runs(goal_id,created_at)")
            db.execSQL("CREATE INDEX goal_runs_status ON goal_runs(status)")
        }
    }

    private inline fun <reified T> query(
        sql: String,
        args: Array<String>? = null,
    ): List<T> = db.rawQuery(sql, args).use { cursor -> buildList { while (cursor.moveToNext())add(json.decodeFromString<T>(cursor.getString(0))) } }

    private fun changed() {
        if (!db.inTransaction())LocalDatabaseChanges.changed()
    }

    private inline fun <T> transaction(block: () -> T): T {
        db.beginTransaction()
        try {
            val result = block()
            db.setTransactionSuccessful()
            return result
        } finally {
            db.endTransaction()
            changed()
        }
    }

    fun list(): List<LocalGoal> = query("SELECT payload FROM goals ORDER BY updated_at DESC,rowid DESC LIMIT 100")

    fun get(id: String): LocalGoal = query<LocalGoal>("SELECT payload FROM goals WHERE id=?", arrayOf(id)).firstOrNull() ?: error("This goal could not be found.")

    fun run(id: String): LocalGoalRun? = query<LocalGoalRun>("SELECT payload FROM goal_runs WHERE id=?", arrayOf(id)).firstOrNull()

    fun runs(goalId: String): List<LocalGoalRun> = query("SELECT payload FROM goal_runs WHERE goal_id=? ORDER BY created_at DESC,rowid DESC LIMIT 50", arrayOf(goalId))

    fun queuedRuns(): List<LocalGoalRun> = query("SELECT payload FROM goal_runs WHERE status=? ORDER BY created_at,rowid LIMIT 100", arrayOf(GoalRunStatus.QUEUED.name))

    fun save(input: LocalGoal): LocalGoal =
        transaction {
            val goal = validateGoal(input)
            val old = query<LocalGoal>("SELECT payload FROM goals WHERE id=?", arrayOf(goal.id)).firstOrNull()
            require(old == null || old.botId == goal.botId && old.channelId == goal.channelId) { "A goal's Bot and conversation cannot change." }
            require(goal.subscriptions.isEmpty() || goal.subscriptions == old?.subscriptions) { "Event-triggered goals are not available yet. Leave event subscriptions empty." }
            require(store.conversations().any { it.id == goal.channelId && it.botId == goal.botId }) { "Choose an accessible Bot and conversation you belong to." }
            val values =
                ContentValues().apply {
                    put("payload", json.encodeToString(goal))
                    put("updated_at", goal.updatedAt)
                }
            if (db.update("goals", values, "id=?", arrayOf(goal.id)) == 0) {
                values.put("id", goal.id)
                values.put("bot_id", goal.botId)
                values.put("channel_id", goal.channelId)
                db.insertOrThrow("goals", null, values)
            }
            goal
        }

    fun transition(
        id: String,
        status: GoalStatus,
    ): LocalGoal =
        transaction {
            val old = get(id)
            require(old.status != GoalStatus.COMPLETED || status == GoalStatus.COMPLETED) { "A completed goal can't be resumed. Create a new goal." }
            val now = Instant.now().toString()
            save(old.copy(status = status, updatedAt = now, completedAt = if (status == GoalStatus.COMPLETED)old.completedAt ?: now else null))
        }

    fun repeats(id: String): String? = whyGoalRepeats(get(id), store.routines())

    fun progress(
        id: String,
        summary: String,
        complete: Boolean = false,
        sourceRunId: String? = null,
    ): LocalGoal =
        transaction {
            val goal = get(id)
            val trimmed = summary.trim()
            require(trimmed.isNotEmpty() && trimmed.length <= 6000) { "Progress must contain 1–6000 characters." }
            require(goal.status == GoalStatus.ACTIVE) { "Only an active goal can make progress." }
            if (sourceRunId != null) {
                require(run(sourceRunId)?.let { it.goalId == id && it.status == GoalRunStatus.RUNNING } == true) { "Progress must come from the goal's current run." }
                if (complete)repeats(id)?.let { error("This goal repeats because $it, so a run can't complete it. Record this run's progress without complete, and the goal stays active. Only the person ends it.") }
            }
            val now = Instant.now().toString()
            save(goal.copy(progress = trimmed, updatedAt = now, status = if (complete)GoalStatus.COMPLETED else goal.status, completedAt = if (complete)now else goal.completedAt))
        }

    fun enqueue(id: String): LocalGoalRun =
        transaction {
            val goal = get(id)
            check(goal.status != GoalStatus.COMPLETED) { "\"${goal.title}\" is complete, so it no longer runs and nothing was done. Tell the person, and ask whether to set it up again as a new goal or switch off what runs it." }
            check(goal.status != GoalStatus.PAUSED) { "\"${goal.title}\" is paused, so it didn't run. Resume it first, if the person wants it to run." }
            require(store.bots().any { it.id == goal.botId && !it.paused }) { "This Bot is paused. Resume it before running the goal." }
            LocalGoalRun(UUID.randomUUID().toString(), id, Instant.now().toString()).also(::putRun)
        }

    private fun putRun(run: LocalGoalRun) {
        val values =
            ContentValues().apply {
                put("payload", json.encodeToString(run))
                put("status", run.status.name)
            }
        if (db.update("goal_runs", values, "id=?", arrayOf(run.id)) == 0) {
            values.put("id", run.id)
            values.put("goal_id", run.goalId)
            values.put("created_at", run.createdAt)
            db.insertOrThrow("goal_runs", null, values)
        }
        changed()
    }

    fun claim(id: String): LocalGoalRun? =
        transaction {
            val old = run(id)?.takeIf { it.status == GoalRunStatus.QUEUED } ?: return@transaction null
            val goal = get(old.goalId)
            if (goal.status != GoalStatus.ACTIVE || store.bots().none { it.id == goal.botId && !it.paused }) {
                putRun(old.copy(status = GoalRunStatus.SKIPPED, finishedAt = Instant.now().toString(), error = "The goal or its Bot is paused or completed."))
                return@transaction null
            }
            old.copy(status = GoalRunStatus.RUNNING, startedAt = Instant.now().toString()).also(::putRun)
        }

    fun attachTurn(
        id: String,
        turnId: String,
    ) = transaction {
        val old = run(id) ?: error("This goal run could not be found.")
        require(old.status == GoalRunStatus.RUNNING && old.turnId == null) { "This goal run already has a turn." }
        putRun(old.copy(turnId = turnId))
    }

    fun requeue(id: String) =
        transaction {
            val old = run(id) ?: return@transaction
            require(old.status == GoalRunStatus.RUNNING && old.turnId == null) { "A started turn cannot be repeated automatically." }
            putRun(old.copy(status = GoalRunStatus.QUEUED, startedAt = null, error = null))
        }

    fun resumeWaiting(id: String) =
        transaction {
            val old = run(id)?.takeIf { it.status == GoalRunStatus.WAITING } ?: return@transaction
            require(get(old.goalId).status == GoalStatus.ACTIVE) { "Resume the goal before answering its waiting run." }
            putRun(old.copy(status = GoalRunStatus.RUNNING, finishedAt = null))
        }

    fun finish(
        id: String,
        status: GoalRunStatus,
        reply: String? = null,
        error: String? = null,
    ) = transaction {
        val old = run(id)?.takeIf { it.status in listOf(GoalRunStatus.RUNNING, GoalRunStatus.QUEUED) || it.status == GoalRunStatus.WAITING && status in listOf(GoalRunStatus.SKIPPED, GoalRunStatus.FAILED, GoalRunStatus.SUCCEEDED) } ?: return@transaction
        putRun(old.copy(status = status, replyText = reply, error = error?.take(1000), finishedAt = Instant.now().toString()))
        if (status == GoalRunStatus.SUCCEEDED && reply != null) {
            val goal = get(old.goalId)
            save(goal.copy(lastResult = reply, updatedAt = Instant.now().toString()))
        }
    }
}
}

// ===== ORIGINAL RUNTIME FILE: android/app/src/main/kotlin/ai/openbot/android/data/LocalDataResetRepository.kt =====
object AS_LocalDataResetRepository {
/** Caller cancels workers and holds AgentGate so no active turn can recreate deleted data. */
class LocalDataResetRepository(
    private val context: Context,
    private val store: LocalStore,
) {
    fun clear() {
        store.clearUserData()
        ModelSettingsStore(context).clear()
        TranscriptionSettingsStore(context).clear()
        ConnectionSecrets(context).clear()
        LocalNotifications.clear(context)
        for (directory in listOf(File(context.filesDir, "agentstudio/attachments"), File(context.cacheDir, "agentstudio/dictation"))) {
            check(!directory.exists() || directory.deleteRecursively()) { "Some attachment or dictation files could not be removed. Try clearing local data again." }
        }
    }
}
}

// ===== ORIGINAL RUNTIME FILE: android/app/src/main/kotlin/ai/openbot/android/data/LocalStore.kt =====
object AS_LocalStore {
object LocalDatabaseChanges {
    val revision = kotlinx.coroutines.flow.MutableStateFlow(0L)

    @Synchronized fun changed() {
        revision.value = revision.value + 1
    }
}

/** App-private, transactional storage. No server, Docker daemon, or cloud database is used. */
class LocalStore(
    context: Context,
) : SQLiteOpenHelper(context, "agentstudio.db", null, 11) {
    private val appContext = context.applicationContext
    private val json = Json { ignoreUnknownKeys = true }

    init {
        setWriteAheadLoggingEnabled(true)
    }

    private fun databaseChanged() {
        if (!writableDatabase.inTransaction())LocalDatabaseChanges.changed()
    }

    override fun onConfigure(db: SQLiteDatabase) {
        db.setForeignKeyConstraintsEnabled(true)
    }

    override fun onCreate(db: SQLiteDatabase) {
        db.execSQL("CREATE TABLE bots (id TEXT PRIMARY KEY, payload TEXT NOT NULL)")
        db.execSQL("CREATE TABLE conversations (id TEXT PRIMARY KEY, bot_id TEXT NOT NULL REFERENCES bots(id), created_at TEXT NOT NULL, payload TEXT NOT NULL)")
        db.execSQL("CREATE TABLE messages (id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE, created_at TEXT NOT NULL, payload TEXT NOT NULL)")
        db.execSQL("CREATE INDEX messages_conversation ON messages(conversation_id, created_at)")
        db.execSQL("CREATE TABLE memories (id TEXT PRIMARY KEY, updated_at TEXT NOT NULL, payload TEXT NOT NULL)")
        insertDefaultBot(db)
        createCapabilityTables(db)
        createRoutineTables(db)
        createMemoryTombstones(db)
        createToolEvents(db)
        createConnections(db)
        createContinuations(db)
        GoalStore.createTables(db)
        ApprovalRuleStore.createTables(db)
        QuestionStore.createTables(db)
        AttachmentStore.createTables(db)
    }

    private fun insertDefaultBot(db: SQLiteDatabase) {
        val profile = AgentStudioProfiles.profile(appContext)
        val bot = profile?.let { LocalBot(it.id,it.name,it.instruction) } ?: LocalBot(UUID.randomUUID().toString(), "OpenBot", "You are a helpful AI coworker. Answer clearly and honestly. Use only the tools made available for this turn, and never claim an action succeeded without its result. Computer use is not available.")
        db.insertOrThrow(
            "bots",
            null,
            ContentValues().apply {
                put("id", bot.id)
                put("payload", json.encodeToString(bot))
            },
        )
    }

    /** Reset records in one transaction. File/credential cleanup happens only after it commits. */
    fun clearUserData() {
        val db = writableDatabase
        db.beginTransaction()
        try {
            db.execSQL("PRAGMA defer_foreign_keys=ON")
            val tables = mutableListOf<String>()
            db.rawQuery("SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' AND name!='android_metadata'", null).use { cursor ->
                while (cursor.moveToNext()) tables += cursor.getString(0)
            }
            tables.forEach { table -> db.delete("\"" + table.replace("\"", "\"\"") + "\"", null, null) }
            insertDefaultBot(db)
            db.setTransactionSuccessful()
        } finally {
            db.endTransaction()
            databaseChanged()
        }
    }

    override fun onUpgrade(
        db: SQLiteDatabase,
        oldVersion: Int,
        newVersion: Int,
    ) {
        if (oldVersion < 2) createCapabilityTables(db)
        if (oldVersion < 3) createRoutineTables(db)
        if (oldVersion < 4) createMemoryTombstones(db)
        if (oldVersion < 5) createToolEvents(db)
        if (oldVersion < 6) createConnections(db)
        if (oldVersion < 7) createContinuations(db)
        if (oldVersion < 8) {
            GoalStore.createTables(db)
            db.rawQuery("SELECT id,payload FROM bots", null).use { cursor ->
                while (cursor.moveToNext()) {
                    val bot = json.decodeFromString<LocalBot>(cursor.getString(1))
                    if (bot.name == "OpenBot" && bot.instruction == "You are a helpful AI coworker. Answer clearly and honestly. You have no browser, computer-control, or external app tools. Never claim to have taken an action you cannot perform.")db.update("bots", ContentValues().apply { put("payload", json.encodeToString(bot.copy(instruction = "You are a helpful AI coworker. Answer clearly and honestly. Use only the tools made available for this turn, and never claim an action succeeded without its result. Computer use is not available."))) }, "id=?", arrayOf(bot.id))
                }
            }
        }
        if (oldVersion < 11) AttachmentStore.createTables(db)
        if (oldVersion < 10) QuestionStore.createTables(db)
        if (oldVersion < 9) {
            val legacy =
                db.rawQuery("SELECT COUNT(*) FROM connections", null).use {
                    it.moveToFirst()
                    it.getInt(0) > 0
                }
            ApprovalRuleStore.createTables(db, keepLegacyAsk = legacy)
        }
    }

    private fun createContinuations(db: SQLiteDatabase) {
        db.execSQL("CREATE TABLE continuations(turn_id TEXT PRIMARY KEY REFERENCES messages(id) ON DELETE CASCADE,payload TEXT NOT NULL)")
        db.execSQL("CREATE TABLE pending_actions(id TEXT PRIMARY KEY,turn_id TEXT NOT NULL REFERENCES messages(id) ON DELETE CASCADE,payload TEXT NOT NULL)")
        db.execSQL("CREATE INDEX pending_actions_turn ON pending_actions(turn_id)")
    }

    fun checkpoints(): List<AgentCheckpoint> = query("SELECT payload FROM continuations ORDER BY rowid")

    fun pendingActions(): List<PendingLocalAction> = query("SELECT payload FROM pending_actions ORDER BY rowid")

    fun saveCheckpoint(checkpoint: AgentCheckpoint) {
        val values = ContentValues().apply { put("payload", json.encodeToString(checkpoint)) }
        if (writableDatabase.update("continuations", values, "turn_id=?", arrayOf(checkpoint.turnId)) == 0) {
            values.put("turn_id", checkpoint.turnId)
            writableDatabase.insertOrThrow("continuations", null, values)
        }
        databaseChanged()
    }

    fun savePendingAction(action: PendingLocalAction) {
        val values = ContentValues().apply { put("payload", json.encodeToString(action)) }
        if (writableDatabase.update("pending_actions", values, "id=?", arrayOf(action.id)) == 0) {
            values.put("id", action.id)
            values.put("turn_id", action.turnId)
            writableDatabase.insertOrThrow("pending_actions", null, values)
        }
        databaseChanged()
    }

    fun waitForApproval(
        checkpoint: AgentCheckpoint,
        action: PendingLocalAction,
    ) {
        require(checkpoint.approvalId == action.id && checkpoint.turnId == action.turnId && checkpoint.channelId == action.channelId)
        require(checkpoint.results.size < checkpoint.round.calls.size && checkpoint.round.calls[checkpoint.results.size] == action.call)
        writableDatabase.beginTransaction()
        try {
            val message = messages(checkpoint.channelId).first { it.id == checkpoint.turnId }
            require(message.role == "assistant" && message.state in listOf(MessageState.GENERATING, MessageState.WAITING))
            savePendingAction(action)
            saveCheckpoint(checkpoint)
            saveMessage(message.copy(state = MessageState.WAITING, text = "Waiting for your approval."))
            writableDatabase.setTransactionSuccessful()
        } finally {
            writableDatabase.endTransaction()
            databaseChanged()
        }
    }

    fun decideAction(
        id: String,
        decision: LocalActionStatus,
        always: Boolean = false,
    ): AgentCheckpoint {
        require(decision in listOf(LocalActionStatus.APPROVED, LocalActionStatus.DENIED, LocalActionStatus.HANDLED))
        writableDatabase.beginTransaction()
        try {
            val action = pendingActions().firstOrNull { it.id == id } ?: error("That approval no longer exists.")
            require(action.status == LocalActionStatus.PENDING) { "This approval has already been answered." }
            val handOff = action.policy?.behaviour == PolicyBehaviour.HAND_OFF
            require(!handOff || decision in listOf(LocalActionStatus.HANDLED, LocalActionStatus.DENIED)) { "This action is handed to you. Do it yourself and mark it done, or decline it." }
            require(handOff || decision != LocalActionStatus.HANDLED) { "Only an action handed to you can be marked done by you." }
            if (always) {
                require(decision == LocalActionStatus.APPROVED && offersStandingRule(action.policy?.source) && safetyRequirement(pendingCandidate(action)) == null) { "This action asks every time. Allow this once, or deny it." }
                val candidate = pendingCandidate(action)
                ApprovalRuleStore(this).save(ApprovalRule(UUID.randomUUID().toString(), candidate.botId, candidate.toolRef, candidate.effect, candidate.scope, RuleBehaviour.ALLOW))
            }
            val checkpoint = checkpoints().firstOrNull { it.turnId == action.turnId && it.approvalId == id && it.phase == ContinuationPhase.WAITING } ?: error("This turn can no longer continue. Send a new message to the Bot.")
            checkpoint.goalRunId?.let { runId ->
                val goals = GoalStore(this)
                val run = goals.run(runId) ?: error("This goal run no longer exists.")
                require(goals.get(run.goalId).status == GoalStatus.ACTIVE) { "Resume the goal before answering its waiting run." }
            }
            savePendingAction(action.copy(status = decision, standingRule = always))
            val queued = checkpoint.copy(phase = ContinuationPhase.QUEUED)
            saveCheckpoint(queued)
            writableDatabase.setTransactionSuccessful()
            return queued
        } finally {
            writableDatabase.endTransaction()
            databaseChanged()
        }
    }

    /** WorkManager owns scheduling. This is a transactional state transition, not another lease. */
    fun claimContinuation(turnId: String): AgentCheckpoint? {
        writableDatabase.beginTransaction()
        try {
            val checkpoint = checkpoints().firstOrNull { it.turnId == turnId && it.phase == ContinuationPhase.QUEUED } ?: return null
            val running = checkpoint.copy(phase = ContinuationPhase.RUNNING)
            saveCheckpoint(running)
            writableDatabase.setTransactionSuccessful()
            return running
        } finally {
            writableDatabase.endTransaction()
            databaseChanged()
        }
    }

    fun deleteCheckpoint(turnId: String) {
        writableDatabase.delete("continuations", "turn_id=?", arrayOf(turnId))
        databaseChanged()
    }

    fun beginApprovedAction(id: String): Boolean {
        writableDatabase.beginTransaction()
        try {
            val action = pendingActions().firstOrNull { it.id == id && it.status == LocalActionStatus.APPROVED } ?: return false
            if (bots().none { it.id == action.botId && !it.paused })return false
            if (checkpoints().any { it.turnId == action.turnId && it.phase == ContinuationPhase.INTERRUPTED })return false
            val candidate = pendingCandidate(action)
            val rules = ApprovalRuleStore(this)
            val mandatory = safetyRequirement(candidate)
            if (mandatory?.behaviour == PolicyBehaviour.HAND_OFF || mandatory?.behaviour == PolicyBehaviour.ASK && action.automatic)return false
            if (strictestRule(candidate, emptyList(), rules.rules())?.rule?.behaviour == RuleBehaviour.HAND_OFF)return false
            if (action.standingRule && !rules.standingRuleExists(candidate))return false
            if (action.automatic && action.policy?.behaviour != PolicyBehaviour.ALLOW)return false
            if (action.automatic && !canExecuteAutomatically(candidate, rules.rules(), rules.preferences(), action.policy?.review))return false
            val checkpoint = checkpoints().find { it.turnId == action.turnId }
            // Automatic actions also carry their scope: there may be no waiting checkpoint.
            (action.goalRunId ?: checkpoint?.goalRunId)?.let { runId ->
                val goals = GoalStore(this)
                val run = goals.run(runId) ?: return false
                if (goals.get(run.goalId).status != GoalStatus.ACTIVE || run.status !in listOf(GoalRunStatus.RUNNING, GoalRunStatus.WAITING))return false
            }
            (action.routineRunId ?: checkpoint?.routineRunId)?.let { runId ->
                val run = routineRun(runId) ?: return false
                if (run.status !in listOf(RoutineStatus.RUNNING, RoutineStatus.WAITING) || routines().none { it.id == run.routineId && it.enabled })return false
            }
            savePendingAction(action.copy(status = LocalActionStatus.EXECUTING))
            writableDatabase.setTransactionSuccessful()
            return true
        } finally {
            writableDatabase.endTransaction()
            databaseChanged()
        }
    }

    fun interruptContinuation(
        checkpoint: AgentCheckpoint,
        reason: String,
        interrupted: Boolean,
    ) {
        writableDatabase.beginTransaction()
        try {
            saveCheckpoint(checkpoint.copy(phase = ContinuationPhase.INTERRUPTED))
            pendingActions().filter { it.turnId == checkpoint.turnId && it.status in listOf(LocalActionStatus.PENDING, LocalActionStatus.APPROVED, LocalActionStatus.EXECUTING) }.forEach { action ->
                if (action.status == LocalActionStatus.EXECUTING)recordUnknownAction(action)
                savePendingAction(action.copy(status = if (action.status == LocalActionStatus.EXECUTING)LocalActionStatus.UNCERTAIN else LocalActionStatus.CANCELLED))
            }
            messages(checkpoint.channelId).find { it.id == checkpoint.turnId }?.let { message -> saveMessage(message.copy(state = if (interrupted)MessageState.INTERRUPTED else MessageState.FAILED, text = reason)) }
            writableDatabase.setTransactionSuccessful()
        } finally {
            writableDatabase.endTransaction()
            databaseChanged()
        }
    }

    fun recoverContinuations() {
        writableDatabase.beginTransaction()
        try {
            checkpoints().filter { it.phase == ContinuationPhase.RUNNING }.forEach { checkpoint ->
                saveCheckpoint(checkpoint.copy(phase = ContinuationPhase.INTERRUPTED))
                pendingActions().filter { it.turnId == checkpoint.turnId && it.status in listOf(LocalActionStatus.PENDING, LocalActionStatus.APPROVED, LocalActionStatus.EXECUTING) }.forEach { action ->
                    if (action.status == LocalActionStatus.EXECUTING)recordUnknownAction(action)
                    savePendingAction(action.copy(status = if (action.status == LocalActionStatus.EXECUTING)LocalActionStatus.UNCERTAIN else LocalActionStatus.CANCELLED))
                }
                messages(checkpoint.channelId).find { it.id == checkpoint.turnId }?.let { message -> saveMessage(message.copy(state = MessageState.INTERRUPTED, text = "The turn was interrupted. Check its saved actions before continuing; an action with an unknown outcome is never repeated automatically.")) }
            }
            // An automatically allowed call may have started before a durable waiting checkpoint
            // ever existed. It still has to surface an unknown outcome after process death.
            pendingActions().filter { it.status == LocalActionStatus.EXECUTING || it.automatic && it.status == LocalActionStatus.APPROVED }.forEach { action ->
                if (action.status == LocalActionStatus.EXECUTING) {
                    recordUnknownAction(action)
                    savePendingAction(action.copy(status = LocalActionStatus.UNCERTAIN))
                } else {
                    savePendingAction(action.copy(status = LocalActionStatus.CANCELLED))
                    if (toolEvents(action.channelId).none { it.turnId == action.turnId && it.callId == action.call.id })saveToolEvent(LocalToolEvent(UUID.randomUUID().toString(), action.turnId, action.channelId, action.call.id, action.call.name, action.call.arguments, NOT_DONE, true, Instant.now().toString()))
                }
            }
            writableDatabase.setTransactionSuccessful()
        } finally {
            writableDatabase.endTransaction()
            databaseChanged()
        }
    }

    private fun createConnections(db: SQLiteDatabase) {
        db.execSQL("CREATE TABLE connections(id TEXT PRIMARY KEY,payload TEXT NOT NULL)")
    }

    fun connections(): List<LocalConnection> = query("SELECT payload FROM connections ORDER BY rowid")

    fun saveConnection(connection: LocalConnection) {
        require(connection.name.isNotBlank() && connection.name.length <= 100) { "Connection name must be 1–100 characters." }
        mcpEndpoint(connection.url)
        require(
            connection.tools
                .map { it.name }
                .distinct()
                .size == connection.tools.size,
        ) { "The connection has duplicate tool names." }
        require(connection.grants.keys.all { bot -> bots().any { it.id == bot } }) { "A granted Bot no longer exists." }
        require(
            connection.grants.values
                .flatten()
                .all { name -> connection.tools.any { it.name == name } },
        ) { "A granted tool is no longer available." }
        val values = ContentValues().apply { put("payload", json.encodeToString(connection)) }
        if (writableDatabase.update("connections", values, "id=?", arrayOf(connection.id)) == 0) {
            values.put("id", connection.id)
            writableDatabase.insertOrThrow("connections", null, values)
        }
        databaseChanged()
    }

    fun deleteConnection(id: String) {
        writableDatabase.delete("connections", "id=?", arrayOf(id))
        databaseChanged()
    }

    private fun createToolEvents(db: SQLiteDatabase) {
        db.execSQL("CREATE TABLE tool_events(id TEXT PRIMARY KEY,channel_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,turn_id TEXT NOT NULL,call_id TEXT NOT NULL,payload TEXT NOT NULL,UNIQUE(turn_id,call_id))")
        db.execSQL("CREATE INDEX tool_events_channel ON tool_events(channel_id)")
    }

    fun toolEvents(channelId: String): List<LocalToolEvent> = query("SELECT payload FROM tool_events WHERE channel_id=? ORDER BY rowid", arrayOf(channelId))

    fun saveToolEvent(event: LocalToolEvent) {
        val old = toolEvents(event.channelId).firstOrNull { it.turnId == event.turnId && it.callId == event.callId }
        if (old != null) {
            require(old.name == event.name && old.arguments == event.arguments) { "A tool identity cannot change its action." }
            require(old.result == OUTCOME_UNKNOWN || old.result == event.result) { "A completed tool result cannot be replaced." }
            writableDatabase.update("tool_events", ContentValues().apply { put("payload", json.encodeToString(event.copy(id = old.id))) }, "id=?", arrayOf(old.id))
        } else {
            writableDatabase.insertOrThrow(
                "tool_events",
                null,
                ContentValues().apply {
                    put("id", event.id)
                    put("channel_id", event.channelId)
                    put("turn_id", event.turnId)
                    put("call_id", event.callId)
                    put("payload", json.encodeToString(event))
                },
            )
        }
        databaseChanged()
    }

    private fun recordUnknownAction(action: PendingLocalAction) {
        if (toolEvents(action.channelId).none { it.turnId == action.turnId && it.callId == action.call.id })saveToolEvent(LocalToolEvent(UUID.randomUUID().toString(), action.turnId, action.channelId, action.call.id, action.call.name, action.call.arguments, OUTCOME_UNKNOWN, true, Instant.now().toString(), "${action.connectionName ?: "Connected app"} · ${action.tool.name.replace('_',' ')}"))
    }

    fun resolveUnknownAction(
        id: String,
        completed: Boolean,
    ) {
        writableDatabase.beginTransaction()
        try {
            val action = pendingActions().firstOrNull { it.id == id && it.status == LocalActionStatus.UNCERTAIN } ?: error("This action is no longer waiting for a result check.")
            savePendingAction(action.copy(status = if (completed)LocalActionStatus.EXECUTED else LocalActionStatus.CANCELLED))
            recordUnknownAction(action)
            val result = if (completed)"The person checked and confirmed that this action completed." else "The person checked and confirmed that this action did not happen. Ask again before retrying."
            saveToolEvent(LocalToolEvent(UUID.randomUUID().toString(), action.turnId, action.channelId, action.call.id, action.call.name, action.call.arguments, result, !completed, Instant.now().toString()))
            writableDatabase.setTransactionSuccessful()
        } finally {
            writableDatabase.endTransaction()
            databaseChanged()
        }
    }

    private fun createMemoryTombstones(db: SQLiteDatabase) {
        db.execSQL("CREATE TABLE forgotten_memories(digest TEXT PRIMARY KEY)")
    }

    private fun memoryDigest(content: String) =
        java.security.MessageDigest
            .getInstance("SHA-256")
            .digest(content.lowercase(java.util.Locale.ROOT).toByteArray())
            .joinToString("") { "%02x".format(it) }

    fun recallMemory(
        botId: String,
        search: String = "",
    ): List<Memory> {
        require(search.length <= 200) { "Search must be 200 characters or fewer." }
        return memories().filter { it.enabled && (it.formedBy != FormedBy.BOT || it.formedByAgentId == botId) && it.content.contains(search, ignoreCase = true) }
    }

    fun saveObservedMemory(
        content: String,
        botId: String,
        sourceApp: String,
        sourceLink: String?,
        observedAt: String?,
    ): String {
        require(content.trim().isNotEmpty() && content.trim().length <= 2000) { "An observed fact must be 1–2000 characters." }
        require(sourceApp.trim().isNotEmpty() && sourceApp.trim().length <= 160) { "Provide a source of 1–160 characters." }
        require(sourceLink == null || sourceLink.length <= 1000 && webLink(sourceLink) != null) { "Links must be http or https URLs." }
        val digest = memoryDigest(content.trim())
        val forgotten = readableDatabase.rawQuery("SELECT digest FROM forgotten_memories WHERE digest=?", arrayOf(digest)).use { it.moveToFirst() }
        if (forgotten)return "{\"duplicate\":true,\"forgotten\":true}"
        memories().firstOrNull { it.formedBy == FormedBy.BOT && it.formedByAgentId == botId && memoryDigest(it.content) == digest }?.let { return "{\"id\":\"${it.id}\",\"duplicate\":true,\"forgotten\":false}" }
        val observed =
            observedAt?.let {
                java.time.OffsetDateTime
                    .parse(it)
                    .toInstant()
                    .toString()
            } ?: Instant.now().toString()
        val provenance = (sourceApp.trim() + (sourceLink?.let { " ($it)" } ?: "") + ", observed $observed").take(500)
        val memory = Memory(UUID.randomUUID().toString(), content.trim(), provenance, true, ReviewState.UNREVIEWED, FormedBy.BOT, Instant.now().toString(), botId, sourceApp.trim(), sourceLink, observed)
        saveMemory(memory)
        return json.encodeToString(memory)
    }

    private fun createRoutineTables(db: SQLiteDatabase) {
        db.execSQL("CREATE TABLE routines (id TEXT PRIMARY KEY, bot_id TEXT NOT NULL REFERENCES bots(id), payload TEXT NOT NULL)")
        db.execSQL("CREATE TABLE routine_runs (id TEXT PRIMARY KEY, routine_id TEXT NOT NULL REFERENCES routines(id) ON DELETE CASCADE, payload TEXT NOT NULL)")
        db.execSQL("CREATE INDEX routine_runs_routine ON routine_runs(routine_id)")
    }

    fun routines(): List<LocalRoutine> = query("SELECT payload FROM routines ORDER BY rowid")

    fun routineRuns(id: String): List<LocalRoutineRun> = query<LocalRoutineRun>("SELECT payload FROM routine_runs WHERE routine_id=? ORDER BY rowid DESC", arrayOf(id))

    fun routineRun(id: String): LocalRoutineRun? = query<LocalRoutineRun>("SELECT payload FROM routine_runs WHERE id=?", arrayOf(id)).firstOrNull()

    fun resumeRoutineRun(id: String) {
        val run = routineRun(id) ?: return
        if (run.status != RoutineStatus.WAITING)return
        writableDatabase.update("routine_runs", ContentValues().apply { put("payload", json.encodeToString(run.copy(status = RoutineStatus.RUNNING, finishedAt = null))) }, "id=?", arrayOf(id))
        databaseChanged()
    }

    fun saveRoutine(
        input: LocalRoutine,
        now: Instant = Instant.now(),
    ): LocalRoutine {
        writableDatabase.beginTransaction()
        try {
            val old = routines().find { it.id == input.id }
            require(conversations().any { it.id == input.channelId && it.botId == input.botId }) { "I can only post into a conversation you and I are both in." }
            require(!input.enabled || old?.enabled == true || routines().count { it.enabled } < 20) { "You already have 20 routines switched on. Switch one off before adding another." }
            input.goalId?.let { id ->
                val goal = GoalStore(this).get(id)
                require(goal.botId == input.botId && goal.status != GoalStatus.COMPLETED) { "Choose a goal belonging to this Bot that is not complete." }
            }
            val valid = validateRoutine(input, now)
            val saved = if (old != null && old.cron == input.cron && old.timezone == input.timezone && !(input.enabled && !old.enabled))valid.copy(nextRunAt = old.nextRunAt) else valid
            putRoutine(saved)
            writableDatabase.setTransactionSuccessful()
            databaseChanged()
            return saved
        } finally {
            writableDatabase.endTransaction()
            databaseChanged()
        }
    }

    private fun putRoutine(routine: LocalRoutine) {
        val values = ContentValues().apply { put("payload", json.encodeToString(routine)) }
        if (writableDatabase.update("routines", values, "id=?", arrayOf(routine.id)) == 0) {
            values.put("id", routine.id)
            values.put("bot_id", routine.botId)
            writableDatabase.insertOrThrow("routines", null, values)
        }
    }

    fun deleteRoutine(id: String) {
        writableDatabase.delete("routines", "id=?", arrayOf(id))
        databaseChanged()
    }

    /** The due stamp and open run are updated in one SQLite transaction, including across workers. */
    fun startRoutineRun(
        id: String,
        manual: Boolean,
        now: Instant = Instant.now(),
    ): LocalRoutineRun? {
        writableDatabase.beginTransaction()
        try {
            val routine = routines().find { it.id == id } ?: error("That routine does not exist.")
            require(routine.enabled) { "This routine is paused, and paused routines never run. Switch it on first." }
            if (!manual && Instant.parse(routine.nextRunAt) > now)return null
            val open = routineRuns(id).any { it.status == RoutineStatus.RUNNING }
            if (open) {
                if (manual)error("This routine is already running. Wait for that run to finish.")
                return null
            }
            val run = LocalRoutineRun(UUID.randomUUID().toString(), id, now.toString(), if (manual)"run_now" else "schedule")
            putRoutine(routine.copy(lastRunAt = now.toString(), nextRunAt = if (manual)routine.nextRunAt else nextOccurrence(routine.cron, routine.timezone, now).toString()))
            writableDatabase.insertOrThrow(
                "routine_runs",
                null,
                ContentValues().apply {
                    put("id", run.id)
                    put("routine_id", id)
                    put("payload", json.encodeToString(run))
                },
            )
            writableDatabase.setTransactionSuccessful()
            databaseChanged()
            return run
        } finally {
            writableDatabase.endTransaction()
            databaseChanged()
        }
    }

    fun disableUnschedulable(
        routine: LocalRoutine,
        reason: String,
    ) {
        writableDatabase.beginTransaction()
        try {
            putRoutine(routine.copy(enabled = false))
            val now = Instant.now().toString()
            val run = LocalRoutineRun(UUID.randomUUID().toString(), routine.id, now, status = RoutineStatus.SKIPPED, finishedAt = now, error = reason.take(400))
            writableDatabase.insertOrThrow(
                "routine_runs",
                null,
                ContentValues().apply {
                    put("id", run.id)
                    put("routine_id", routine.id)
                    put("payload", json.encodeToString(run))
                },
            )
            writableDatabase.setTransactionSuccessful()
        } finally {
            writableDatabase.endTransaction()
            databaseChanged()
        }
    }

    fun reapRoutineRuns(now: Instant = Instant.now()) {
        routines().forEach { routine ->
            routineRuns(routine.id)
                .filter {
                    it.status == RoutineStatus.RUNNING && java.time.Duration
                        .between(Instant.parse(it.startedAt), now)
                        .toMinutes() >= 30
                }.forEach {
                    finishRoutineRun(it, RoutineStatus.SKIPPED, "The previous run was interrupted before it finished.", now)
                }
        }
    }

    fun finishRoutineRun(
        run: LocalRoutineRun,
        status: RoutineStatus,
        error: String? = null,
        now: Instant = Instant.now(),
    ) {
        val current = routineRuns(run.routineId).find { it.id == run.id } ?: return
        if (current.status != RoutineStatus.RUNNING)return
        val reason = error?.let { String(it.codePoints().limit(400).toArray(), 0, it.codePointCount(0, it.length).coerceAtMost(400)) }
        writableDatabase.update("routine_runs", ContentValues().apply { put("payload", json.encodeToString(current.copy(status = status, finishedAt = now.toString(), error = reason))) }, "id=?", arrayOf(run.id))
        databaseChanged()
        if (status == RoutineStatus.FAILED && routineRuns(run.routineId).take(10).let { it.size == 10 && it.all { r -> r.status == RoutineStatus.FAILED } }) {
            routines().find { it.id == run.routineId }?.let { putRoutine(it.copy(enabled = false)) }
        }
    }

    private fun createCapabilityTables(db: SQLiteDatabase) {
        db.execSQL("CREATE TABLE skills (slug TEXT PRIMARY KEY, payload TEXT NOT NULL)")
        db.execSQL("CREATE TABLE preferences (id INTEGER PRIMARY KEY CHECK(id=1), payload TEXT NOT NULL)")
    }

    fun skills(): List<LocalSkill> = query("SELECT payload FROM skills ORDER BY rowid")

    fun preferences(): LocalPreferences = query<LocalPreferences>("SELECT payload FROM preferences WHERE id=1").firstOrNull() ?: LocalPreferences(darkTheme=if(AgentStudioProfiles.id(appContext)!=null)false else null)

    fun savePreferences(preferences: LocalPreferences) {
        require(preferences.name.length <= 100) { "Name must be 100 characters or fewer." }
        require(preferences.messageListEmphasis in listOf("agent", "thread")) { "Choose Bot names or conversation titles." }
        writableDatabase.insertWithOnConflict(
            "preferences",
            null,
            ContentValues().apply {
                put("id", 1)
                put("payload", json.encodeToString(preferences))
            },
            SQLiteDatabase.CONFLICT_REPLACE,
        )
        databaseChanged()
    }

    fun saveSkill(
        skill: LocalSkill,
        creating: Boolean,
    ) {
        validateSkill(skill)
        val values =
            ContentValues().apply {
                put("slug", skill.slug)
                put("payload", json.encodeToString(skill))
            }
        if (creating) {
            check(skills().none { it.slug == skill.slug }) { "A skill already uses /${skill.slug}. Choose another command." }
            writableDatabase.insertOrThrow("skills", null, values)
        } else {
            check(writableDatabase.update("skills", values, "slug=?", arrayOf(skill.slug)) == 1) { "This skill no longer exists." }
        }
        databaseChanged()
    }

    fun deleteSkill(slug: String) {
        writableDatabase.delete("skills", "slug=?", arrayOf(slug))
        databaseChanged()
    }

    fun bots(): List<LocalBot> = query("SELECT payload FROM bots ORDER BY rowid")

    fun conversations(): List<LocalConversation> =
        query<LocalConversation>("SELECT payload FROM conversations ORDER BY created_at DESC, rowid DESC")
            .sortedByDescending { it.lastMessageAt ?: it.createdAt }

    fun messages(conversationId: String): List<LocalMessage> = query("SELECT payload FROM messages WHERE conversation_id=? ORDER BY created_at, rowid", arrayOf(conversationId))

    fun memories(): List<Memory> = query("SELECT payload FROM memories ORDER BY updated_at DESC, rowid DESC")

    fun saveBot(bot: LocalBot) {
        require(bot.name.isNotBlank() && bot.name.length <= 80) { "Name must be 1–80 characters." }
        require(bot.instruction.isNotBlank() && (bot.instruction.length <= 1000 || bots().any { it.id == bot.id && it.instruction == bot.instruction })) { "Instructions must be 1–1000 characters." }
        // UPDATE rather than REPLACE: preserve foreign-key relationships and the Bot's identity.
        val values = ContentValues().apply { put("payload", json.encodeToString(bot)) }
        if (writableDatabase.update("bots", values, "id=?", arrayOf(bot.id)) == 0) {
            values.put("id", bot.id)
            writableDatabase.insertOrThrow("bots", null, values)
        }
        databaseChanged()
    }

    fun deleteBot(id: String) {
        val files = AttachmentStore(appContext, this)
        val attachmentIds = conversations().filter { it.botId == id }.flatMap { files.conversation(it.id) }.map { it.id }
        val nested = writableDatabase.inTransaction()
        var deleted = false
        writableDatabase.beginTransaction()
        try {
            writableDatabase.delete("routines", "bot_id=?", arrayOf(id))
            writableDatabase.delete("conversations", "bot_id=?", arrayOf(id))
            writableDatabase.delete("bots", "id=?", arrayOf(id))
            connections().filter { it.grants.containsKey(id) }.forEach { saveConnection(it.copy(grants = it.grants - id)) }
            writableDatabase.setTransactionSuccessful()
            deleted = true
            databaseChanged()
        } finally {
            writableDatabase.endTransaction()
            if (deleted && !nested)files.deleteUnreferenced(attachmentIds)
            databaseChanged()
        }
    }

    fun newConversation(botId: String): LocalConversation {
        val bot = bots().first { it.id == botId }
        val conversation = LocalConversation(UUID.randomUUID().toString(), botId, bot.name, Instant.now().toString())
        writableDatabase.insertOrThrow(
            "conversations",
            null,
            ContentValues().apply {
                put("id", conversation.id)
                put("bot_id", botId)
                put("created_at", conversation.createdAt)
                put("payload", json.encodeToString(conversation))
            },
        )
        databaseChanged()
        return conversation
    }

    fun saveMessage(message: LocalMessage) {
        writableDatabase.beginTransaction()
        try {
            val values =
                ContentValues().apply {
                    put("id", message.id)
                    put("conversation_id", message.conversationId)
                    put("created_at", message.createdAt)
                    put("payload", json.encodeToString(message))
                }
            if (writableDatabase.update("messages", values, "id=?", arrayOf(message.id)) == 0) {
                writableDatabase.insertOrThrow("messages", null, values)
            }
            if (message.state == MessageState.COMPLETE) {
                val conversation: LocalConversation = query<LocalConversation>("SELECT payload FROM conversations WHERE id=?", arrayOf(message.conversationId)).single()
                saveConversation(
                    conversation.copy(
                        opening = conversation.opening ?: message.text.takeIf { message.role == "user" },
                        lastMessage = message.text,
                        lastMessageAgentId = conversation.botId.takeIf { message.role != "user" },
                        lastMessageAt = message.createdAt,
                    ),
                )
            }
            writableDatabase.setTransactionSuccessful()
        } finally {
            writableDatabase.endTransaction()
            databaseChanged()
        }
    }

    /** A chosen title is separate from the generated summary; an empty title restores it. */
    fun renameConversation(
        id: String,
        title: String,
    ) {
        val chosen = title.trim().takeIf { it.isNotEmpty() }
        if (chosen != null) {
            val boundaries =
                android.icu.text.BreakIterator
                    .getCharacterInstance(java.util.Locale.ROOT)
            boundaries.setText(chosen)
            var count = 0
            while (boundaries.next() != android.icu.text.BreakIterator.DONE) count++
            require(count <= 60) { "Use a conversation name of at most 60 characters." }
        }
        writableDatabase.beginTransaction()
        try {
            val current = conversations().firstOrNull { it.id == id } ?: error("Conversation no longer exists.")
            saveConversation(current.copy(title = chosen))
            writableDatabase.setTransactionSuccessful()
        } finally {
            writableDatabase.endTransaction()
            databaseChanged()
        }
    }

    fun saveConversation(conversation: LocalConversation) {
        val values = ContentValues().apply { put("payload", json.encodeToString(conversation)) }
        check(writableDatabase.update("conversations", values, "id=?", arrayOf(conversation.id)) == 1) { "Conversation no longer exists." }
        databaseChanged()
    }

    fun deleteConversation(id: String) {
        val files = AttachmentStore(appContext, this)
        val ids = files.conversation(id).map { it.id }
        val nested = writableDatabase.inTransaction()
        writableDatabase.delete("conversations", "id=?", arrayOf(id))
        if (!nested)files.deleteUnreferenced(ids)
        databaseChanged()
    }

    fun beginTurn(
        user: LocalMessage,
        assistant: LocalMessage,
    ) {
        require(user.conversationId == assistant.conversationId) { "A turn must belong to one conversation." }
        writableDatabase.beginTransaction()
        try {
            saveMessage(user)
            saveMessage(assistant)
            writableDatabase.setTransactionSuccessful()
            databaseChanged()
        } finally {
            writableDatabase.endTransaction()
            databaseChanged()
        }
    }

    fun saveMemory(memory: Memory) {
        require(memory.content.isNotBlank() && memory.content.length <= 6000)
        val values =
            ContentValues().apply {
                put("id", memory.id)
                put("updated_at", memory.updatedAt)
                put("payload", json.encodeToString(memory))
            }
        if (writableDatabase.update("memories", values, "id=?", arrayOf(memory.id)) == 0) {
            writableDatabase.insertOrThrow("memories", null, values)
        }
        databaseChanged()
    }

    fun deleteMemory(id: String) {
        writableDatabase.beginTransaction()
        try {
            memories().find { it.id == id }?.let { memory -> writableDatabase.insertWithOnConflict("forgotten_memories", null, ContentValues().apply { put("digest", memoryDigest(memory.content)) }, SQLiteDatabase.CONFLICT_IGNORE) }
            writableDatabase.delete("memories", "id=?", arrayOf(id))
            writableDatabase.setTransactionSuccessful()
            databaseChanged()
        } finally {
            writableDatabase.endTransaction()
            databaseChanged()
        }
    }

    fun recoverInterruptedMessages() {
        writableDatabase.beginTransaction()
        try {
            val interrupted: List<LocalMessage> = query("SELECT payload FROM messages")
            interrupted.filter { it.state == MessageState.GENERATING }.forEach {
                val partial = it.text.takeIf { text -> text.isNotBlank() && text != "Working…" }
                saveMessage(it.copy(text = listOfNotNull(partial, "Generation was interrupted. Send your message again to retry.").joinToString("\n\n"), state = MessageState.INTERRUPTED))
            }
            writableDatabase.setTransactionSuccessful()
            databaseChanged()
        } finally {
            writableDatabase.endTransaction()
            databaseChanged()
        }
    }

    private inline fun <reified T> query(
        sql: String,
        args: Array<String>? = null,
    ): List<T> =
        readableDatabase.rawQuery(sql, args).use { cursor ->
            buildList { while (cursor.moveToNext()) add(json.decodeFromString<T>(cursor.getString(0))) }
        }
}
}

