object AS_McpClient {
/** Direct HTTPS MCP Streamable HTTP transport. A session and its credential never follow redirects. */
interface McpSession {
    suspend fun initialize(): String

    suspend fun listTools(): List<McpTool>

    suspend fun call(
        tool: McpTool,
        args: JsonObject,
    ): JsonObject

    suspend fun close()
}

class McpClient(
    private val connection: LocalConnection,
    private val token: String?,
) : McpSession {
    private var session: String? = null
    private var initialized = false
    private var protocolVersion = MCP_VERSION

    private suspend fun post(
        body: JsonObject,
        id: String?,
    ): JsonObject? =
        withContext(Dispatchers.IO) {
            coroutineScope {
                require(token == null || token.none { it == '\r' || it == '\n' }) { "The connection credential must be a single line." }
                val http = mcpEndpoint(connection.url).toURL().openConnection() as HttpsURLConnection
                val watcher =
                    launch(Dispatchers.IO, start = CoroutineStart.UNDISPATCHED) {
                        try {
                            awaitCancellation()
                        } finally {
                            http.disconnect()
                        }
                    }
                try {
                    http.requestMethod = "POST"
                    http.instanceFollowRedirects = false
                    http.connectTimeout = 20_000
                    http.readTimeout = 120_000
                    http.setRequestProperty("Content-Type", "application/json")
                    http.setRequestProperty("Accept", "application/json, text/event-stream")
                    if (initialized)http.setRequestProperty("MCP-Protocol-Version", protocolVersion)
                    session?.let { http.setRequestProperty("Mcp-Session-Id", it) }
                    token?.takeIf { it.isNotBlank() }?.let { http.setRequestProperty("Authorization", "Bearer $it") }
                    http.doOutput = true
                    val bytes = body.toString().toByteArray(Charsets.UTF_8)
                    http.setFixedLengthStreamingMode(bytes.size)
                    http.outputStream.use { it.write(bytes) }
                    val status = http.responseCode
                    check(status in 200..299) {
                        when (status) {
                            401, 403 -> "The MCP server refused the connection credential."
                            in 300..399 -> "The MCP server redirected the request. Enter its final HTTPS URL."
                            else -> "The MCP request failed (HTTP $status)."
                        }
                    }
                    http.getHeaderField("Mcp-Session-Id")?.let { value ->
                        require(value.length <= 4096 && value.all { it.code in 33..126 }) { "The MCP server returned an invalid session identity." }
                        session = value
                    }
                    if (id == null)return@coroutineScope null
                    check(status != 202) { "The MCP server accepted the request without returning its result. This response mode is not supported yet." }
                    http.inputStream.use { input -> readMcpStream(input, http.contentType.orEmpty(), id) }
                } finally {
                    watcher.cancel()
                    http.disconnect()
                }
            }
        }

    override suspend fun initialize(): String {
        val id = UUID.randomUUID().toString()
        val result = requireNotNull(post(mcpInitialize(id), id))
        protocolVersion = result["protocolVersion"]?.jsonPrimitive?.contentOrNull?.takeIf { it in MCP_HTTP_VERSIONS } ?: error("This MCP server uses an unsupported protocol version.")
        initialized = true
        post(
            buildJsonObject {
                put("jsonrpc", "2.0")
                put("method", "notifications/initialized")
            },
            null,
        )
        return result["serverInfo"]
            ?.jsonObject
            ?.get("name")
            ?.jsonPrimitive
            ?.contentOrNull ?: connection.name
    }

    override suspend fun listTools(): List<McpTool> {
        check(initialized) { "Initialize the MCP connection first." }
        var descriptionBudget = 1_000_000
        val tools = mutableListOf<McpTool>()
        val seen = mutableSetOf<String>()
        var cursor: String? = null
        do {
            val id = UUID.randomUUID().toString()
            val params = buildJsonObject { cursor?.let { put("cursor", it) } }
            val reply = requireNotNull(post(mcpRequest(id, "tools/list", params), id))
            val items = reply["tools"] as? JsonArray ?: error("The MCP server did not return a tool list.")
            items.forEach { item ->
                descriptionBudget -= item.toString().length
                check(descriptionBudget >= 0) { "The MCP tool descriptions exceeded this connection’s size limit." }
                val obj = item.jsonObject
                val name = obj["name"]?.jsonPrimitive?.contentOrNull?.takeIf { it.isNotBlank() && it.length <= 256 } ?: error("The MCP server returned an invalid tool name.")
                check(tools.none { it.name == name }) { "The MCP server returned duplicate tool names." }
                tools.add(McpTool(name, obj["description"]?.jsonPrimitive?.contentOrNull.orEmpty(), obj["inputSchema"] as? JsonObject ?: error("The MCP server returned an invalid tool schema."), obj["annotations"] as? JsonObject ?: buildJsonObject {}))
                check(tools.size <= 500) { "This MCP connection offers more than 500 tools." }
            }
            cursor = reply["nextCursor"]?.jsonPrimitive?.contentOrNull?.takeIf { it.isNotEmpty() }
            if (cursor != null)check(seen.add(cursor!!)) { "The MCP server repeated a pagination cursor." }
        } while (cursor != null)
        return tools
    }

    override suspend fun close() =
        withContext(Dispatchers.IO) {
            val identity = session ?: return@withContext
            session = null
            initialized = false
            val http = mcpEndpoint(connection.url).toURL().openConnection() as HttpsURLConnection
            try {
                http.requestMethod = "DELETE"
                http.instanceFollowRedirects = false
                http.connectTimeout = 5000
                http.readTimeout = 5000
                http.setRequestProperty("Mcp-Session-Id", identity)
                http.setRequestProperty("MCP-Protocol-Version", protocolVersion)
                token?.takeIf { it.isNotBlank() }?.let { http.setRequestProperty("Authorization", "Bearer $it") }
                http.responseCode // Session deletion is optional; a server may answer 405.
            } finally {
                http.disconnect()
            }
        }

    override suspend fun call(
        tool: McpTool,
        args: JsonObject,
    ): JsonObject {
        check(initialized) { "Initialize the MCP connection first." }
        val id = UUID.randomUUID().toString()
        return requireNotNull(
            post(
                mcpRequest(
                    id,
                    "tools/call",
                    buildJsonObject {
                        put("name", tool.name)
                        put("arguments", args)
                    },
                ),
                id,
            ),
        )
    }
}
}

// ===== ORIGINAL RUNTIME FILE: android/app/src/main/kotlin/ai/openbot/android/inference/OnDeviceSpeechRecording.kt =====
object AS_OnDeviceSpeechRecording {
/** Strictly the Android on-device recognizer. Never silently sends speech to a cloud service. */
class OnDeviceSpeechRecording private constructor(
    private val recognizer: SpeechRecognizer,
    private val onError: (Throwable) -> Unit,
    private val onLimit: () -> Unit,
) : AudioRecording,
    RecognitionListener {
    private val result = CompletableDeferred<String>()

    @Volatile private var disposed = false

    @Volatile private var amplitude = 0f
    private var stopping = false

    override suspend fun finish(): DictationText =
        withContext(Dispatchers.Main.immediate) {
            try {
                check(!disposed) { "Speech recognition was cancelled." }
                if (!stopping && !result.isCompleted) {
                    stopping = true
                    recognizer.stopListening()
                }
                DictationText(withTimeout(15_000) { result.await() })
            } finally {
                this@OnDeviceSpeechRecording.cancel()
            }
        }

    override fun level(): Float = amplitude

    override fun cancel() {
        if (disposed) return
        disposed = true
        result.cancel()
        val release =
            Runnable {
                runCatching { recognizer.cancel() }
                runCatching { recognizer.destroy() }
            }
        if (Looper.myLooper() == Looper.getMainLooper()) release.run() else Handler(Looper.getMainLooper()).post(release)
    }

    override fun onReadyForSpeech(params: Bundle?) = Unit

    override fun onBeginningOfSpeech() = Unit

    override fun onRmsChanged(rmsdB: Float) {
        if (!disposed) amplitude = (rmsdB / 10f).coerceIn(0f, 1f)
    }

    override fun onBufferReceived(buffer: ByteArray?) = Unit

    override fun onEndOfSpeech() {
        if (!disposed) onLimit()
    }

    override fun onPartialResults(partialResults: Bundle?) = Unit

    override fun onEvent(
        eventType: Int,
        params: Bundle?,
    ) = Unit

    override fun onResults(results: Bundle?) {
        if (disposed) return
        val text = results?.getStringArrayList(SpeechRecognizer.RESULTS_RECOGNITION)?.firstOrNull()?.trim()
        if (text.isNullOrBlank()) {
            onError(SpeechRecognizer.ERROR_NO_MATCH)
            return
        }
        result.complete(text)
        onLimit()
    }

    override fun onError(error: Int) {
        if (disposed) return
        val message =
            when (error) {
                SpeechRecognizer.ERROR_INSUFFICIENT_PERMISSIONS -> "Microphone access was denied. Allow it in Android settings and try again."
                SpeechRecognizer.ERROR_NO_MATCH, SpeechRecognizer.ERROR_SPEECH_TIMEOUT -> "No speech was detected. Try recording again."
                SpeechRecognizer.ERROR_LANGUAGE_NOT_SUPPORTED, SpeechRecognizer.ERROR_LANGUAGE_UNAVAILABLE -> "On-device speech for this language is unavailable. Download a speech language in Android settings, or configure a transcription provider."
                else -> "On-device speech stopped. Try again, or configure a transcription provider in Model settings."
            }
        result.completeExceptionally(IllegalStateException(message))
        onError(IllegalStateException(message))
        cancel()
    }

    companion object {
        fun requireAvailable(context: Context) {
            if (Build.VERSION.SDK_INT < 31 || !SpeechRecognizer.isOnDeviceRecognitionAvailable(context)) {
                throw DictationUnavailableException("On-device speech is unavailable on this phone. Configure a transcription provider in Model settings to use dictation.")
            }
        }

        suspend fun create(
            context: Context,
            onError: (Throwable) -> Unit,
            onLimit: () -> Unit,
        ): OnDeviceSpeechRecording =
            withContext(Dispatchers.Main.immediate) {
                requireAvailable(context)
                if (Build.VERSION.SDK_INT < 31) throw DictationUnavailableException("On-device speech requires Android 12 or later.")
                val recognizer = SpeechRecognizer.createOnDeviceSpeechRecognizer(context.applicationContext)
                val recording = OnDeviceSpeechRecording(recognizer, onError, onLimit)
                try {
                    recognizer.setRecognitionListener(recording)
                    recognizer.startListening(
                        Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH).apply {
                            putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL, RecognizerIntent.LANGUAGE_MODEL_FREE_FORM)
                            putExtra(RecognizerIntent.EXTRA_LANGUAGE, Locale.getDefault().toLanguageTag())
                            putExtra(RecognizerIntent.EXTRA_PREFER_OFFLINE, true)
                            putExtra(RecognizerIntent.EXTRA_MAX_RESULTS, 1)
                            putExtra(RecognizerIntent.EXTRA_PARTIAL_RESULTS, false)
                        },
                    )
                    recording
                } catch (failure: Throwable) {
                    recording.cancel()
                    throw failure
                }
            }
    }
}
}

// ===== ORIGINAL RUNTIME FILE: android/app/src/main/kotlin/ai/openbot/android/inference/ProviderModel.kt =====
object AS_ProviderModel {
fun interface ProviderTransport {
    suspend fun request(
        settings: ProviderSettings,
        key: String,
        request: JsonObject,
    ): JsonObject

    suspend fun stream(
        settings: ProviderSettings,
        key: String,
        request: JsonObject,
        onText: suspend (String) -> Unit,
    ): JsonObject = request(settings, key, request)
}

/** HTTPS only; never redirects or retries a POST, including a turn containing tool results. */
class ProviderModel(
    private val attachments: AttachmentWireSource? = null,
    client: OkHttpClient = sharedClient,
) : ProviderTransport {
    private val client =
        client
            .newBuilder()
            .followRedirects(false)
            .followSslRedirects(false)
            .retryOnConnectionFailure(false)
            .build()

    suspend fun generate(
        settings: ProviderSettings,
        key: String,
        prompt: String,
    ): String = providerAnswer(settings.apiStyle, request(settings, key, providerRequest(settings, prompt)))

    override suspend fun request(
        settings: ProviderSettings,
        key: String,
        request: JsonObject,
    ): JsonObject = exchange(settings, key, request, null)

    override suspend fun stream(
        settings: ProviderSettings,
        key: String,
        request: JsonObject,
        onText: suspend (String) -> Unit,
    ): JsonObject = exchange(settings, key, request, onText)

    private suspend fun exchange(
        settings: ProviderSettings,
        key: String,
        request: JsonObject,
        onText: (suspend (String) -> Unit)?,
    ): JsonObject =
        withContext(Dispatchers.IO) {
            coroutineScope {
                require(key.isNotBlank() && key.none { it == '\r' || it == '\n' }) { "Save a valid model provider key in Model settings first." }
                val payload = if (onText == null) request else JsonObject(request + ("stream" to JsonPrimitive(true)))
                val body = AttachmentRequestBody(payload, attachments)
                val length = body.byteCount()
                val requestBody =
                    object : RequestBody() {
                        override fun contentType() = "application/json".toMediaType()

                        override fun contentLength() = length

                        override fun writeTo(sink: BufferedSink) = body.writeTo(sink.outputStream())

                        override fun isOneShot() = true
                    }
                val wire =
                    Request
                        .Builder()
                        .url(providerEndpoint(settings).toString())
                        .header("Authorization", "Bearer $key")
                        .header("Accept", if (onText == null) "application/json" else "text/event-stream, application/json")
                        .post(requestBody)
                        .build()
                val call = client.newCall(wire)
                val watcher =
                    launch(Dispatchers.IO, start = CoroutineStart.UNDISPATCHED) {
                        try {
                            awaitCancellation()
                        } finally {
                            call.cancel()
                        }
                    }
                try {
                    call.execute().use { response ->
                        check(response.isSuccessful) {
                            when (response.code) {
                                401, 403 -> "The model provider refused the saved key. Check it in Model settings."
                                429 -> "The model provider is rate limited or out of quota. Try later."
                                in 300..399 -> "The model API redirected the request. Enter its final HTTPS endpoint; keys are never forwarded to redirects."
                                else -> "The model API request failed (HTTP ${response.code}). Check the API URL, model name and API style."
                            }
                        }
                        val responseBody = response.body ?: error("The model API returned no response.")
                        BoundedResponse(responseBody.byteStream()).bufferedReader(Charsets.UTF_8).use { reader ->
                            if (onText == null || responseBody.contentType()?.subtype != "event-stream") {
                                return@coroutineScope runCatching { Json.parseToJsonElement(reader.readText()).jsonObject }.getOrElse { error("The model API returned an invalid JSON response.") }
                            }
                            val events = ServerSentEvents()
                            val stream = ProviderStream(settings.apiStyle)
                            var lastText = ""
                            var lastUpdate = 0L
                            while (true) {
                                currentCoroutineContext().ensureActive()
                                val line = reader.readLine() ?: break
                                val event = events.line(line) ?: continue
                                val complete = stream.accept(event)
                                val text = stream.visibleText
                                val now = System.nanoTime()
                                if (text != lastText && (lastText.isEmpty() || complete || now - lastUpdate >= 100_000_000)) {
                                    onText(text)
                                    lastText = text
                                    lastUpdate = now
                                }
                                if (complete) {
                                    if (text != lastText) onText(text)
                                    break
                                }
                            }
                            stream.finish()
                        }
                    }
                } catch (failure: Exception) {
                    currentCoroutineContext().ensureActive()
                    throw failure
                } finally {
                    watcher.cancel()
                    call.cancel()
                }
            }
        }

    private class BoundedResponse(
        input: InputStream,
    ) : FilterInputStream(input) {
        private var count = 0L

        private fun account(size: Int): Int {
            if (size > 0) count += size
            check(count <= 2 * 1024 * 1024) { "The model API response was too large." }
            return size
        }

        override fun read(): Int = super.read().also { if (it >= 0) account(1) }

        override fun read(
            buffer: ByteArray,
            offset: Int,
            length: Int,
        ): Int = account(`in`.read(buffer, offset, length))
    }

    companion object {
        private val sharedClient =
            OkHttpClient
                .Builder()
                .followRedirects(false)
                .followSslRedirects(false)
                .retryOnConnectionFailure(false)
                .connectTimeout(20, TimeUnit.SECONDS)
                .readTimeout(120, TimeUnit.SECONDS)
                .callTimeout(180, TimeUnit.SECONDS)
                .build()
    }
}
}

// ===== ORIGINAL RUNTIME FILE: android/app/src/main/kotlin/ai/openbot/android/inference/ProviderTurnEngine.kt =====
object AS_ProviderTurnEngine {
enum class TurnOutcome { COMPLETED, WAITING }

/** Provider continuations pause durably before an external action, without keeping a network job open. */
internal class ProviderTurnEngine(
    context: Context,
    private val store: LocalStore,
    private val configuration: ModelConfiguration,
    private val provider: ProviderTransport,
    private val builtin: (ToolCall, String, String, String) -> String,
    private val sessions: (LocalConnection, String?) -> McpSession = { connection, token -> McpClient(connection, token) },
) {
    private val secrets = ConnectionSecrets(context)
    private val policy = ActionPolicy(store, configuration, provider)

    fun connectedTools(botId: String): List<AgentTool> =
        store.connections().flatMap { connection ->
            connection.tools.filter { it.name in connection.grants[botId].orEmpty() }.map { tool ->
                AgentTool(mcpModelToolName(connection.id, tool.name), "${connection.name}: ${tool.name}. ${tool.description}", tool.inputSchema)
            }
        }

    suspend fun run(
        settings: ProviderSettings,
        tools: List<AgentTool>,
        protocol: AgentProtocol,
        pending: LocalMessage,
        botId: String,
        onChanged: suspend () -> Unit,
        checkpoint: AgentCheckpoint? = null,
        routineRunId: String? = null,
        goalRunId: String? = null,
    ): String? {
        var current = checkpoint?.round
        var outputs = checkpoint?.results?.toMutableList() ?: mutableListOf()
        var rounds = checkpoint?.roundCount ?: 0
        var answeredAction = checkpoint?.approvalId?.let { id -> store.pendingActions().firstOrNull { it.id == id } }
        // Every step after the one that paused must receive a result without running.
        // The next model round can plan again using the person's decision.
        var waitedIndex = checkpoint?.results?.size
        while (true) {
            if (current == null) {
                check(rounds < 16) { "This turn reached its tool-call limit. Saved actions were kept; ask the Bot to continue." }
                val (active, keyValue) = configuration.snapshot()
                check(active == settings) { "Model settings changed during this turn. Saved actions were kept; send a new message to continue." }
                val key = keyValue?.takeIf { it.isNotBlank() } ?: error("Add your model provider key in Model settings first.")
                current =
                    protocol.read(
                        provider.stream(settings, key, protocol.request()) { partial ->
                            currentCoroutineContext().ensureActive()
                            val latest = store.messages(pending.conversationId).firstOrNull { it.id == pending.id }
                            if (latest?.state == MessageState.GENERATING) {
                                store.saveMessage(latest.copy(text = partial))
                                onChanged()
                            }
                        },
                    )
                ;rounds++
                outputs = mutableListOf()
            }
            val round = requireNotNull(current)
            if (round.calls.isEmpty())return round.text
            for (index in outputs.size until round.calls.size) {
                currentCoroutineContext().ensureActive()
                require(store.checkpoints().none { it.turnId == pending.id && it.phase == ContinuationPhase.INTERRUPTED }) { "This turn was stopped." }
                val call = round.calls[index]
                val previous = store.toolEvents(pending.conversationId).find { it.turnId == pending.id && it.callId == call.id }
                val result =
                    if (previous != null) {
                        check(previous.name == call.name && previous.arguments == call.arguments) { "The model reused a tool identity for a different action." }
                        previous.result
                    } else if (waitedIndex?.let { index > it } == true) {
                        record(call, pending, null, NOT_RUN_WHILE_WAITING, true)
                    } else if (call.name == askPersonTool.name) {
                        val parsed = runCatching { parseQuestion(call) }
                        if (parsed.isFailure) {
                            record(call, pending, null, refusal(parsed.exceptionOrNull()?.message ?: "Say what you need a person to answer."), true)
                        } else {
                            val (question, why, parts) = parsed.getOrThrow()
                            val request = LocalQuestion(UUID.randomUUID().toString(), pending.id, pending.conversationId, botId, call, question, why, parts, Instant.now().toString())
                            QuestionStore(store).wait(
                                AgentCheckpoint(
                                    pending.id,
                                    pending.conversationId,
                                    botId,
                                    settings,
                                    tools,
                                    protocol.snapshot(),
                                    round,
                                    outputs.toList(),
                                    "",
                                    Instant.now().toString(),
                                    routineRunId = routineRunId,
                                    roundCount = rounds,
                                    goalRunId = goalRunId,
                                    questionId = request.id,
                                ),
                                request,
                            )
                            onChanged()
                            currentCoroutineContext().ensureActive()
                            return null
                        }
                    } else if (!call.name.startsWith("mcp_")) {
                        builtin(call, botId, pending.conversationId, pending.id)
                    } else {
                        val decision = answeredAction?.takeIf { it.call.id == call.id }
                        val binding = binding(botId, call.name)
                        if (decision?.status == LocalActionStatus.DENIED) {
                            answeredAction = null
                            record(call, pending, decision, DECLINED_BY_PERSON, true, LocalActionStatus.DENIED)
                        } else if (decision?.status == LocalActionStatus.HANDLED) {
                            answeredAction = null
                            record(call, pending, decision, HANDLED_BY_PERSON, false, LocalActionStatus.HANDLED)
                        } else if (binding == null) {
                            answeredAction = null
                            record(call, pending, decision, notDoneOnRecheck("this connected tool is no longer granted to the Bot."), true, LocalActionStatus.CANCELLED)
                        } else {
                            val(connection, tool) = binding
                            try {
                                validateToolArguments(AgentTool(call.name, tool.description, tool.inputSchema), call.arguments)
                            } catch (failure: Exception) {
                                answeredAction = null
                                outputs.add(record(call, pending, decision, refusal(failure.message ?: "Invalid tool arguments."), true, LocalActionStatus.CANCELLED))
                                continue
                            }
                            val action = decision
                            if (action == null) {
                                val uncertain = store.pendingActions().any { it.channelId == pending.conversationId && it.connectionId == connection.id && it.tool.name == tool.name && it.call.arguments == call.arguments && it.status == LocalActionStatus.UNCERTAIN }
                                if (uncertain) {
                                    outputs.add(record(call, pending, null, OUTCOME_UNKNOWN, true))
                                    continue
                                }
                                val outcome = policy.decide(connectedCandidate(botId, connection.id, connection.url, tool, call.arguments), pending.conversationId)
                                val request =
                                    PendingLocalAction(
                                        UUID.randomUUID().toString(),
                                        pending.id,
                                        pending.conversationId,
                                        botId,
                                        connection.id,
                                        connection.url,
                                        connection.credentialRef,
                                        tool,
                                        call,
                                        Instant.now().toString(),
                                        status = if (outcome.behaviour == PolicyBehaviour.ALLOW)LocalActionStatus.APPROVED else LocalActionStatus.PENDING,
                                        automatic = outcome.behaviour == PolicyBehaviour.ALLOW,
                                        policy = outcome,
                                        connectionName = connection.name,
                                        goalRunId = goalRunId,
                                        routineRunId = routineRunId,
                                    )
                                if (outcome.behaviour == PolicyBehaviour.ALLOW) {
                                    store.savePendingAction(request)
                                    outputs.add(executeAction(request, connection, tool, call, pending))
                                    onChanged()
                                    continue
                                }
                                store.waitForApproval(
                                    AgentCheckpoint(
                                        pending.id,
                                        pending.conversationId,
                                        botId,
                                        settings,
                                        tools,
                                        protocol.snapshot(),
                                        round,
                                        outputs.toList(),
                                        request.id,
                                        Instant.now().toString(),
                                        routineRunId = routineRunId,
                                        roundCount = rounds,
                                        goalRunId = goalRunId,
                                    ),
                                    request,
                                )
                                onChanged()
                                currentCoroutineContext().ensureActive()
                                return null
                            }
                            answeredAction = null
                            executeAction(action, connection, tool, call, pending)
                        }
                    }
                outputs.add(result)
                store.checkpoints().find { it.turnId == pending.id && it.phase == ContinuationPhase.RUNNING }?.let { saved ->
                    store.saveCheckpoint(saved.copy(round = round, history = protocol.snapshot(), results = outputs.toList(), roundCount = rounds))
                }
                onChanged()
            }
            protocol.continueWith(round, outputs)
            current = null
            waitedIndex = null
        }
    }

    private fun binding(
        botId: String,
        modelName: String,
    ): Pair<LocalConnection, McpTool>? {
        for (connection in store.connections()) {
            for (tool in connection.tools) {
                if (tool.name in connection.grants[botId].orEmpty() && mcpModelToolName(connection.id, tool.name) == modelName)return connection to tool
            }
        }
        return null
    }

    private fun unchanged(
        action: PendingLocalAction,
        connection: LocalConnection,
        tool: McpTool,
    ): Boolean =
        action.connectionId == connection.id && action.connectionUrl == connection.url && action.credentialRef == connection.credentialRef && action.tool == tool &&
            tool.name in connection.grants[action.botId].orEmpty() && store.bots().any { it.id == action.botId && !it.paused } && store.pendingActions().any { it.id == action.id && it.status == LocalActionStatus.APPROVED }

    private suspend fun executeAction(
        action: PendingLocalAction,
        connection: LocalConnection,
        tool: McpTool,
        call: ToolCall,
        pending: LocalMessage,
    ): String {
        require(action.call == call) { "The tool action changed after approval." }
        if (action.status == LocalActionStatus.DENIED)return record(call, pending, action, DECLINED_BY_PERSON, true, LocalActionStatus.DENIED)
        if (action.status == LocalActionStatus.HANDLED)return record(call, pending, action, HANDLED_BY_PERSON, false, LocalActionStatus.HANDLED)
        if (action.status != LocalActionStatus.APPROVED)return record(call, pending, action, OUTCOME_UNKNOWN, true, LocalActionStatus.UNCERTAIN)
        if (!unchanged(action, connection, tool))return record(call, pending, action, notDoneOnRecheck("the connection, credential, tool, grant or Bot status changed."), true, LocalActionStatus.CANCELLED)
        val currentPolicy = if (action.automatic)action.policy ?: LocalPolicyOutcome(PolicyBehaviour.ASK, "default", "The saved policy could not be restored.") else policy.decide(pendingCandidate(action), pending.conversationId)
        if (currentPolicy.behaviour == PolicyBehaviour.HAND_OFF || action.automatic && currentPolicy.behaviour != PolicyBehaviour.ALLOW) {
            return record(call, pending, action, notDoneOnRecheck(currentPolicy.reason), true, LocalActionStatus.CANCELLED)
        }
        var started = false
        val session = sessions(connection, connection.credentialRef?.let(secrets::token))
        try {
            session.initialize()
            val fresh = binding(action.botId, call.name)
            if (fresh == null || !unchanged(action, fresh.first, fresh.second))return record(call, pending, action, notDoneOnRecheck("access changed before execution."), true, LocalActionStatus.CANCELLED)
            if (!store.beginApprovedAction(action.id))return record(call, pending, action, NOT_DONE, true, LocalActionStatus.CANCELLED)
            started = true
            val result = session.call(tool, call.arguments)
            val failed = result["isError"]?.jsonPrimitive?.booleanOrNull == true
            return record(call, pending, action, result.toString(), failed, if (failed)LocalActionStatus.FAILED else LocalActionStatus.EXECUTED)
        } catch (failure: CancellationException) {
            record(call, pending, action, if (started)OUTCOME_UNKNOWN else NOT_DONE, true, if (started)LocalActionStatus.UNCERTAIN else LocalActionStatus.CANCELLED)
            throw failure
        } catch (failure: Exception) {
            return record(call, pending, action, if (started)OUTCOME_UNKNOWN else "Not done: ${failure.message.orEmpty().take(400)}", true, if (started)LocalActionStatus.UNCERTAIN else LocalActionStatus.FAILED)
        } finally {
            withContext(NonCancellable) { runCatching { session.close() } }
        }
    }

    private fun connectionName(id: String) = store.connections().find { it.id == id }?.name ?: "Connected app"

    private fun refusal(message: String) =
        buildJsonObject {
            put("isError", true)
            put("message", message)
        }.toString()

    private fun record(
        call: ToolCall,
        pending: LocalMessage,
        action: PendingLocalAction?,
        result: String,
        failed: Boolean,
        status: LocalActionStatus? = null,
    ): String {
        val db = store.writableDatabase
        db.beginTransaction()
        try {
            store.saveToolEvent(LocalToolEvent(UUID.randomUUID().toString(), pending.id, pending.conversationId, call.id, call.name, call.arguments, result, failed, Instant.now().toString(), action?.let { "${it.connectionName ?: connectionName(it.connectionId)} · ${it.tool.name.replace('_',' ')}" }))
            if (action != null && status != null)store.savePendingAction(action.copy(status = status))
            db.setTransactionSuccessful()
        } finally {
            db.endTransaction()
            LocalDatabaseChanges.changed()
        }
        return result
    }
}
}

// ===== ORIGINAL RUNTIME FILE: android/app/src/main/kotlin/ai/openbot/android/inference/TranscriptionProvider.kt =====
object AS_TranscriptionProvider {
fun transcriptionEndpoint(
    baseUrl: String,
    model: String,
): URI {
    providerEndpoint(ProviderSettings(baseUrl = baseUrl, model = model))
    require(model.none { it == '\r' || it == '\n' }) { "Enter a single-line transcription model name." }
    return URI(baseUrl.trim().trimEnd('/') + "/audio/transcriptions")
}

class TranscriptionError(
    message: String,
) : IllegalStateException(message)

class TranscriptionBody(
    private val audio: DictationAudio,
    model: String,
    val boundary: String = "OpenBot-" + UUID.randomUUID().toString(),
) {
    private val header: ByteArray
    private val footer = "\r\n--$boundary--\r\n".toByteArray(Charsets.UTF_8)
    val length: Long

    init {
        require(boundary.matches(Regex("[A-Za-z0-9-]{1,100}")))
        val type = dictationMediaType(audio.mimeType)
        val extension = dictationExtension(type) ?: error("This recording format is not supported. Use WebM, MP4, or WAV audio.")
        require(audio.file.length() in 1..MAX_DICTATION_BYTES.toLong()) { "The recording is empty or too large. Please record again." }
        header =
            (
                "--$boundary\r\nContent-Disposition: form-data; name=\"model\"\r\n\r\n$model\r\n" +
                    "--$boundary\r\nContent-Disposition: form-data; name=\"file\"; filename=\"recording.$extension\"\r\nContent-Type: $type\r\n\r\n"
            ).toByteArray(Charsets.UTF_8)
        length = header.size.toLong() + audio.file.length() + footer.size
    }

    fun writeTo(output: OutputStream) {
        output.write(header)
        var sent = 0L
        audio.file.inputStream().use { input ->
            val buffer = ByteArray(8192)
            while (true) {
                val count = input.read(buffer)
                if (count < 0)break
                sent += count
                require(sent <= MAX_DICTATION_BYTES) { "The recording is too large." }
                output.write(buffer, 0, count)
            }
        }
        require(header.size + sent + footer.size == length) { "The recording changed before transcription." }
        output.write(footer)
    }
}

class TranscriptionProvider(
    private val configuration: ModelConfiguration,
    private val open: (URI) -> HttpsURLConnection = { it.toURL().openConnection() as HttpsURLConnection },
) {
    suspend fun transcribe(audio: DictationAudio): String =
        withContext(Dispatchers.IO) {
            coroutineScope {
                val (settings, key) =
                    try {
                        configuration.snapshot()
                    } catch (_: Exception) {
                        throw TranscriptionError("The transcription settings could not be opened. Save them again in Dictation settings.")
                    }
                val endpoint = transcriptionEndpoint(settings.baseUrl, settings.model)
                val body = TranscriptionBody(audio, settings.model)
                require(key == null || key.none { it == '\r' || it == '\n' }) { "Save a valid transcription provider key." }
                val connection = open(endpoint)
                val cancellation =
                    launch(Dispatchers.IO, start = CoroutineStart.UNDISPATCHED) {
                        try {
                            awaitCancellation()
                        } finally {
                            connection.disconnect()
                        }
                    }
                try {
                    connection.requestMethod = "POST"
                    connection.instanceFollowRedirects = false
                    connection.connectTimeout = 20_000
                    connection.readTimeout = DICTATION_TIMEOUT_MS.toInt()
                    key?.takeIf { it.isNotBlank() }?.let { connection.setRequestProperty("Authorization", "Bearer $it") }
                    connection.setRequestProperty("Content-Type", "multipart/form-data; boundary=${body.boundary}")
                    connection.setRequestProperty("Accept", "application/json")
                    connection.doOutput = true
                    connection.setFixedLengthStreamingMode(body.length)
                    connection.outputStream.use { body.writeTo(it) }
                    val status = connection.responseCode
                    if (status !in 200..299) {
                        throw TranscriptionError(
                            when (status) {
                                401, 403 -> "The transcription provider refused the key. Check it in Dictation settings."
                                429 -> "The transcription service is busy. Please retry shortly."
                                in 300..399 -> "The transcription service redirected the request. Save its final HTTPS URL in Dictation settings."
                                else -> "Couldn't process this recording. Check Dictation settings and try again."
                            },
                        )
                    }
                    val response =
                        connection.inputStream.use { input ->
                            val result = ByteArrayOutputStream()
                            val buffer = ByteArray(8192)
                            while (true) {
                                val count = input.read(buffer)
                                if (count < 0)break
                                if (result.size() + count > 1024 * 1024)throw TranscriptionError("The transcription service returned an invalid response. Please retry.")
                                result.write(buffer, 0, count)
                            }
                            result.toString("UTF-8")
                        }
                    val parsed = runCatching { Json.parseToJsonElement(response).jsonObject["text"] as? JsonPrimitive }.getOrNull()
                    if (parsed == null || !parsed.isString)throw TranscriptionError("The transcription service returned an invalid response. Please retry.")
                    parsed.content
                } catch (failure: CancellationException) {
                    throw failure
                } catch (failure: TranscriptionError) {
                    throw failure
                } catch (_: Exception) {
                    throw TranscriptionError("Couldn't reach the transcription service. Try again.")
                } finally {
                    cancellation.cancel()
                    connection.disconnect()
                }
            }
        }
}
}

// ===== ORIGINAL RUNTIME FILE: android/app/src/main/kotlin/ai/openbot/android/inference/TurnAttachments.kt =====
object AS_TurnAttachments {
internal data class TurnAttachments(
    val content: JsonArray?,
    val selected: List<LocalAttachment>,
)

/** The current send is included whole; older files share the remaining original 32 MB budget. */
internal fun prepareTurnAttachments(
    settings: ProviderSettings,
    channelId: String,
    prompt: String,
    history: List<LocalMessage>,
    includedMessages: List<String>,
    current: LocalMessage,
    currentFiles: List<LocalAttachment>,
    store: AttachmentStore,
): TurnAttachments {
    val byId = store.conversation(channelId).associateBy { it.id }
    val selected = mutableListOf<LocalAttachment>()
    selected.addAll(currentFiles)
    var remaining = MAX_INLINED_BYTES_PER_RUN - currentFiles.sumOf { it.size }
    require(remaining >= 0) { "This message's attachments exceed the 32MB limit. Send fewer files in each message." }
    val parts = mutableMapOf<String, List<JsonObject>>()

    fun text(value: String) =
        buildJsonObject {
            put("type", if (settings.apiStyle == ApiStyle.RESPONSES)"input_text" else "text")
            put("text", value)
        }

    fun part(attachment: LocalAttachment): JsonObject {
        val ref = attachmentReference(channelId, attachment.id)
        if (classifyAttachment(attachment.mimeType) == AttachmentKind.TEXT)return text(ref)
        return buildJsonObject {
            put("type", if (settings.apiStyle == ApiStyle.RESPONSES)"input_image" else "image_url")
            if (settings.apiStyle == ApiStyle.RESPONSES)put("image_url", ref) else put("image_url", buildJsonObject { put("url", ref) })
        }
    }
    for (message in history.filter { it.id != current.id && it.id in includedMessages }.asReversed()) {
        parts[message.id] =
            message.attachmentIds.map { id ->
                val attachment = byId[id]
                if (attachment == null || store.preview(id, null, channelId) == null) {
                    text("[attachment \"${attachment?.name ?: id}\" is no longer available]")
                } else if (attachment.size > remaining) {
                    remaining = 0
                    text("[attachment \"${attachment.name}\" from an earlier message was not included in this turn]")
                } else {
                    remaining -= attachment.size
                    selected.add(attachment)
                    part(attachment)
                }
            }
    }
    if (selected.isEmpty() && parts.values.all { it.isEmpty() })return TurnAttachments(null, emptyList())
    val content =
        buildJsonArray {
            add(text(prompt))
            for (message in history.filter { it.id != current.id && it.id in includedMessages }) {
                val values = parts[message.id].orEmpty()
                if (values.isNotEmpty()) {
                    add(text("Files from the earlier user message at ${message.createdAt}: ${message.text.take(300)}"))
                    values.forEach { add(it) }
                }
            }
            if (currentFiles.isNotEmpty()) {
                add(text("Files attached to the current user message:"))
                currentFiles.forEach { add(part(it)) }
            }
        }
    return TurnAttachments(content, selected)
}

/** Restore only references actually kept in the durable provider history, bound to its conversation. */
internal fun checkpointAttachments(
    history: JsonArray,
    channelId: String,
    store: AttachmentStore,
): List<LocalAttachment> {
    val available = store.conversation(channelId).associateBy { attachmentReference(channelId, it.id) }
    val found = mutableSetOf<String>()

    fun visit(value: JsonElement) {
        when (value) {
            is JsonObject -> {
                attachmentPartReference(value)?.let { found.add(it) }
                value.values.forEach { visit(it) }
            }
            is JsonArray -> value.forEach { visit(it) }
            is JsonPrimitive -> Unit
        }
    }
    visit(history)
    return found.map { available[it] ?: error("An attachment from this waiting turn is no longer available.") }
}
}

// ===== ORIGINAL RUNTIME FILE: android/app/src/main/kotlin/ai/openbot/android/notifications/LocalNotifications.kt =====
object AS_LocalNotifications {
/** Android delivery for the phone's own local agent; no remote push service or device token. */
object LocalNotifications {
    const val CHANNEL = "agentstudio"
    private const val SEEN = "delivered"

    fun allowed(context: Context): Boolean =
        (Build.VERSION.SDK_INT < 33 || context.checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS) == PackageManager.PERMISSION_GRANTED) &&
            context.getSystemService(NotificationManager::class.java).areNotificationsEnabled() &&
            context.getSystemService(NotificationManager::class.java).getNotificationChannel(CHANNEL)?.importance != NotificationManager.IMPORTANCE_NONE

    private fun manager(context: Context) = context.getSystemService(NotificationManager::class.java)

    fun createChannel(context: Context) {
        manager(context).createNotificationChannel(
            NotificationChannel(CHANNEL, "OpenBot", NotificationManager.IMPORTANCE_HIGH).apply {
                description = "Answers, questions and approvals from your Bots"
                lockscreenVisibility = Notification.VISIBILITY_PRIVATE
            },
        )
    }

    @Synchronized fun sync(
        context: Context,
        store: LocalStore,
    ) {
        createChannel(context)
        if (!store.preferences().notificationsEnabled || !allowed(context)) {
            clear(context)
            return
        }
        val waiting =
            buildMap<String, Triple<String, String, String>> {
                for (action in store.pendingActions().filter { it.status == LocalActionStatus.PENDING }) {
                    val bot = store.bots().find { it.id == action.botId }?.name ?: "Your Bot"
                    put(AgentStudioProfiles.notificationPrefix(context)+"approval:${action.id}", Triple("$bot is waiting for your approval.", action.channelId, action.id))
                }
                for (question in QuestionStore(store).waiting()) {
                    val bot = store.bots().find { it.id == question.botId }?.name ?: "Your Bot"
                    put(AgentStudioProfiles.notificationPrefix(context)+"question:${question.id}", Triple("$bot has a question for you.", question.channelId, question.id))
                }
            }
        val preferences = context.getSharedPreferences("agentstudio-notifications", Context.MODE_PRIVATE)
        val seen = preferences.getStringSet(SEEN, emptySet()).orEmpty()
        for ((tag, values) in waiting)if (tag !in seen)post(context, tag, values.first, "Open OpenBot to answer.", "approvals", values.second, values.third)
        // Dismissing an Android notification does not make it reappear on every database change.
        preferences.edit().putStringSet(SEEN, waiting.keys).apply()
        manager(context)
            .activeNotifications
            .filter { it.tag?.startsWith(AgentStudioProfiles.notificationPrefix(context)+"approval:") == true || it.tag?.startsWith(AgentStudioProfiles.notificationPrefix(context)+"question:") == true }
            .filter { it.tag !in waiting }
            .forEach { manager(context).cancel(it.tag, it.id) }
        val channels = store.conversations().map { it.id }.toSet()
        manager(context)
            .activeNotifications
            .filter { it.tag?.startsWith(AgentStudioProfiles.notificationPrefix(context)+"reply:") == true && it.notification.extras.getString("agentstudio-channel") !in channels }
            .forEach { manager(context).cancel(it.tag, it.id) }
    }

    @Synchronized fun reply(
        context: Context,
        store: LocalStore,
        message: LocalMessage,
        botId: String,
    ) {
        if (message.state != MessageState.COMPLETE || !store.preferences().notificationsEnabled || !allowed(context) || store.conversations().none { it.id == message.conversationId })return
        val name = store.bots().find { it.id == botId }?.name ?: "Your Bot"
        post(context, AgentStudioProfiles.notificationPrefix(context)+"reply:${message.id}", name, "Your Bot has finished. Open the conversation to read its reply.", "conversation", message.conversationId, null)
    }

    private fun post(
        context: Context,
        tag: String,
        title: String,
        body: String,
        path: String,
        channelId: String,
        requestId: String?,
    ) {
        createChannel(context)
        val uri =
            Uri
                .Builder()
                .scheme("openbotmobile")
                .authority(path)
                .appendQueryParameter("channelId", channelId)
                .apply { requestId?.let { appendQueryParameter("requestId", it) } }
                .build()
        val intent = Intent(context, MainActivity::class.java).putExtra(AgentStudioProfiles.PROFILE_KEY,AgentStudioProfiles.id(context)).setData(uri).addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP or Intent.FLAG_ACTIVITY_SINGLE_TOP)
        val content = PendingIntent.getActivity(context, 0, intent, PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE)
        val public =
            Notification
                .Builder(context, CHANNEL)
                .setSmallIcon(AgentStudioResources.notificationIcon(R.drawable.ic_bolt))
                .setContentTitle("OpenBot")
                .setContentText("A Bot has an update for you.")
                .build()
        val notification =
            Notification
                .Builder(context, CHANNEL)
                .setSmallIcon(AgentStudioResources.notificationIcon(R.drawable.ic_bolt))
                .setContentTitle(title)
                .setContentText(body)
                .setContentIntent(content)
                .setAutoCancel(true)
                .setOnlyAlertOnce(true)
                .setVisibility(Notification.VISIBILITY_PRIVATE)
                .setPublicVersion(public)
                .setCategory(Notification.CATEGORY_MESSAGE)
                .addExtras(android.os.Bundle().apply { putString("agentstudio-channel", channelId) })
                .build()
        try {
            manager(context).notify(tag, 0, notification)
        } catch (_: SecurityException) {
            // Permission can be revoked between checking and posting.
        }
    }

    @Synchronized fun clear(context: Context) {
        manager(context)
            .activeNotifications
            .filter { it.tag?.let { tag -> tag.startsWith(AgentStudioProfiles.notificationPrefix(context)+"approval:") || tag.startsWith(AgentStudioProfiles.notificationPrefix(context)+"question:") || tag.startsWith(AgentStudioProfiles.notificationPrefix(context)+"reply:") } == true }
            .forEach { manager(context).cancel(it.tag, it.id) }
        context
            .getSharedPreferences("agentstudio-notifications", Context.MODE_PRIVATE)
            .edit()
            .remove(SEEN)
            .apply()
    }
}
}

// ===== ORIGINAL RUNTIME FILE: android/app/src/main/kotlin/ai/openbot/android/ui/AdaptiveNavigation.kt =====
object AS_AdaptiveNavigation {
internal val LocalExpandedNavigation = staticCompositionLocalOf { false }

/** Keep navigation visible on tablets/landscape and keep long chat lines readable. */
@Composable internal fun AdaptiveNavigation(
    drawerState: DrawerState,
    gesturesEnabled: Boolean,
    sidebar: @Composable () -> Unit,
    content: @Composable () -> Unit,
) {
    val palette = LocalOpenBotPalette.current
    BoxWithConstraints(Modifier.fillMaxSize()) {
        val expanded = maxWidth >= 840.dp
        CompositionLocalProvider(LocalExpandedNavigation provides expanded) {
            if (expanded) {
                PermanentNavigationDrawer(drawerContent = {
                    PermanentDrawerSheet(
                        Modifier.width(288.dp),
                        drawerShape = RectangleShape,
                        drawerContainerColor = palette.sidebar,
                        drawerTonalElevation = 0.dp,
                    ) { sidebar() }
                }) {
                    Box(Modifier.fillMaxSize(), contentAlignment = Alignment.TopCenter) {
                        Box(Modifier.widthIn(max = 1000.dp).fillMaxSize()) { content() }
                    }
                }
            } else {
                ModalNavigationDrawer(drawerState = drawerState, gesturesEnabled = gesturesEnabled, drawerContent = {
                    ModalDrawerSheet(
                        Modifier.width(288.dp),
                        drawerShape = RectangleShape,
                        drawerContainerColor = palette.sidebar,
                        drawerTonalElevation = 0.dp,
                    ) { sidebar() }
                }, content = content)
            }
        }
    }
}
}

