    return { launcher.launch(arrayOf("*/*")) }
}

@OptIn(ExperimentalLayoutApi::class)
@Composable
internal fun AttachmentStrip(
    files: List<LocalAttachment>,
    vm: OpenBotViewModel,
    removable: Boolean = false,
    enabled: Boolean = true,
) {
    if (files.isEmpty())return
    val p = LocalOpenBotPalette.current
    FlowRow(Modifier.fillMaxWidth().padding(bottom = 12.dp).testTag("attachment-strip"), horizontalArrangement = Arrangement.spacedBy(8.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
        files.forEach { file ->
            key(file.id) {
                val image = classifyAttachment(file.mimeType) == AttachmentKind.IMAGE
                Box(Modifier.width(if (image)80.dp else 160.dp).height(80.dp).testTag("attachment-${file.id}")) {
                    val shape = RoundedCornerShape(12.dp)
                    if (image) {
                        val bitmap by produceState<android.graphics.Bitmap?>(null, file.id) {
                            value =
                                withContext(Dispatchers.IO) {
                                    val local = vm.attachmentFile(file) ?: return@withContext null
                                    runCatching {
                                        val bounds = BitmapFactory.Options().apply { inJustDecodeBounds = true }
                                        local.inputStream().use { BitmapFactory.decodeStream(it, null, bounds) }
                                        var sample = 1
                                        while (bounds.outWidth / sample > 160 || bounds.outHeight / sample > 160)sample *= 2
                                        local.inputStream().use { BitmapFactory.decodeStream(it, null, BitmapFactory.Options().apply { inSampleSize = sample }) }
                                    }.getOrNull()
                                }
                        }
                        Box(
                            Modifier
                                .fillMaxSize()
                                .clip(shape)
                                .background(p.muted)
                                .border(1.dp, p.border, shape)
                                .clickable(enabled = enabled) { vm.openAttachment(file) },
                            contentAlignment = Alignment.Center,
                        ) {
                            bitmap?.let { Image(it.asImageBitmap(), file.name, Modifier.fillMaxSize(), contentScale = ContentScale.Crop) } ?: Text(file.name, Modifier.padding(8.dp), maxLines = 2, overflow = TextOverflow.Ellipsis, style = MaterialTheme.typography.bodySmall)
                        }
                    } else {
                        Surface(Modifier.fillMaxSize().clickable(enabled = enabled) { vm.openAttachment(file) }, shape = shape, color = p.muted.copy(alpha = .4f), border = BorderStroke(1.dp, p.border)) {
                            Column(Modifier.padding(8.dp), verticalArrangement = Arrangement.SpaceBetween) {
                                TablerIcon(R.drawable.ic_file, modifier = Modifier.size(20.dp))
                                Column {
                                    Text(file.name, maxLines = 1, overflow = TextOverflow.Ellipsis, style = MaterialTheme.typography.labelMedium)
                                    val size =
                                        when {
                                            file.size < 1024 -> "${file.size}B"
                                            file.size < 1024 * 1024 -> "${kotlin.math.floor(file.size / 1024.0 + .5).toInt()}KB"
                                            else -> String.format(Locale.ROOT, "%.1fMB", file.size / (1024.0 * 1024))
                                        }
                                    Text(size + if (mayBeTruncatedForModel(file.size))" · may be cut" else "", color = p.mutedForeground, maxLines = 1, overflow = TextOverflow.Ellipsis, style = MaterialTheme.typography.bodySmall)
                                }
                            }
                        }
                    }
                    if (removable) {
                        IconButton(onClick = { vm.removeAttachment(file.id) }, enabled = enabled, modifier = Modifier.align(Alignment.TopEnd).padding(4.dp).size(20.dp)) {
                            Box(Modifier.size(20.dp).background(p.background.copy(alpha = .9f), RoundedCornerShape(100)).border(1.dp, p.border, RoundedCornerShape(100)), contentAlignment = Alignment.Center) {
                                TablerIcon(R.drawable.ic_x, "Remove ${file.name}", Modifier.size(12.dp))
                            }
                        }
                    }
                }
            }
        }
    }
}
}

// ===== ORIGINAL RUNTIME FILE: android/app/src/main/kotlin/ai/openbot/android/ui/BotAvatar.kt =====
object AS_BotAvatar {
/** Kotlin rendering of boring-avatars' default marble variant used by AbstractAvatar.tsx. */
@Composable internal fun BotAvatar(
    name: String,
    seed: String,
    size: Dp = 28.dp,
) {
    val bitmap = remember(seed) { marble(seed).asImageBitmap() }
    Image(bitmap, name, Modifier.size(size))
}

private fun marble(seed: String): android.graphics.Bitmap {
    val colors = listOf("#92A1C6", "#146A7C", "#F0AB3D", "#C271B4", "#C20D90")
    val hash = abs(seed.hashCode().toLong())

    fun digit(
        value: Long,
        position: Int,
    ) = (value / 10.0.pow(position)).toLong() % 10

    fun unit(
        value: Long,
        range: Int,
        position: Int? = null,
    ): Float {
        val number = (value % range).toFloat()
        return if (position != null && digit(value, position) % 2 == 0L)-number else number
    }
    val bitmap = android.graphics.Bitmap.createBitmap(80, 80, android.graphics.Bitmap.Config.ARGB_8888)
    val canvas = android.graphics.Canvas(bitmap)
    val clip = android.graphics.Path().apply { addCircle(40f, 40f, 40f, android.graphics.Path.Direction.CW) }
    canvas.clipPath(clip)
    canvas.drawColor(android.graphics.Color.parseColor(colors[(hash % 5).toInt()]))
    val scale = 1.2f + unit(hash * 3, 4) / 10f
    val paths =
        listOf(
            "M32.414 59.35L50.376 70.5H72.5v-71H33.728L26.5 13.381l19.057 27.08L32.414 59.35z",
            "M22.216 24L0 46.75l14.108 38.129L78 86l-3.081-59.276-22.378 4.005 12.972 20.186-23.35 27.395L22.215 24z",
        )
    for (index in 1..2) {
        val value = hash * (index + 1)
        val paint =
            android.graphics.Paint(android.graphics.Paint.ANTI_ALIAS_FLAG).apply {
                color = android.graphics.Color.parseColor(colors[((hash + index) % 5).toInt()])
                maskFilter = BlurMaskFilter(11.25f, BlurMaskFilter.Blur.NORMAL)
                if (index == 2)xfermode = PorterDuffXfermode(PorterDuff.Mode.OVERLAY)
            }
        canvas.save()
        canvas.translate(unit(value, 8, 1), unit(value, 8, 2))
        canvas.rotate(unit(value, 360, 1), 40f, 40f)
        canvas.scale(scale, scale)
        canvas.drawPath(PathParser.createPathFromPathData(paths[index - 1])!!, paint)
        canvas.restore()
    }
    return bitmap
}
}

