                                    p.ring.copy(alpha = .5f),
                                    topLeft =
                                        androidx.compose.ui.geometry
                                            .Offset(-1.5.dp.toPx(), -1.5.dp.toPx()),
                                    size =
                                        androidx.compose.ui.geometry
                                            .Size(size.width + 3.dp.toPx(), size.height + 3.dp.toPx()),
                                    cornerRadius = CornerRadius(11.5.dp.toPx()),
                                    style = Stroke(3.dp.toPx()),
                                )
