object AS_ConversationScreen {
/** Same end-aligned muted user bubbles and full-width ghost replies as chat-transcript.tsx. */
@Composable internal fun ConversationScreen(
    state: AppState,
    bot: LocalBot?,
    vm: OpenBotViewModel,
) {
    val p = LocalOpenBotPalette.current
    var text by rememberSaveable(state.selectedConversation ?: state.draftBotId) { mutableStateOf("") }
    val scroll = rememberLazyListState()
    val attach = rememberAttachmentPicker(vm)
    val backgroundTurn =
        state.messages
            .lastOrNull { it.state == MessageState.GENERATING }
            ?.takeIf { message -> message.id in state.continuingTurns }
            ?.id
    val question = state.questions.firstOrNull { it.channelId == state.selectedConversation }
    val stop: (() -> Unit)? = if (state.generatingChannelId == state.selectedConversation && state.generatingChannelId != null)vm::stopGeneration else backgroundTurn?.let { id -> { vm.stopContinuation(id) } }
    LaunchedEffect(state.messages.size) { if (state.messages.isNotEmpty())scroll.animateScrollToItem(state.messages.lastIndex) }
    Column(Modifier.fillMaxSize().padding(horizontal = 16.dp), verticalArrangement = Arrangement.spacedBy(12.dp)) {
        if (bot?.paused == true)Text("This Bot is paused. Resume it before sending a message.", color = p.mutedForeground)
        LazyColumn(Modifier.weight(1f).fillMaxWidth().testTag("transcript"), state = scroll, contentPadding = PaddingValues(vertical = 16.dp), verticalArrangement = Arrangement.spacedBy(if(LocalAgentStudioChat.current)12.dp else 24.dp)) {
            itemsIndexed(state.messages, key = { _,message -> message.id }) { index,message ->
                if(LocalAgentStudioChat.current && (index==0 || state.messages[index-1].createdAt.take(10)!=message.createdAt.take(10))) {
                    val stamp=runCatching { val time=java.time.Instant.parse(message.createdAt).atZone(java.time.ZoneId.systemDefault());val today=java.time.LocalDate.now();(if(time.toLocalDate()==today)"Today "else time.format(java.time.format.DateTimeFormatter.ofPattern("d MMM ")))+time.format(java.time.format.DateTimeFormatter.ofPattern("h:mm a")) }.getOrDefault("")
                    Text(stamp,Modifier.fillMaxWidth().padding(vertical=12.dp),textAlign=androidx.compose.ui.text.style.TextAlign.Center,color=p.mutedForeground,style=MaterialTheme.typography.bodySmall)
                }
                val events = state.toolEvents.filter { it.turnId == message.id }
                if (events.isNotEmpty())ToolActivity(events, state)
                state.pendingActions.filter { it.turnId == message.id && it.status == LocalActionStatus.UNCERTAIN }.forEach { UnknownActionCard(it, state, vm) }
                val firing = readFiring(message.text)
                if (message.role == "user" && message.systemLabel != null) {
                    Column(verticalArrangement = Arrangement.spacedBy(6.dp)) {
                        message.systemLabel?.let { Text(it, color = p.mutedForeground, style = MaterialTheme.typography.bodySmall) }
                        message.displayText?.let { Text(it, color = p.mutedForeground) }
                    }
                } else if (message.role == "user" && firing == null) {
                    Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.End) {
                        Surface(color = if(LocalAgentStudioChat.current)androidx.compose.ui.graphics.Color.Black else p.muted.copy(alpha = .5f), shape = RoundedCornerShape(12.dp), modifier = Modifier.widthIn(max = 560.dp)) {
                            Column {
                                AttachmentStrip(message.attachmentIds.mapNotNull { id -> state.conversationAttachments.find { it.id == id } }, vm, enabled = !state.busy)
                                if (message.text.isNotBlank())SelectionContainer { Text(message.displayText ?: message.text, Modifier.padding(horizontal = 12.dp, vertical = 8.dp), style = MaterialTheme.typography.bodyMedium, color = if(LocalAgentStudioChat.current)androidx.compose.ui.graphics.Color.White else p.foreground) }
                            }
                        }
                    }
                } else if (message.state == MessageState.GENERATING) {
                    Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                        if (message.text.isNotBlank() && message.text != "Working…")Surface(color = if(LocalAgentStudioChat.current)p.muted.copy(alpha=.6f) else androidx.compose.ui.graphics.Color.Transparent, shape = RoundedCornerShape(18.dp)) { SelectionContainer { Box(Modifier.padding(if(LocalAgentStudioChat.current)12.dp else 0.dp)) { MarkdownBody(message.text) } } }
                        WorkingIndicator(state.stopping)
                    }
                } else if (message.state == MessageState.WAITING) {
                    val pending = state.pendingActions.filter { it.turnId == message.id && it.status == LocalActionStatus.PENDING }
                    pending.forEach { ApprovalCard(it, state, vm) }
                    state.questions.filter { it.turnId == message.id }.forEach { QuestionCard(it, state, vm) }
                    if (pending.isEmpty() && state.questions.none { it.turnId == message.id })Text("Continuing after your decision…", color = p.mutedForeground)
                    OpenBotTextButton(onClick = { vm.stopContinuation(message.id) }, enabled = !state.busy) { Text("Stop this turn") }
                } else if (message.state in listOf(MessageState.FAILED, MessageState.INTERRUPTED)) {
                    Text(message.text, color = p.destructive)
                } else if (firing != null) {
                    Text("Routine · $firing", color = p.mutedForeground)
                } else {
                    Surface(color = if(LocalAgentStudioChat.current)p.muted.copy(alpha=.6f) else androidx.compose.ui.graphics.Color.Transparent, shape = RoundedCornerShape(18.dp)) { SelectionContainer { Box(Modifier.padding(if(LocalAgentStudioChat.current)12.dp else 0.dp)) { MarkdownBody(message.text) } } }
                }
            }
        }
        SourceComposer(text, { text = it }, { if (question != null)vm.answerQuestion(question.id, text) { text = "" } else vm.send(text) { text = "" } }, !state.busy && !state.attachmentsLoading && bot?.paused == false && (question != null || state.messages.none { it.state in listOf(MessageState.WAITING, MessageState.GENERATING) }), compact = true, onStop = stop, stopping = state.stopping, hasAttachments = question == null && state.draftAttachments.isNotEmpty(), onAttach = if (question == null)attach else null, attachments = { if (question == null)AttachmentStrip(state.draftAttachments, vm, removable = true, enabled = !state.busy) })
        Spacer(Modifier.height(4.dp))
    }
}

@Composable private fun WorkingIndicator(stopping: Boolean) {
    val transition = rememberInfiniteTransition(label = "working")
    val opacity by transition.animateFloat(
        initialValue = .7f,
        targetValue = 1f,
        animationSpec = infiniteRepeatable(tween(1200, easing = LinearEasing), RepeatMode.Reverse),
        label = "working opacity",
    )
    Text(if (stopping)"Stopping…" else "Working…", color = LocalOpenBotPalette.current.foreground, modifier = Modifier.alpha(opacity))
}

@Composable private fun ToolActivity(
    events: List<LocalToolEvent>,
    state: AppState,
) {
    val p = LocalOpenBotPalette.current

    fun label(event: LocalToolEvent): String {
        event.displayName?.let { return it }
        for (connection in state.connections)for (tool in connection.tools)if (mcpModelToolName(connection.id, tool.name) == event.name)return "${connection.name} · ${tool.name.replace('_',' ')}"
        return if (event.name.startsWith("mcp_"))"Connected action" else event.name.replace('_', ' ')
    }
    var expanded by rememberSaveable(events.first().id) { mutableStateOf(false) }
    Column(Modifier.fillMaxWidth(), verticalArrangement = Arrangement.spacedBy(6.dp)) {
        Text(
            "${if (expanded)"▾" else "▸"} ${if (events.size == 1)label(events.first()) else "${events.size} actions"}",
            Modifier.fillMaxWidth().clickable { expanded = !expanded }.padding(vertical = 6.dp),
            style = MaterialTheme.typography.bodyMedium,
            color = p.mutedForeground,
        )
        if (expanded) {
            events.forEach { event ->
                var detail by rememberSaveable(event.id) { mutableStateOf(false) }
                Text(
                    "${if (detail)"▾" else "▸"} ${label(event)}${when (event.result.trim()){
                        OUTCOME_UNKNOWN -> ", outcome unknown"
                        WITHDRAWN_APPROVALS_OFF,WITHDRAWN_RULE_ALLOWS -> ", withdrawn"
                        DECLINED_BY_PERSON -> ", declined"
                        HANDLED_BY_PERSON -> ", done by you"
                        else -> if (event.failed)", didn't work" else ""
                    }}",
                    Modifier.fillMaxWidth().clickable { detail = !detail }.padding(start = 16.dp, top = 6.dp, bottom = 6.dp),
                    color = if (event.failed && event.result !in listOf(WITHDRAWN_APPROVALS_OFF, WITHDRAWN_RULE_ALLOWS))p.destructive else p.mutedForeground,
                )
                if (detail) {
                    SelectionContainer {
                        Column(Modifier.fillMaxWidth().padding(start = 24.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                            Text(event.arguments.toString(), style = MaterialTheme.typography.bodySmall)
                            Text(outcomeForPerson(event.result), style = MaterialTheme.typography.bodySmall)
                        }
                    }
                }
            }
        }
    }
}
}

// ===== ORIGINAL RUNTIME FILE: android/app/src/main/kotlin/ai/openbot/android/ui/DictationControls.kt =====
object AS_DictationControls {
internal data class DictationUi(
    val session: DictationSession,
    val state: DictationState,
    val start: () -> Unit,
    val cancel: () -> Unit,
)

@Composable internal fun rememberDictation(
    enabled: Boolean,
    onTranscript: (String, DictationIntent) -> Unit,
): DictationUi {
    val context = LocalContext.current
    val scope = rememberCoroutineScope()
    val delivered by rememberUpdatedState(onTranscript)
    val pending = remember { arrayOfNulls<CompletableDeferred<Boolean>>(1) }
    val permission = rememberLauncherForActivityResult(ActivityResultContracts.RequestPermission()) { granted -> pending[0]?.complete(granted) }
    val session =
        remember(context) {
            val settings = TranscriptionSettingsStore(context)
            val provider = TranscriptionProvider(settings)
            DictationSession(scope, record = { onError, onLimit ->
                val useProvider = settings.configured()
                if (!useProvider)OnDeviceSpeechRecording.requireAvailable(context)
                if (context.checkSelfPermission(Manifest.permission.RECORD_AUDIO) != PackageManager.PERMISSION_GRANTED) {
                    val answer = CompletableDeferred<Boolean>()
                    pending[0] = answer
                    try {
                        permission.launch(Manifest.permission.RECORD_AUDIO)
                        if (!answer.await()) {
                            onError(IllegalStateException("Microphone access was denied. Allow it in Android settings and try again."))
                            throw CancellationException("Microphone permission denied.")
                        }
                    } finally {
                        if (pending[0] === answer)pending[0] = null
                    }
                }
                if (useProvider) {
                    AndroidAudioRecording.create(context, onError, onLimit)
                } else {
                    OnDeviceSpeechRecording.create(context, onError, onLimit)
                }
            }, transcribe = provider::transcribe, onTranscript = { text, intent -> delivered(text, intent) })
        }
    val state by session.state.collectAsState()
    val cancel =
        remember(session) {
            {
                session.cancel()
                pending[0]?.cancel()
                pending[0] = null
                Unit
            }
        }
    val lifecycle = LocalLifecycleOwner.current.lifecycle
    DisposableEffect(lifecycle, session) {
        val observer = LifecycleEventObserver { _, event -> if (event == Lifecycle.Event.ON_STOP)cancel() }
        lifecycle.addObserver(observer)
        onDispose {
            lifecycle.removeObserver(observer)
            cancel()
        }
    }
    LaunchedEffect(enabled) { if (!enabled)cancel() }
    return DictationUi(session, state, {
        scope.launch { session.start() }
        Unit
    }, cancel)
}

@Composable internal fun RecordingControls(
    dictation: DictationUi,
    canSend: Boolean,
) {
    val p = LocalOpenBotPalette.current
    val scope = rememberCoroutineScope()
    val state = dictation.state
    var levels by remember { mutableStateOf(List(24) { 0f }) }
    LaunchedEffect(state.level, state.phase) {
        if (state.phase in listOf(DictationPhase.REQUESTING, DictationPhase.IDLE)) {
            levels = List(24) { 0f }
        } else if (state.phase == DictationPhase.RECORDING) {
            levels = (levels.drop(1) + state.level)
        }
    }
    Row(Modifier.fillMaxWidth().heightIn(min = 48.dp), verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(8.dp)) {
        IconButton(onClick = dictation.cancel, modifier = Modifier.size(28.dp)) { TablerIcon(R.drawable.ic_x, "Cancel dictation", Modifier.size(16.dp)) }
        Box(Modifier.weight(1f)) {
            when (state.phase) {
                DictationPhase.ERROR -> Text(state.error.orEmpty(), Modifier.semantics { liveRegion = LiveRegionMode.Polite }, color = p.destructive, style = MaterialTheme.typography.bodyMedium)
                DictationPhase.REQUESTING -> Text("Waiting for microphone permission…", Modifier.semantics { liveRegion = LiveRegionMode.Polite }, color = p.mutedForeground)
                else ->
                    Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                        val description = if (state.phase == DictationPhase.TRANSCRIBING)"Transcribing…" else "Listening"
                        Canvas(
                            Modifier.weight(1f).height(28.dp).semantics {
                                contentDescription = description
                                liveRegion = LiveRegionMode.Polite
                            },
                        ) {
                            val width = size.width / 24
                            levels.forEachIndexed { index, level ->
                                val height = maxOf(2.dp.toPx(), level * size.height)
                                drawRoundRect(p.foreground, Offset(index * width, (size.height - height) / 2), Size(maxOf(1f, width - 2.dp.toPx()), height), CornerRadius(1.dp.toPx()))
                            }
                        }
                        Text(String.format(Locale.ROOT, "%d:%02d", state.seconds / 60, state.seconds % 60), Modifier.semantics { contentDescription = "Recording duration" }, style = MaterialTheme.typography.bodySmall, color = p.mutedForeground)
                    }
            }
        }
        if (state.phase == DictationPhase.ERROR) {
            OpenBotTextButton(onClick = { if (state.canRetry)scope.launch { dictation.session.retry() } else dictation.start() }) { Text(if (state.canRetry)"Retry" else "Record again") }
        } else {
            IconButton(onClick = { scope.launch { dictation.session.finish() } }, enabled = state.phase == DictationPhase.RECORDING, modifier = Modifier.size(28.dp)) { TablerIcon(R.drawable.ic_player_stop, "Stop and transcribe", Modifier.size(16.dp)) }
            IconButton(onClick = { scope.launch { dictation.session.finish(DictationIntent.SEND) } }, enabled = state.phase == DictationPhase.RECORDING && canSend, modifier = Modifier.size(28.dp)) {
                if (state.phase == DictationPhase.TRANSCRIBING) {
                    CircularProgressIndicator(Modifier.size(16.dp), strokeWidth = 2.dp)
                } else {
                    TablerIcon(R.drawable.ic_arrow_up, "Transcribe and send", Modifier.size(16.dp))
                }
            }
        }
    }
}
}

