object AS_Mcp {
const val MCP_VERSION = "2025-11-25"
val MCP_HTTP_VERSIONS = setOf(MCP_VERSION, "2025-06-18", "2025-03-26")

@Serializable data class McpTool(
    val name: String,
    val description: String = "",
