// ===== ORIGINAL RUNTIME FILE: android/core/src/main/kotlin/ai/openbot/core/NotificationDestination.kt =====
object AS_NotificationDestination {
sealed interface NotificationDestination {
    data object NeedsYou : NotificationDestination

    data class Conversation(
        val channelId: String,
        val requestId: String? = null,
    ) : NotificationDestination

    data class Approvals(
        val channelId: String,
        val requestId: String? = null,
    ) : NotificationDestination
}

/** Strict route parser translated from mobile/src/links.ts; it never opens arbitrary URIs. */
fun notificationDestination(value: String?): NotificationDestination? {
    val uri = value?.let { runCatching { URI(it) }.getOrNull() } ?: return null
    if (!uri.scheme.equals("openbotmobile", ignoreCase = true) || !uri.rawUserInfo.isNullOrEmpty() ||
        !uri.rawFragment.isNullOrEmpty() || uri.port != -1 || uri.path !in listOf("", "/")
    ) {
        return null
    }
    val host = uri.host?.lowercase() ?: return null
    if (host == "needs-you") return if (uri.rawQuery.isNullOrEmpty()) NotificationDestination.NeedsYou else null
    if (host !in listOf("conversation", "approvals")) return null
    val params =
        runCatching {
            uri.rawQuery.orEmpty().split('&').map {
                val parts = it.split('=', limit = 2)
                URLDecoder.decode(parts[0], "UTF-8") to URLDecoder.decode(parts.getOrElse(1) { "" }, "UTF-8")
            }
        }.getOrNull() ?: return null
    val channel = params.firstOrNull { it.first == "channelId" }?.second ?: return null
    val request = params.firstOrNull { it.first == "requestId" }?.second?.takeIf { it.isNotEmpty() }
    if (channel.isEmpty() || channel.length > 200 || (request?.length ?: 0) > 200) return null
    return if (host == "conversation") {
        NotificationDestination.Conversation(channel, request)
    } else {
        NotificationDestination.Approvals(channel, request)
    }
}
}

// ===== ORIGINAL RUNTIME FILE: android/core/src/main/kotlin/ai/openbot/core/OklchColor.kt =====
object AS_OklchColor {
/** CSS Color 4 OKLCH → sRGB, used to carry app/src/theme.css tokens into Compose. */
fun oklchArgb(
    lightness: Double,
    chroma: Double,
    hue: Double,
    alpha: Double = 1.0,
): Int {
    val radians = hue * PI / 180
    val a = chroma * cos(radians)
    val b = chroma * sin(radians)
    val l = (lightness + 0.3963377774 * a + 0.2158037573 * b).pow(3)
    val m = (lightness - 0.1055613458 * a - 0.0638541728 * b).pow(3)
    val s = (lightness - 0.0894841775 * a - 1.2914855480 * b).pow(3)

    fun encode(value: Double): Int {
        val srgb = if (value <= 0.0031308) 12.92 * value else 1.055 * value.pow(1.0 / 2.4) - 0.055
        return (srgb.coerceIn(0.0, 1.0) * 255).roundToInt()
    }
    val red = encode(4.0767416621 * l - 3.3077115913 * m + 0.2309699292 * s)
    val green = encode(-1.2684380046 * l + 2.6097574011 * m - 0.3413193965 * s)
    val blue = encode(-0.0041960863 * l - 0.7034186147 * m + 1.7076147010 * s)
    return ((alpha.coerceIn(0.0, 1.0) * 255).roundToInt() shl 24) or (red shl 16) or (green shl 8) or blue
}
}

// ===== ORIGINAL RUNTIME FILE: android/core/src/main/kotlin/ai/openbot/core/Prompt.kt =====
object AS_Prompt {
/** Local inference context is deliberately bounded for phone memory and model context limits. */
data class LocalPromptContext(
    val text: String,
    val messageIds: List<String>,
)

fun localPrompt(
    bot: LocalBot,
    memories: List<Memory>,
    history: List<LocalMessage>,
    maximumCharacters: Int = 64000,
    toolNames: List<String> = emptyList(),
    toolEvents: List<LocalToolEvent> = emptyList(),
): String = localPromptContext(bot, memories, history, maximumCharacters, toolNames, toolEvents).text

fun localPromptContext(
    bot: LocalBot,
    memories: List<Memory>,
    history: List<LocalMessage>,
    maximumCharacters: Int = 64000,
    toolNames: List<String> = emptyList(),
    toolEvents: List<LocalToolEvent> = emptyList(),
): LocalPromptContext {
    require(!bot.paused) { "This Bot is paused. Resume it before sending a message." }
    val lastUser =
        history.lastOrNull { it.role == "user" && it.state == MessageState.COMPLETE }
            ?: error("A user message is required.")
    val instruction = bot.instruction
    val facts = quoteMemoryContext(memories.filter { it.enabled && (it.formedBy != FormedBy.BOT || it.formedByAgentId == bot.id) })
    val prefix =
        buildString {
            appendLine(instruction)
            appendLine("The OpenBot backend runs on this Android device. Computer use is unavailable.")
            if (toolNames.isEmpty()) {
                appendLine("No tools or connected apps are available for this turn. Never claim to have taken an action.")
            } else {
                appendLine("Available tools: ${toolNames.joinToString()}. Use the supplied tools to take actions; only report success after a successful result. No other tools or connected apps are available. The person’s timezone is ${java.time.ZoneId.systemDefault().id}.")
            }
            if (facts.isNotEmpty()) appendLine(facts)
            if (toolEvents.isNotEmpty())appendLine(quoteToolContext(toolEvents))
        }
    val current = "Person: ${lastUser.text}\nBot:"
    require(prefix.length + current.length + 100 <= maximumCharacters) {
        "The instructions, enabled memory and message exceed this model's context budget. Choose a larger model context or reduce them. Nothing was sent."
    }
    var remaining = maximumCharacters - prefix.length - current.length - 100
    val prior =
        history
            .takeWhile { it.id != lastUser.id }
            .filter { it.state == MessageState.COMPLETE && it.role in listOf("user", "assistant") }
    val selected = mutableListOf<String>()
    val selectedIds = mutableListOf<String>()
    for (message in prior.asReversed()) {
        val line = "${if (message.role == "user") "Person" else "Bot"}: ${message.text}"
        if (line.length + 1 > remaining) break
        selectedIds.add(message.id)
        selected.add(line)
        remaining -= line.length + 1
    }
    val previous = selected.asReversed().joinToString("\n")
    val text =
        buildString {
            append(prefix)
            if (selected.size < prior.size) appendLine("Earlier messages were omitted to fit the model's context budget.")
            if (previous.isNotEmpty()) {
                appendLine("Earlier conversation:")
                appendLine(previous)
            }
            append(current)
        }
    return LocalPromptContext(text, selectedIds.asReversed() + lastUser.id)
}
}

// ===== ORIGINAL RUNTIME FILE: android/core/src/main/kotlin/ai/openbot/core/ProviderStream.kt =====
object AS_ProviderStream {
/** SSE event framing is independent of socket chunks and ignores comments/heartbeats. */
class ServerSentEvents {
    private val data = StringBuilder()
    private var hasData = false

    fun line(line: String): String? {
        if (line.isEmpty()) {
            val event = data.toString().takeIf { hasData }
            data.clear()
            hasData = false
            return event
        }
        if (line.startsWith(":")) return null
        val field = line.substringBefore(':')
        if (field == "data") {
            if (hasData) data.append('\n')
            data.append(line.substringAfter(':', "").removePrefix(" "))
            hasData = true
            check(data.length <= 2 * 1024 * 1024) { "The streamed event was too large." }
        }
        return null
    }
}

/** Assemble complete tool calls before AgentProtocol may inspect or execute any of them. */
class ProviderStream(
    private val style: ApiStyle,
) {
    private data class FunctionParts(
        val id: StringBuilder = StringBuilder(),
        val name: StringBuilder = StringBuilder(),
        val arguments: StringBuilder = StringBuilder(),
    )

    private val tools = sortedMapOf<Int, FunctionParts>()
    private val text = StringBuilder()
    private var reason: String? = null
    private var response: JsonObject? = null
    private var done = false
    val visibleText: String get() = text.toString()

    /** True only when the wire protocol has supplied its successful terminal event. */
    fun accept(data: String): Boolean {
        check(!done) { "The model sent data after its final response." }
        if (data == "[DONE]") {
            check(style == ApiStyle.CHAT_COMPLETIONS && reason != null) { "The model stream ended before its answer was complete; no tools were executed." }
            check(tools.isEmpty() || reason == "tool_calls") { "The model stream ended with incomplete tool calls." }
            response =
                buildJsonObject {
                    putJsonArray("choices") {
                        addJsonObject {
                            put("finish_reason", reason)
                            putJsonObject("message") {
                                put("role", "assistant")
                                put("content", text.toString())
                                if (tools.isNotEmpty()) {
                                    putJsonArray("tool_calls") {
                                        tools.values.forEach { parts ->
                                            addJsonObject {
                                                put("id", parts.id.toString())
                                                put("type", "function")
                                                putJsonObject("function") {
                                                    put("name", parts.name.toString())
                                                    put("arguments", parts.arguments.toString())
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            done = true
            return true
        }
        val event =
            runCatching { Json.parseToJsonElement(data).jsonObject }.getOrElse {
                error("The model sent a malformed streamed event; no tools were executed.")
            }
        check(!event.containsKey("error")) { "The model provider reported a streaming error." }
        if (style == ApiStyle.RESPONSES) {
            when (event["type"]?.jsonPrimitive?.contentOrNull) {
                "error", "response.failed", "response.incomplete" -> error("The model stream failed or was incomplete; no tools were executed.")
                "response.output_text.delta" -> append(event["delta"]?.jsonPrimitive?.contentOrNull.orEmpty())
                "response.completed" -> {
                    val final = event["response"] as? JsonObject ?: error("The model sent no completed response.")
                    check(final["status"]?.jsonPrimitive?.contentOrNull == "completed") { "The model response was incomplete; no tools were executed." }
                    response = final
                    done = true
                }
            }
        } else {
            val choices = event["choices"] as? JsonArray ?: error("The model sent an invalid streaming choice.")
            if (choices.isEmpty()) return false // Optional usage-only chunk.
            check(choices.size == 1) { "The model sent multiple streaming choices." }
            val choice = choices.single().jsonObject
            check(choice["index"]?.jsonPrimitive?.intOrNull == 0) { "The model sent an unexpected streaming choice." }
            val delta = choice["delta"] as? JsonObject ?: JsonObject(emptyMap())
            check(reason == null) { "The model sent content after finishing its answer." }
            check(delta["refusal"]?.jsonPrimitive?.contentOrNull.isNullOrEmpty()) { "The model provider declined this answer." }
            append(delta["content"]?.jsonPrimitive?.contentOrNull.orEmpty())
            (delta["tool_calls"] as? JsonArray).orEmpty().forEach { item ->
                val part = item.jsonObject
                val index = part["index"]?.jsonPrimitive?.intOrNull ?: error("The model sent a tool call without an index.")
                check(index in 0..31) { "The model sent too many tool calls." }
                val target = tools.getOrPut(index) { FunctionParts() }
                target.id.append(part["id"]?.jsonPrimitive?.contentOrNull.orEmpty())
                val function = part["function"] as? JsonObject
                target.name.append(
                    function
                        ?.get("name")
                        ?.jsonPrimitive
                        ?.contentOrNull
                        .orEmpty(),
                )
                target.arguments.append(
                    function
                        ?.get("arguments")
                        ?.jsonPrimitive
                        ?.contentOrNull
                        .orEmpty(),
                )
                check(target.arguments.length <= 256_000 && target.name.length <= 256 && target.id.length <= 256) { "The streamed tool call was too large." }
            }
            choice["finish_reason"]?.jsonPrimitive?.contentOrNull?.let {
                check(it in setOf("stop", "tool_calls")) { "The model response was incomplete; no tools were executed." }
                reason = it
            }
        }
        return done
    }

    private fun append(value: String) {
        check(text.length + value.length <= 128_000) { "The streamed answer was too large." }
        text.append(value)
    }

    fun finish(): JsonObject {
        check(done) { "The model stream disconnected before its answer was complete; no tools were executed." }
        return requireNotNull(response)
    }
}
}

// ===== ORIGINAL RUNTIME FILE: android/core/src/main/kotlin/ai/openbot/core/Questions.kt =====
object AS_Questions {
@Serializable data class QuestionPart(
    val header: String,
    val question: String,
    val options: List<String> = emptyList(),
)

@Serializable data class LocalQuestion(
    val id: String,
    val turnId: String,
    val channelId: String,
    val botId: String,
    val call: ToolCall,
    val question: String,
    val why: String? = null,
    val parts: List<QuestionPart> = emptyList(),
    val createdAt: String,
    val answer: String? = null,
)

val askPersonTool: AgentTool by lazy {
    val source = Json.parseToJsonElement(requireNotNull(AgentStudioResources.open("/question-tool.json")).bufferedReader().use { it.readText() }).jsonObject
    AgentTool(source["name"]!!.jsonPrimitive.content, source["description"]!!.jsonPrimitive.content, source["inputSchema"]!!.jsonObject)
}

fun parseQuestion(call: ToolCall): Triple<String, String?, List<QuestionPart>> {
    require(call.name == askPersonTool.name)
    validateToolArguments(askPersonTool, call.arguments)
    val question =
        call.arguments["question"]!!
            .jsonPrimitive.content
            .trim()
    require(question.isNotEmpty() && question.length <= 6000) { "Say what you need a person to answer, in 1–6000 characters." }
    val why =
        call.arguments["why"]
            ?.jsonPrimitive
            ?.content
            ?.trim()
    require(why == null || why.length <= 6000) { "Explain why in at most 6000 characters." }
    val parts =
        call.arguments["parts"]
            ?.jsonArray
            ?.map { element ->
                val part = element.jsonObject
                QuestionPart(
                    part["header"]!!.jsonPrimitive.content.trim(),
                    part["question"]!!.jsonPrimitive.content.trim(),
                    part["options"]?.jsonArray?.map { it.jsonPrimitive.content.trim() }.orEmpty(),
                ).also {
                    require(it.header.isNotEmpty() && it.header.length <= 40 && it.question.isNotEmpty() && it.question.length <= 500)
                    require(it.options.size <= 6 && it.options.all { option -> option.isNotEmpty() && option.length <= 120 })
                }
            }.orEmpty()
    require(parts.size <= 6 && (call.arguments["parts"] == null || parts.isNotEmpty()))
    return Triple(question, why, parts)
}

fun questionResponseMessage(
    question: String,
    response: String,
) = "In response to your question: $question\n\n$response"

fun partsAnswer(
    parts: List<QuestionPart>,
    selected: List<String>,
    typed: List<String>,
): String {
    require(parts.isNotEmpty() && selected.size == parts.size && typed.size == parts.size)
    return parts
        .mapIndexed { index, part ->
            val values = listOf(selected[index].trim(), typed[index].trim()).filter { it.isNotEmpty() }
            require(values.isNotEmpty()) { "Answer each question before sending." }
            "${part.header}: ${values.joinToString(", ") }"
        }.joinToString("\n")
}
}

