@Composable private fun AgentStudioExperience(
    modifier: Modifier,onBack: (() -> Unit)?,notificationUri: String?,onNotificationConsumed: () -> Unit,initialAgentId: String?,displayName: String,
) {
    val root=AgentStudioProfiles.root(androidx.compose.ui.platform.LocalContext.current)
    val revision by AgentStudioProfiles.revision.collectAsState()
    var agents by remember{mutableStateOf<List<AgentStudioProfile>>(emptyList())}
    var loading by remember{mutableStateOf(true)}
    val latestNotification by rememberUpdatedState(notificationUri)
    var error by remember{mutableStateOf<String?>(null)}
    var selected by rememberSaveable{mutableStateOf(initialAgentId)}
    var selectedDark by remember{mutableStateOf<Boolean?>(null)}
    var creating by rememberSaveable{mutableStateOf(false)}
    var editing by remember{mutableStateOf<AgentStudioProfile?>(null)}
    val scope=rememberCoroutineScope()
    val session:AgentStudioFeatureSession=viewModel(key="agentstudio-profile-session")
    val agentPages=rememberSaveableStateHolder()
    val activityResultOwner=androidx.activity.compose.LocalActivityResultRegistryOwner.current
    val backOwner=androidx.activity.compose.LocalOnBackPressedDispatcherOwner.current
    LaunchedEffect(revision) {
        try{agents=withContext(Dispatchers.IO){AgentStudioProfiles.list(root)};error=null}
        catch(failure:Exception){error=failure.message?:"Could not load your agents."}
        finally{loading=false}
    }
    LaunchedEffect(initialAgentId){if(initialAgentId!=null)selected=initialAgentId}
    val profile=agents.firstOrNull{it.id==selected}
    AS_OpenBotTheme.OpenBotTheme(if(profile==null)false else selectedDark?:false) {
        AS_SourceDialogHost.SourceDialogHost {
            Surface(modifier.fillMaxSize(),color=LocalOpenBotPalette.current.background) {
                if(profile==null) {
                    androidx.activity.compose.BackHandler(enabled=onBack!=null){onBack?.invoke()}
                    AgentStudioGallery(agents,loading,error,displayName,{selected=it.id},{creating=true})
                } else agentPages.SaveableStateProvider("agent:"+profile.id) { key(profile.id) {
                    val context=remember(root,profile.id){AgentStudioProfiles.context(root,profile.id)}
                    CompositionLocalProvider(androidx.compose.ui.platform.LocalContext provides context,
                        androidx.lifecycle.viewmodel.compose.LocalViewModelStoreOwner provides session.owner(profile.id),
                        androidx.activity.compose.LocalActivityResultRegistryOwner provides requireNotNull(activityResultOwner),
                        androidx.activity.compose.LocalOnBackPressedDispatcherOwner provides requireNotNull(backOwner)) {
                        AgentStudioAgentPage(profile,{selected=null},{editing=profile},notificationUri,{if(latestNotification==notificationUri)onNotificationConsumed()},{selectedDark=it},{
                            scope.launch {
                                try {
                                    val owner=session.owner(profile.id)
                                    val provider=androidx.lifecycle.ViewModelProvider(owner)
                                    val vm=provider[AS_OpenBotViewModel.OpenBotViewModel::class.java]
                                    session.remove(profile.id)
                                    vm.awaitFeatureClosed()
                                    withContext(Dispatchers.IO){AgentStudioProfiles.delete(root,profile.id)}
                                    selected=null
                                    agentPages.removeState("agent:"+profile.id)
                                }catch(failure:Exception){error=failure.message?:"Could not delete this agent."}
                            }
                        })
                    }
                } }
            }
            if(creating||editing!=null) CompositionLocalProvider(LocalAgentStudioCreating provides true) { AgentStudioCreateAgent(editing,{creating=false;editing=null}){id,name,instruction,shape,color->
                val profile=(editing?:AgentStudioProfile(id,name,instruction)).copy(name=name,instruction=instruction,shape=shape,color=color)
                withContext(Dispatchers.IO){AgentStudioProfiles.save(root,profile)}
                creating=false;editing=null;selected=profile.id
            } }
        }
    }
}

@Composable private fun AgentStudioGallery(agents: List<AgentStudioProfile>,loading: Boolean,error: String?,displayName: String,onOpen: (AgentStudioProfile)->Unit,onCreate: ()->Unit) {
    var searching by rememberSaveable{mutableStateOf(false)}
    var query by rememberSaveable{mutableStateOf("")}
    val visible=agents.filter{it.name.contains(query.trim(),true)}
    Column(Modifier.fillMaxSize().padding(horizontal=20.dp)) {
        Row(Modifier.fillMaxWidth().padding(top=16.dp,bottom=24.dp),verticalAlignment=androidx.compose.ui.Alignment.CenterVertically,horizontalArrangement=Arrangement.spacedBy(12.dp)) {
            Surface(shape=androidx.compose.foundation.shape.CircleShape,color=androidx.compose.ui.graphics.Color.White,shadowElevation=4.dp,modifier=Modifier.size(48.dp)){
                Box(contentAlignment=androidx.compose.ui.Alignment.Center){Text(displayName.split(' ').mapNotNull{it.firstOrNull()?.toString()}.take(2).joinToString("").ifEmpty{"You"},fontSize=14.sp)}
            }
            Spacer(Modifier.weight(1f))
            AgentStudioRoundButton("Search agents","⌕",{searching=!searching})
            AgentStudioRoundButton("Create agent","+",onCreate,Modifier.testTag("create-agent"))
        }
        if(searching) SourceTextField(query,{query=it},singleLine=true,placeholder={Text("Search agents")},modifier=Modifier.fillMaxWidth().padding(bottom=12.dp).testTag("search-agents"))
        when {
            loading->Box(Modifier.fillMaxSize(),contentAlignment=androidx.compose.ui.Alignment.Center){CircularProgressIndicator()}
            error!=null->Box(Modifier.fillMaxSize(),contentAlignment=androidx.compose.ui.Alignment.Center){Text(error,color=androidx.compose.ui.graphics.Color(0xffb3261e))}
            agents.isEmpty()->Box(Modifier.fillMaxSize(),contentAlignment=androidx.compose.ui.Alignment.Center){
                Button(onClick=onCreate,modifier=Modifier.fillMaxWidth(.78f).height(60.dp).testTag("make-an-agent"),shape=RoundedCornerShape(30.dp),colors=ButtonDefaults.buttonColors(containerColor=androidx.compose.ui.graphics.Color.Black)){
                    Text("Make an agent",fontSize=18.sp,color=androidx.compose.ui.graphics.Color.White)
                }
            }
            visible.isEmpty()->Box(Modifier.fillMaxSize(),contentAlignment=androidx.compose.ui.Alignment.Center){Text("No agents match your search.")}
            else->androidx.compose.foundation.lazy.LazyColumn(Modifier.fillMaxSize(),verticalArrangement=Arrangement.spacedBy(6.dp),contentPadding=PaddingValues(bottom=24.dp)) {
                item {
                    androidx.compose.foundation.lazy.LazyRow(Modifier.fillMaxWidth().padding(bottom=24.dp),horizontalArrangement=Arrangement.spacedBy(20.dp)) {
                        items(visible.sortedByDescending{it.pinned}.take(3),key={it.id}){agent->
                            Column(Modifier.width(96.dp).clickable{onOpen(agent)}.semantics{contentDescription="Favorite ${agent.name}"},horizontalAlignment=androidx.compose.ui.Alignment.CenterHorizontally,verticalArrangement=Arrangement.spacedBy(10.dp)) {
                                AgentStudioMascot(agent.shape,agent.color,Modifier.size(88.dp))
                                Text(agent.name,maxLines=1,overflow=androidx.compose.ui.text.style.TextOverflow.Ellipsis,fontSize=13.sp,color=androidx.compose.ui.graphics.Color(0xff696969))
                            }
                        }
                    }
                }
                items(visible,key={it.id}){agent->
                    Row(Modifier.fillMaxWidth().clickable{onOpen(agent)}.padding(vertical=12.dp).testTag("agent-${agent.id}"),verticalAlignment=androidx.compose.ui.Alignment.CenterVertically,horizontalArrangement=Arrangement.spacedBy(12.dp)) {
                        AgentStudioMascot(agent.shape,agent.color,Modifier.size(52.dp))
                        Column(Modifier.weight(1f),verticalArrangement=Arrangement.spacedBy(5.dp)) {
                            Text(agent.name,fontSize=16.sp,fontWeight=androidx.compose.ui.text.font.FontWeight.Medium,maxLines=1,overflow=androidx.compose.ui.text.style.TextOverflow.Ellipsis)
                            Text(agent.preview.ifBlank{"Start a conversation"},fontSize=13.sp,color=androidx.compose.ui.graphics.Color(0xff727272),maxLines=1,overflow=androidx.compose.ui.text.style.TextOverflow.Ellipsis)
                        }
                        if(agent.preview.isNotBlank())Text(runCatching{java.time.Instant.parse(agent.updatedAt).atZone(java.time.ZoneId.systemDefault()).format(java.time.format.DateTimeFormatter.ofPattern("h:mm a"))}.getOrDefault(""),fontSize=11.sp,color=androidx.compose.ui.graphics.Color(0xff727272))
                    }
                }
            }
        }
    }
}

@Composable private fun AgentStudioCreateAgent(existing: AgentStudioProfile?,onDismiss: ()->Unit,onSave: suspend(String,String,String,Int,Long)->Unit) {
    val draftId=rememberSaveable(existing?.id){existing?.id?:java.util.UUID.randomUUID().toString()}
    var name by rememberSaveable(existing?.id){mutableStateOf(existing?.name.orEmpty())}
    var instruction by rememberSaveable(existing?.id){mutableStateOf(existing?.instruction.orEmpty())}
    var shape by rememberSaveable(existing?.id){mutableStateOf(existing?.shape?:6)}
    var color by rememberSaveable(existing?.id){mutableStateOf(existing?.color?:0xffff6b00L)}
    var step by rememberSaveable(existing?.id){mutableStateOf(0)}
    var saving by remember{mutableStateOf(false)}
    var error by remember{mutableStateOf<String?>(null)}
    val scope=rememberCoroutineScope()
    val colors=listOf(0xffffffffL,0xff9b642eL,0xffff2851L,0xffff6b00L,0xffffa000L,0xff00c779L,0xff05b8aaL,0xff168affL,0xff9251ffL,0xffff2a9bL,0xff7b7b7bL)
    val shapes=listOf("Circle","Bean","Squircle","Pill","Triangle","Hexagon","Flower","Drop")
    val colorNames=listOf("White","Brown","Rose","Orange","Amber","Green","Turquoise","Blue","Purple","Pink","Gray")
    SourceDialog(if(existing==null)"Create New Agent" else "Edit ${existing.name}",{if(!saving)onDismiss()}) {
        Column(Modifier.fillMaxWidth().heightIn(max=580.dp),verticalArrangement=Arrangement.spacedBy(16.dp)) {
            Column(Modifier.weight(1f,fill=false).fillMaxWidth().verticalScroll(rememberScrollState()),horizontalAlignment=androidx.compose.ui.Alignment.CenterHorizontally,verticalArrangement=Arrangement.spacedBy(16.dp)) {
                AgentStudioMascot(shape,color,Modifier.size(if(step==0)128.dp else 72.dp))
                if(step==0) {
                    SourceTextField(name,{if(it.length<=80)name=it},singleLine=true,placeholder={Text("Agent name")},enabled=!saving,modifier=Modifier.fillMaxWidth().testTag("agent-name"))
                    Text("Choose a mascot",style=MaterialTheme.typography.titleSmall)
                    for(row in 0..1)Row(horizontalArrangement=Arrangement.spacedBy(12.dp)){
                        for(column in 0..3){val candidate=row*4+column
                            Surface(onClick={shape=candidate},enabled=!saving,shape=RoundedCornerShape(14.dp),color=if(shape==candidate)androidx.compose.ui.graphics.Color(0xffdedede)else androidx.compose.ui.graphics.Color.Transparent,
                                modifier=Modifier.size(52.dp).testTag("mascot-shape-$candidate").semantics{contentDescription="Mascot shape: "+shapes[candidate];selected=shape==candidate}){
                                Box(contentAlignment=androidx.compose.ui.Alignment.Center){AgentStudioMascot(candidate,color,Modifier.size(40.dp))}
                            }
                        }
                    }
                    for(row in colors.chunked(6))Row(horizontalArrangement=Arrangement.spacedBy(4.dp)){
                        row.forEach{candidate->
                            Surface(onClick={color=candidate},enabled=!saving,shape=androidx.compose.foundation.shape.CircleShape,color=if(color==candidate)androidx.compose.ui.graphics.Color(0xffdedede)else androidx.compose.ui.graphics.Color.Transparent,
                                modifier=Modifier.size(44.dp).testTag("mascot-color-${candidate.toString(16)}").semantics{contentDescription="Mascot color: "+colorNames[colors.indexOf(candidate)];selected=color==candidate}){
                                Box(contentAlignment=androidx.compose.ui.Alignment.Center){Box(Modifier.size(28.dp).background(androidx.compose.ui.graphics.Color(candidate.toInt()),androidx.compose.foundation.shape.CircleShape).border(1.dp,androidx.compose.ui.graphics.Color(0xffdddddd),androidx.compose.foundation.shape.CircleShape))}
                            }
                        }
                    }
                } else {
                    Text(name,style=MaterialTheme.typography.titleMedium)
                    Text("Give this agent its own instructions",style=MaterialTheme.typography.titleSmall)
                    SourceTextField(instruction,{if(it.length<=1000)instruction=it},minLines=5,maxLines=8,placeholder={Text("What should this agent do? Include its role, priorities and how it should answer.")},enabled=!saving,modifier=Modifier.fillMaxWidth().testTag("agent-instructions"))
                    Text("${instruction.length}/1000 · These instructions, chats and settings belong only to this agent.",style=MaterialTheme.typography.bodySmall)
                    error?.let{Text(it,color=androidx.compose.ui.graphics.Color(0xffb3261e))}
                }
            }
            if(step==0)Button(onClick={step=1},enabled=name.isNotBlank()&&!saving,modifier=Modifier.fillMaxWidth().height(50.dp).testTag("agent-next"),colors=ButtonDefaults.buttonColors(containerColor=androidx.compose.ui.graphics.Color.Black)){Text("Next")}
            else Row(horizontalArrangement=Arrangement.spacedBy(12.dp)) {
                TextButton(onClick={step=0},enabled=!saving){Text("Back")}
                Button(onClick={scope.launch{saving=true;error=null;try{onSave(draftId,name,instruction,shape,color)}catch(failure:Exception){error=failure.message?:"Could not save this agent."}finally{saving=false}}},enabled=name.isNotBlank()&&instruction.isNotBlank()&&!saving,modifier=Modifier.weight(1f).height(50.dp).testTag("save-agent"),colors=ButtonDefaults.buttonColors(containerColor=androidx.compose.ui.graphics.Color.Black)){Text(if(saving)"Saving…" else if(existing==null)"Create" else "Save")}
            }
        }
    }
}

@Composable private fun AgentStudioAgentPage(agent: AgentStudioProfile,onHome: ()->Unit,onEdit: ()->Unit,notificationUri: String?,onNotificationConsumed: ()->Unit,onTheme: (Boolean?)->Unit,onDelete: ()->Unit) {
    val context=androidx.compose.ui.platform.LocalContext.current as AgentStudioScopedApplication
    val scope=rememberCoroutineScope()
    val factory=remember(context){viewModelFactory{initializer{AS_OpenBotViewModel.OpenBotViewModel(context)}}}
    val vm:AS_OpenBotViewModel.OpenBotViewModel=viewModel(factory=factory)
    val state by vm.ui.collectAsStateWithLifecycle()
    var route by rememberSaveable(agent.id){mutableStateOf("Chat")}
    var menu by remember{mutableStateOf(false)}
    var history by remember{mutableStateOf(false)}
    var confirmingDelete by remember{mutableStateOf(false)}
    var notificationNotice by remember{mutableStateOf<String?>(null)}
    val pages=rememberSaveableStateHolder()
    val importModel=rememberLauncherForActivityResult(ActivityResultContracts.OpenDocument()){uri->uri?.let(vm::importModel)}
    val permission=rememberLauncherForActivityResult(ActivityResultContracts.RequestPermission()){allowed->vm.savePreferences(state.preferences.copy(notificationsEnabled=allowed));notificationNotice=if(allowed)null else "Notifications are off. You can enable them in Android settings."}
    val bot=state.bots.find{it.id==agent.id}
    LaunchedEffect(state.preferences.darkTheme){onTheme(state.preferences.darkTheme)}
    LaunchedEffect(state.busy,agent.id) {
        if(!state.busy&&bot!=null&&state.selectedConversation==null&&state.draftBotId==null) {
            state.conversations.firstOrNull()?.let{vm.openConversation(it.id)}?:vm.newConversation(agent.id)
        }
    }
    LaunchedEffect(notificationUri,state.busy) {
        if(notificationUri!=null&&!state.busy) {
            val target=notificationDestination(notificationUri)
            if(target!=null) {
                while(!vm.openNotification(target){opened->if(opened){route=if(target is NotificationDestination.Approvals)"Approvals"else"Chat"};onNotificationConsumed()}) kotlinx.coroutines.delay(50)
            } else onNotificationConsumed()
        }
    }
    LaunchedEffect(state.conversations) {
        state.conversations.maxByOrNull{it.lastMessageAt?:it.createdAt}?.let{channel->
            if(channel.lastMessage!=null&&channel.lastMessageAt!=null)withContext(Dispatchers.IO){AgentStudioProfiles.preview(context,agent.id,channel.lastMessage,channel.lastMessageAt)}
        }
    }
    androidx.activity.compose.BackHandler{if(route!="Chat")route="Chat"else onHome()}
    Column(Modifier.fillMaxSize().imePadding()) {
        Row(Modifier.fillMaxWidth().padding(horizontal=16.dp,vertical=12.dp),verticalAlignment=androidx.compose.ui.Alignment.CenterVertically,horizontalArrangement=Arrangement.spacedBy(10.dp)) {
            AgentStudioRoundButton("Back","‹",{if(route!="Chat")route="Chat"else onHome()},Modifier.testTag("agent-back"))
            Surface(shape=RoundedCornerShape(26.dp),color=androidx.compose.ui.graphics.Color.White,shadowElevation=3.dp,modifier=Modifier.weight(1f)){
                Row(Modifier.padding(horizontal=12.dp,vertical=10.dp),verticalAlignment=androidx.compose.ui.Alignment.CenterVertically,horizontalArrangement=Arrangement.spacedBy(8.dp)){
                    AgentStudioMascot(agent.shape,agent.color,Modifier.size(28.dp))
                    Text(if(route=="Chat")agent.name else route,maxLines=1,overflow=androidx.compose.ui.text.style.TextOverflow.Ellipsis,fontSize=15.sp)
                }
            }
            Box {
                AgentStudioRoundButton("Agent options","⋯",{menu=true},Modifier.testTag("agent-options"))
                DropdownMenu(menu,{menu=false}) {
                    listOf("Edit agent","New chat","Chat history","Memory","Skills","Routines","Goals","Connections","Approvals","Approval rules","Model settings","Dictation settings","Settings",if(bot?.paused==true)"Resume agent"else"Pause agent",if(agent.pinned)"Remove favorite"else"Add to favorites","Delete agent").forEach{option->
                        DropdownMenuItem(text={Text(option)},enabled=!state.busy,onClick={menu=false;when(option){"Edit agent"->onEdit();"New chat"->{vm.newConversation(agent.id);route="Chat"};"Chat history"->history=true;"Delete agent"->confirmingDelete=true;"Pause agent","Resume agent"->bot?.let{vm.setPaused(it,!it.paused)};"Add to favorites","Remove favorite"->{scope.launch { try { withContext(Dispatchers.IO){AgentStudioProfiles.save(context,agent.copy(pinned=!agent.pinned))} } catch(_:Exception) { notificationNotice="Could not update this favorite. Try again." } }};else->route=option}})
                    }
                }
            }
        }
        if(state.busy)LinearProgressIndicator(Modifier.fillMaxWidth().height(2.dp))
        state.error?.let{error->Row(Modifier.fillMaxWidth().padding(12.dp),verticalAlignment=androidx.compose.ui.Alignment.CenterVertically){Text(error,Modifier.weight(1f),color=androidx.compose.ui.graphics.Color(0xffb3261e));TextButton(onClick=vm::dismissError){Text("Dismiss")}}}
        Box(Modifier.weight(1f).fillMaxWidth()) {
            CompositionLocalProvider(LocalAgentStudioName provides agent.name,LocalAgentStudioChat provides true) {
                when(route) {
                    "Chat"->if(bot!=null)pages.SaveableStateProvider("chat:"+(state.selectedConversation?:state.draftSessionId?:agent.id)){AS_ConversationScreen.ConversationScreen(state,bot,vm)}else Box(Modifier.fillMaxSize(),contentAlignment=androidx.compose.ui.Alignment.Center){CircularProgressIndicator()}
                    "Memory"->AS_MemoryScreen.MemoryScreen(state,vm)
                    "Skills"->AS_CapabilitiesScreen.CapabilitiesScreen(state,vm)
                    "Routines"->AS_RoutinesScreen.RoutinesScreen(state,vm,agent.id)
                    "Goals"->AS_GoalsScreen.GoalsScreen(state,vm,agent.id)
                    "Connections"->AS_ConnectionsScreen.ConnectionsScreen(state,vm)
                    "Approvals"->AS_ApprovalsScreen.ApprovalsScreen(state,vm)
                    "Approval rules"->AS_ApprovalRulesScreen.ApprovalRulesScreen(state,vm)
                    "Model settings"->AS_ModelScreen.ModelScreen(state,vm,onDictation={route="Dictation settings"},onImport={importModel.launch(arrayOf("*/*"))})
                    "Dictation settings"->AS_DictationSettingsScreen.DictationSettingsScreen(state,vm)
                    "Settings"->AS_SettingsScreen.SettingsScreen(state,vm,{route="Model settings"},{route="Approval rules"},{enabled->if(enabled&&android.os.Build.VERSION.SDK_INT>=33)permission.launch(android.Manifest.permission.POST_NOTIFICATIONS)else vm.savePreferences(state.preferences.copy(notificationsEnabled=enabled))},notificationNotice)
                }
            }
        }
    }
    if(history) AgentStudioChatHistory(state,vm,{id->vm.openConversation(id);route="Chat";history=false},{history=false})
    if(confirmingDelete) SourceDialog("Delete ${agent.name}?",{confirmingDelete=false}) {
        Text("This deletes only this agent and its saved chats, memory, files, settings and keys.")
        Row(horizontalArrangement=Arrangement.End,modifier=Modifier.fillMaxWidth()){
            TextButton(onClick={confirmingDelete=false}){Text("Cancel")}
            Button(onClick={confirmingDelete=false;onDelete()},modifier=Modifier.testTag("delete-agent")){Text("Delete agent")}
        }
    }
}

private val LocalAgentStudioCreating=staticCompositionLocalOf{false}

@Composable private fun AgentStudioComposerBar(
    text:String,onChange:(String)->Unit,onSend:()->Unit,enabled:Boolean,modifier:Modifier,
    onStop:(()->Unit)?,stopping:Boolean,hasAttachments:Boolean,onAttach:(()->Unit)?,
    attachments:(@Composable ()->Unit)?,dictation:AS_DictationControls.DictationUi,
) {
    val dictating=dictation.state.phase!=DictationPhase.IDLE
    Column(modifier.fillMaxWidth(),verticalArrangement=Arrangement.spacedBy(8.dp)) {
        attachments?.invoke()
        Row(Modifier.fillMaxWidth().padding(vertical=6.dp),verticalAlignment=androidx.compose.ui.Alignment.CenterVertically,horizontalArrangement=Arrangement.spacedBy(10.dp)) {
            Surface(onClick={onAttach?.invoke()},enabled=enabled&&!dictating&&onAttach!=null,shape=androidx.compose.foundation.shape.CircleShape,color=LocalOpenBotPalette.current.card,shadowElevation=6.dp,modifier=Modifier.size(48.dp).semantics{contentDescription="Attach files"}) {
                Box(contentAlignment=androidx.compose.ui.Alignment.Center){Text("+",fontSize=28.sp)}
            }
            Surface(Modifier.weight(1f).heightIn(min=50.dp),shape=RoundedCornerShape(28.dp),color=LocalOpenBotPalette.current.card,shadowElevation=6.dp) {
                if(dictating) Box(Modifier.padding(horizontal=8.dp,vertical=4.dp)) {AS_DictationControls.RecordingControls(dictation,enabled)}
                else Row(Modifier.padding(start=16.dp,end=5.dp,top=4.dp,bottom=4.dp),verticalAlignment=androidx.compose.ui.Alignment.CenterVertically) {
                    androidx.compose.foundation.text.BasicTextField(text,onChange,enabled=enabled,maxLines=4,
                        textStyle=MaterialTheme.typography.bodyLarge.copy(color=LocalOpenBotPalette.current.foreground),
                        cursorBrush=androidx.compose.ui.graphics.SolidColor(LocalOpenBotPalette.current.foreground),
                        modifier=Modifier.weight(1f).padding(vertical=8.dp).semantics{contentDescription="Message"},
                        decorationBox={inner->Box{if(text.isEmpty())Text(LocalAgentStudioName.current?.let{"Ask $it"}?:"Ask anything",color=LocalOpenBotPalette.current.mutedForeground);inner()}})
                    if(onStop!=null)IconButton(onClick=onStop,enabled=!stopping,modifier=Modifier.size(40.dp)){AS_Components.TablerIcon(R.drawable.ic_player_stop,if(stopping)"Stopping…"else"Stop generating")}
                    else {
                        IconButton(onClick=dictation.start,enabled=enabled,modifier=Modifier.size(40.dp)){AS_Components.TablerIcon(R.drawable.ic_microphone,"Dictate a message")}
                        if(text.isNotBlank()||hasAttachments)IconButton(onClick=onSend,enabled=enabled,modifier=Modifier.size(40.dp)){AS_Components.TablerIcon(R.drawable.ic_arrow_up,"Send message")}
                    }
                }
            }
        }
    }
}

@Composable private fun AgentStudioChatHistory(state:AppState,vm:AS_OpenBotViewModel.OpenBotViewModel,onOpen:(String)->Unit,onClose:()->Unit) {
    var menu by remember{mutableStateOf<String?>(null)}
    var renaming by remember{mutableStateOf<LocalConversation?>(null)}
    var deleting by remember{mutableStateOf<LocalConversation?>(null)}
    var title by rememberSaveable{mutableStateOf("")}
    SourceDialog("Chat history",onClose) {
        if(state.conversations.isEmpty())Text("No conversations yet.")
        Column(Modifier.fillMaxWidth().heightIn(max=400.dp).verticalScroll(rememberScrollState())) {
            state.conversations.forEach{channel->
                Row(Modifier.fillMaxWidth().padding(vertical=8.dp),verticalAlignment=androidx.compose.ui.Alignment.CenterVertically){
                    Text(conversationTitle(channel),Modifier.weight(1f).clickable{onOpen(channel.id)},maxLines=2)
                    Box {
                        TextButton(onClick={menu=channel.id}){Text("⋯")}
                        DropdownMenu(menu==channel.id,{menu=null}){
                            DropdownMenuItem(text={Text(if(channel.pinned)"Unpin"else"Pin")},enabled=!state.busy,onClick={menu=null;vm.pinConversation(channel)})
                            DropdownMenuItem(text={Text("Rename")},enabled=!state.busy,onClick={menu=null;renaming=channel;title=channel.title?:conversationTitle(channel)})
                            DropdownMenuItem(text={Text("Delete")},enabled=!state.busy,onClick={menu=null;deleting=channel})
                        }
                    }
                }
            }
        }
    }
    renaming?.let { channel -> SourceDialog("Rename conversation",{renaming=null}) {
        Text("Leave it empty to restore the generated name.")
        SourceTextField(title,{if(it.length<=60)title=it},singleLine=true,enabled=!state.busy,modifier=Modifier.testTag("conversation-name"))
        Row(horizontalArrangement=Arrangement.End,modifier=Modifier.fillMaxWidth()) {
            TextButton(onClick={renaming=null},enabled=!state.busy){Text("Cancel")}
            Button(onClick={vm.renameConversation(channel,title){renaming=null}},enabled=!state.busy,modifier=Modifier.testTag("confirm-rename-conversation")){Text("Save")}
        }
    } }
    deleting?.let { channel -> SourceDialog("Delete conversation?",{deleting=null}) {
        Text("This deletes this conversation and its attached files from this agent.")
        Row(horizontalArrangement=Arrangement.End,modifier=Modifier.fillMaxWidth()) {
            TextButton(onClick={deleting=null},enabled=!state.busy){Text("Cancel")}
            Button(onClick={vm.deleteConversation(channel){deleting=null}},enabled=!state.busy,modifier=Modifier.testTag("confirm-delete-conversation")){Text("Delete")}
        }
    } }
}
